  ('cmsgcnaf1002umv7u8tqfm9ex', 'Estudar sem se afundar', 'em', 18, 'estudar-sem-se-afundar', 'O custo de estudar não é só a mensalidade', 2, ARRAY['bolsas', 'em13lf', 'ensino superior', 'ensino-medio', 'financiamento', 'permanencia', 'prouni'], NULL, 'intermediario', ARRAY['ensino_superior', 'dependentes'], 'em', NULL, NULL, false, 40, NULL, 40),
  ('cmsgcnayt0030mv7uud1tmv00', 'De onde vem a sua renda', 'em', 19, 'de-onde-vem-a-sua-renda', 'Estrutura, momento, escolhas e vínculo definem sua renda', 2, ARRAY['direitos', 'em13lf', 'ensino-medio', 'informalidade', 'renda', 'trabalho', 'vinculo'], NULL, 'intermediario', ARRAY['renda_variavel', 'primeiro_emprego'], 'em', NULL, NULL, false, 40, NULL, 40),
  ('cmsgcnbin0036mv7ur91o322s', 'Pensar como quem empreende', 'em', 20, 'pensar-como-quem-empreende', 'Testar pequeno, no emprego, no bairro ou no negócio próprio', 2, ARRAY['comunidade', 'em13lf', 'empreender', 'ensino-medio', 'negocio', 'risco', 'teste'], NULL, 'intermediario', ARRAY['renda_variavel'], 'em', NULL, NULL, false, 40, NULL, 40),
  ('cmsgcnc2g003cmv7ufhdnncg5', 'A conta do negócio', 'em', 21, 'a-conta-do-negocio', 'Receita, custo, margem: onde mexer para o lucro subir', 2, ARRAY['custos', 'em13lf', 'ensino-medio', 'margem', 'negocio', 'orcamento', 'sustentabilidade'], NULL, 'avancado', ARRAY['renda_variavel'], 'em', NULL, NULL, false, 50, NULL, 50),
  ('cmsgcncme003imv7ugx7tx3c3', 'Quem move a economia', 'em', 22, 'quem-move-a-economia', 'Quem produz, quem compra, quem regula — e onde você entra', 2, ARRAY['consumo', 'desigualdade', 'economia', 'em13lf', 'ensino-medio', 'governo', 'renda'], NULL, 'intermediario', ARRAY[]::TEXT[], 'em', NULL, NULL, false, 40, NULL, 40),
  ('cmsgcnd63003omv7uk6756ij0', 'Imposto, serviço público e você', 'em', 23, 'imposto-servico-publico-e-voce', 'Para onde vai o imposto e como você fiscaliza isso', 2, ARRAY['cidadania', 'em13lf', 'ensino-medio', 'impostos', 'servicos publicos', 'transparencia', 'tributos'], NULL, 'intermediario', ARRAY[]::TEXT[], 'em', NULL, NULL, false, 40, NULL, 40),
  ('cmsgcndpv003umv7ufeji4tc6', 'O termômetro da economia', 'em', 24, 'o-termometro-da-economia', 'Selic, inflação, câmbio e PIB no seu extrato', 2, ARRAY['cambio', 'economia', 'em13lf', 'ensino-medio', 'indicadores', 'inflacao', 'pib', 'selic'], NULL, 'avancado', ARRAY[]::TEXT[], 'em', NULL, NULL, false, 50, NULL, 50)
INSERT INTO "Tela" ("id", "moduloId", "ordem", "tipo", "label", "conteudo", "mediacao") VALUES
  ('cmsdk84i9001hpb7ekv53csj6', '725dfefa-0f91-47d9-a278-77da9a3091fe', 0, 'conceito', 'Ponto de partida', '{"corpo":"Você tem projetos demais: a pós, a viagem, trocar o carro, a entrada do apartamento. Todos ficam na cabeça e <strong>nenhum sai do lugar.</strong> O problema não é vontade. Você tem de sobra. É que objetivo sem número e sem prazo não vira ação.","insight":{"label":"Por que isso importa","texto":"Existe um abismo entre querer e fazer. A pesquisa mostra que a intenção sozinha explica só uma fração do que a gente realiza. O que fecha o abismo é dar forma concreta ao objetivo."},"headline":"Planejar você já sabe. Falta <em>executar.</em>"}'::jsonb, NULL),
  ('cmsdk84i9001ipb7eaw12lsiv', '725dfefa-0f91-47d9-a278-77da9a3091fe', 1, 'cenario', 'Conceito', '{"linhas":[{"tipo":"entrada","label":"Trocar o carro","valor":0,"valorTexto":"sem número"},{"tipo":"entrada","label":"Pós-graduação","valor":0,"valorTexto":"sem número"},{"tipo":"entrada","label":"Viagem com a família","valor":0,"valorTexto":"sem número"},{"tipo":"saldo","label":"Guardado pra qualquer um deles","valor":0}],"rodape":"O Kaio quer as três coisas há dois anos. Nenhuma tem valor definido, nenhuma tem prazo. <strong>Resultado: R$ 0 guardado.</strong>","headline":"Os planos do <em>Kaio</em>","personagem":"Kaio, 31"}'::jsonb, NULL),
  ('cmsdk84i9001jpb7ehowcldjo', '725dfefa-0f91-47d9-a278-77da9a3091fe', 2, 'quiz', 'Reflexão rápida', '{"opcoes":[{"letra":"A","texto":"Três objetivos vagos ao mesmo tempo travam a ação","correta":true,"feedback":"Isso. Uma única meta concreta gera mais economia real do que várias simultâneas. Espalhar o foco paralisa. É o que a pesquisa sobre metas mostra de forma consistente."},{"letra":"B","texto":"Ele ainda não encontrou o objetivo certo","correta":false,"feedback":"O objetivo ''certo'' não aparece sozinho. Ele se constrói quando você se compromete com um. Esperar a certeza é só uma forma elegante de adiar."},{"letra":"C","texto":"Ele precisa ganhar mais primeiro","correta":false,"feedback":"Sem alvo definido, um aumento também sumiria sem virar nenhum dos três. O gargalo não é a renda: é a falta de destino."}],"headline":"Por que o Kaio não saiu do zero em dois anos?"}'::jsonb, NULL),
  ('cmsdk84i9001kpb7eb5k0r7a6', '725dfefa-0f91-47d9-a278-77da9a3091fe', 3, 'conceito', 'O nome disso', '{"corpo":"''Quero viajar'' é um desejo. ''Quero R$ 6.000 até dezembro pra viajar'' é uma meta. A diferença parece pequena, mas pro cérebro é enorme: a segunda tem <strong>alvo, prazo e um próximo passo óbvio.</strong>","insight":{"label":"A regra que muda tudo","texto":"Um objetivo por vez. Focar numa única meta específica funciona melhor do que perseguir várias. Escolher parece perda, mas é o que faz uma delas finalmente acontecer."},"headline":"Objetivo vira meta quando ganha <em>número e data</em>"}'::jsonb, NULL),
  ('cmsdk84i9001lpb7eyc5uwf0o', '725dfefa-0f91-47d9-a278-77da9a3091fe', 4, 'input', 'Agora é com você', '{"aviso":"Isso fica só com você. Não salvamos nenhuma resposta.","campos":[{"id":"sonho","tipo":"texto","emoji":"✨","label":"Meu objetivo","placeholder":"o que você mais quer conquistar?"},{"id":"custo","tipo":"decimal","emoji":"🎯","label":"Custa","placeholder":"R$ quanto custa (estima se não souber)"},{"id":"meses","tipo":"decimal","emoji":"📅","label":"Em","placeholder":"quantos meses até lá?"}],"headline":"Escolhe <em>um</em>. Só um.","subtitulo":"3 campos. É aqui que ele sai da cabeça."}'::jsonb, NULL),
  ('cmsdk84i9001mpb7enlpfzbuc', '725dfefa-0f91-47d9-a278-77da9a3091fe', 5, 'resultado', 'Seu resultado', '{"faixas":[{"cor":"green","condicao":"porMesNum <= 200","mensagem":"Cabe mais fácil do que parecia, né? Menos de R$ 200 por mês e o objetivo é seu. O módulo 2 mostra o menor passo pra começar hoje."},{"cor":"yellow","condicao":"porMesNum <= 600","mensagem":"É um valor real, mas possível com organização. A diferença de agora pra ontem: agora tem número, então tem plano."},{"cor":"red","condicao":"porMesNum > 600","mensagem":"É ambicioso pro prazo que você deu. Ou estica o prazo, ou começa por uma versão menor, mas agora você sabe o tamanho exato do desafio. Isso já é metade do caminho."}],"formula":"sonhador_por_mes","headline":"Você precisa de <em>{porMes} por mês</em>","insightDinamico":"\"{sonho}\" deixou de ser uma ideia solta. Agora é uma meta com número e prazo. O tipo de coisa que o cérebro consegue perseguir de verdade."}'::jsonb, NULL),
  ('cmsdk84i9001npb7ead74zoa7', '725dfefa-0f91-47d9-a278-77da9a3091fe', 6, 'conceito', 'Módulo completo', '{"corpo":"Você fez o que trava a maioria: escolheu um só e deu a ele número e prazo. No próximo módulo você define <strong>o menor passo possível pra começar já</strong>. Porque meta sem primeiro passo continua sendo só um plano bonito.","insight":{"label":"Módulo 1 completo","texto":"Intenção sozinha não vira realização · Objetivo vira meta com número e prazo · Um de cada vez > vários ao mesmo tempo."},"headline":"Objetivo <em>ancorado</em>"}'::jsonb, NULL),
  ('cmsdk83mk0012pb7ehzvvhd4e', '834971a7-0415-4164-9424-eb5373c16fa8', 0, 'conceito', 'Ponto de partida', '{"corpo":"Você já comprou algo às onze da noite e, no dia seguinte, pensou ''por que eu fiz isso?''. Não é falta de caráter: é <strong>como o cérebro reage a uma emoção forte.</strong> Esse módulo mostra o mecanismo. Sem julgamento.","insight":{"label":"Por que isso importa","texto":"Você não controla um impulso que não enxerga. Reconhecer o gatilho é o que devolve o poder de escolha pra você."},"headline":"A compra alivia. A fatura chega <em>depois.</em>"}'::jsonb, NULL),
  ('cmsdk83mk0013pb7egb24mpvm', '834971a7-0415-4164-9424-eb5373c16fa8', 1, 'cenario', 'Conceito', '{"linhas":[{"tipo":"entrada","label":"Entrou (salário)","valor":4200},{"tipo":"saida","label":"Semana pesada → compra online","valor":-680},{"tipo":"saida","label":"Discussão em casa → jantar caro","valor":-240},{"tipo":"saida","label":"Resto do mês (contas, mercado, transporte)","valor":-3100},{"tipo":"saldo","label":"Sobrou","valor":180}],"rodape":"A Lari não planejou nem a compra nem o jantar. Os dois vieram logo depois de <strong>um dia ruim.</strong> O dinheiro não sumiu por acaso, sumiu junto com a emoção.","headline":"O mês da <em>Lari</em>","personagem":"Lari, 27, agência de publicidade"}'::jsonb, NULL),
  ('cmsdk83mk0014pb7esplgs736', '834971a7-0415-4164-9424-eb5373c16fa8', 2, 'quiz', 'Reflexão rápida', '{"opcoes":[{"letra":"A","texto":"Um jeito rápido de se sentir melhor","correta":true,"feedback":"Exato. Ela não queria o produto. Queria sair do dia ruim. A compra foi só o atalho mais próximo pro alívio."},{"letra":"B","texto":"Coisas que ela precisava e ia comprar de qualquer jeito","correta":false,"feedback":"Repara no timing: as duas compras vieram nas horas seguintes a um momento ruim. Necessidade real não tem esse padrão de horário."},{"letra":"C","texto":"Nada, faltou disciplina","correta":false,"feedback":"Não é disciplina nem caráter. É um mecanismo do cérebro buscando alívio imediato, e mecanismo se desarma com método, não com força de vontade."}],"headline":"O que a Lari estava tentando comprar de verdade?"}'::jsonb, NULL),
  ('cmsdk83mk0015pb7e72er05p6', '834971a7-0415-4164-9424-eb5373c16fa8', 3, 'conceito', 'O nome disso', '{"corpo":"Sob emoção forte, o cérebro prefere um alívio pequeno e imediato a um ganho maior lá na frente. Isso tem nome: <strong>desconto temporal</strong>. É por isso que ''compro agora'' parece tão certo às onze da noite, e tão errado quando a fatura fecha.","insight":{"label":"O que desarma","texto":"A pausa. Só o ato de esperar já reduz a intensidade da emoção. Quando o impulso deixa de ser imediato, ele perde força, e a escolha volta pra você."},"headline":"Seu cérebro quer o prêmio <em>agora</em>"}'::jsonb, NULL),
  ('cmsdk83mk0016pb7eltvj298a', '834971a7-0415-4164-9424-eb5373c16fa8', 4, 'input', 'Agora é com você', '{"aviso":"Isso fica só com você. Não salvamos nenhuma resposta.","campos":[{"id":"item","tipo":"texto","emoji":"🛍️","label":"Comprei","placeholder":"o que você comprou sem planejar?"},{"id":"valor","tipo":"decimal","emoji":"💸","label":"Custou","placeholder":"R$ quanto foi?"},{"id":"emocao","tipo":"texto","emoji":"🎭","label":"Sentia","placeholder":"que emoção veio antes? (cansaço, raiva, ansiedade...)"}],"headline":"Lembra da sua <em>última</em> compra por impulso","subtitulo":"3 campos. Sem vergonha."}'::jsonb, NULL),
  ('cmsdk83mk0017pb7eays22w30', '834971a7-0415-4164-9424-eb5373c16fa8', 5, 'resultado', 'Seu resultado', '{"faixas":[{"cor":"red","condicao":"valor > 500","mensagem":"Foi um gasto pesado movido por emoção, provavelmente parcelado, o que estica o efeito por meses. Imagina esse valor indo pra algo que você escolheu de verdade. O módulo 2 traz a técnica da pausa."},{"cor":"yellow","condicao":"valor > 150","mensagem":"O valor foi médio, mas o padrão é o que importa: emoção → compra. Agora que você viu o mecanismo, fica bem mais fácil pegar no flagra."},{"cor":"green","condicao":"valor <= 150","mensagem":"O valor foi pequeno, e você acabou de fazer a parte difícil: ligar a compra à emoção que veio antes. Esse é o mapa que quase ninguém desenha."}],"formula":"impulsivo_gatilho","headline":"Seu gatilho foi: <em>{emocao}</em>","insightDinamico":"Você comprou \"{item}\" sentindo \"{emocao}\". Da próxima vez que essa mesma emoção bater, é aí que a pausa entra. Você acabou de mapear seu próprio gatilho."}'::jsonb, NULL),
  ('cmsdk83mk0018pb7exv92tiqk', '834971a7-0415-4164-9424-eb5373c16fa8', 6, 'conceito', 'Módulo completo', '{"corpo":"Suas compras por impulso têm um padrão emocional, e agora você consegue vê-lo chegando. No próximo módulo, a <strong>técnica da pausa</strong>: o passo que desarma o impulso antes de ele virar parcela.","insight":{"label":"Módulo 1 completo","texto":"Impulso é emoção buscando alívio rápido · Desconto temporal faz o ''agora'' parecer certo · Você nomeou o gatilho que mais te pega."},"headline":"Gatilho <em>identificado</em>"}'::jsonb, NULL),
  ('cmsdk82qu000npb7ex10v4drg', '8aba2860-fa3d-4794-b55a-8488048c57d4', 0, 'conceito', 'Ponto de partida', '{"corpo":"A maioria dos apps assume que você gasta sem pensar. O seu caso é o contrário: você segura cada centavo, e mesmo assim sente <strong>peso quando gasta, até no que importa.</strong> Esse módulo é sobre isso.","insight":{"label":"Por que isso importa","texto":"Guardar por escolha e guardar por automatismo parecem iguais no extrato. A diferença é uma pergunta que quase ninguém se faz: guardar pra quê?"},"headline":"E se o seu problema <em>não for</em> gastar demais?"}'::jsonb, NULL),
  ('cmsdk82qu000opb7e5vi65odg', '8aba2860-fa3d-4794-b55a-8488048c57d4', 1, 'cenario', 'Conceito', '{"linhas":[{"tipo":"entrada","label":"Entrou (projeto fechado)","valor":5200},{"tipo":"saida","label":"Contas e essenciais","valor":-2900},{"tipo":"saida","label":"Guardou","valor":-2250},{"tipo":"saida","label":"Gastou consigo","valor":-50},{"tipo":"saldo","label":"Parado na conta, sem destino","valor":2250}],"rodape":"O Théo recusou ir ao casamento de um amigo pra não gastar R$ 400 com passagem. Do que sobrou depois das contas, guardou 98%. <strong>E passou o mês se sentindo mal mesmo assim.</strong>","headline":"O mês do <em>Théo</em>","personagem":"Théo, 34, designer, PJ"}'::jsonb, NULL),
  ('cmsdk82qu000ppb7elx7i8ig4', '8aba2860-fa3d-4794-b55a-8488048c57d4', 2, 'quiz', 'Reflexão rápida', '{"opcoes":[{"letra":"A","texto":"Ele guarda sem saber pra quê, e aí nem gastar nem guardar traz paz","correta":true,"feedback":"Isso. Dinheiro guardado sem destino não dá sensação de progresso, só adia a decisão. E cada gasto vira culpa porque não existe um ''quanto é ok''."},{"letra":"B","texto":"Ele deveria guardar ainda mais até se sentir seguro","correta":false,"feedback":"Essa é a armadilha do perfil: se 98% não trouxe paz, 100% também não traria. O problema não é o valor guardado: é a ausência de propósito."},{"letra":"C","texto":"Casamento é gasto besta, ele fez certo em recusar","correta":false,"feedback":"R$ 400 não ameaçavam nada: ele tinha R$ 2.250 parados sem destino nenhum. Recusar por reflexo, sem fazer a conta, não é decisão: é medo no automático."}],"headline":"Se guardar é bom, por que o Théo se sente mal?"}'::jsonb, NULL),
  ('cmsdk82qu000qpb7ekx0pzkdo', '8aba2860-fa3d-4794-b55a-8488048c57d4', 3, 'conceito', 'O nome disso', '{"corpo":"Quando você acredita que ''deveria estar guardando'' e gasta mesmo assim, o cérebro entra em conflito. Esse desconforto se chama <strong>dissonância cognitiva</strong>, e aparece até quando o gasto era totalmente razoável.","insight":{"label":"A pergunta que desarma","texto":"Guardar demais também cobra: casamentos, viagens e jantares que não voltam. Antes de recusar o próximo gasto, vale uma pergunta honesta. Isso é segurança, ou é medo no piloto automático?"},"headline":"A culpa de gastar tem <em>nome</em>"}'::jsonb, NULL),
  ('cmsdk82qu000rpb7ess255pvj', '8aba2860-fa3d-4794-b55a-8488048c57d4', 4, 'input', 'Agora é com você', '{"aviso":"Isso fica só com você. Não salvamos nenhuma resposta.","campos":[{"id":"guardou","tipo":"decimal","emoji":"🔒","label":"Guardei","placeholder":"R$ quanto você guardou esse mês?"},{"id":"gastou","tipo":"faixa","emoji":"🎉","label":"Curti","opcoes":[{"label":"quase nada (até R$ 100)","valor":"50"},{"label":"R$ 100–400","valor":"250"},{"label":"R$ 400–800","valor":"600"},{"label":"mais de R$ 800","valor":"1000"}]},{"id":"recusa","tipo":"texto","emoji":"😕","label":"Recusei","placeholder":"algo que deixou de fazer só pra economizar"}],"headline":"Responde <em>sincero</em>, só pra você","subtitulo":"3 campos. Ninguém vê."}'::jsonb, NULL),
  ('cmsdk82qu000spb7ec8yciv9a', '8aba2860-fa3d-4794-b55a-8488048c57d4', 5, 'resultado', 'Seu resultado', '{"faixas":[{"cor":"red","condicao":"pctGuardador < 5","mensagem":"Quase nada foi pra você. Não existe número certo, mas se dizer ''não'' virou reflexo, vale investigar o porquê. O módulo 2 te dá um jeito de gastar com intenção, sem peso."},{"cor":"yellow","condicao":"pctGuardador < 20","mensagem":"Você guarda muito e usa pouco. Pode ser uma fase com objetivo claro, ou pode ser o automático. Só você sabe. O próximo módulo transforma isso em escolha consciente."},{"cor":"green","condicao":"pctGuardador >= 20","mensagem":"Você tem um equilíbrio entre guardar e viver que é raro nesse perfil. A pergunta que fica: ele foi planejado, ou aconteceu por acaso?"}],"formula":"guardador_ratio","headline":"Você usou <em>≈ {pctGuardador}%</em> do seu dinheiro com você","insightDinamico":"Você deixou de fazer: \"{recusa}\". Vale se perguntar: essa recusa te protegeu de verdade, ou só te tirou algo que não custava tanto assim?"}'::jsonb, NULL),
  ('cmsdk82qu000tpb7eg7yyttu3', '8aba2860-fa3d-4794-b55a-8488048c57d4', 6, 'conceito', 'Módulo completo', '{"corpo":"Você viu que guardar sem propósito cobra um preço invisível, e que a culpa de gastar tem explicação, não é defeito seu. No próximo módulo você vai <strong>separar um valor pré-autorizado pra viver</strong>, com regra clara.","insight":{"label":"Módulo 1 completo","texto":"Guardar por escolha ≠ guardar no automático · Culpa de gastar é dissonância, não fato · Você identificou uma recusa que merecia uma segunda olhada."},"headline":"Permissão <em>ativada</em>"}'::jsonb, NULL),
  ('cmsdk81cq0008pb7etapekjnx', '98eed272-8e9e-4247-b322-de8eb77f85aa', 0, 'conceito', 'Ponto de partida', '{"corpo":"Não é falta de cuidado. É que o dinheiro digital <strong>some sem deixar rastro visível</strong>. Débito automático, Pix, parcela de três meses atrás. Esse módulo não vai te dizer o que fazer. Primeiro você vai só <strong>olhar.</strong>","insight":{"label":"Por que isso importa","texto":"Você não consegue mudar o que não enxerga. Consciência vem antes de qualquer regra, e antes de qualquer planilha."},"headline":"Você sabe pra onde foi o dinheiro <em>do mês passado?</em>"}'::jsonb, NULL),
  ('cmsdk81cq0009pb7e7ks01wqw', '98eed272-8e9e-4247-b322-de8eb77f85aa', 1, 'cenario', 'Conceito', '{"linhas":[{"tipo":"entrada","label":"Entrou (salário líquido)","valor":3800},{"tipo":"saida","label":"Aluguel + condomínio","valor":-1650},{"tipo":"saida","label":"Mercado + delivery","valor":-920},{"tipo":"saida","label":"Transporte + combustível","valor":-410},{"tipo":"saida","label":"Assinaturas e apps","valor":-180},{"tipo":"saida","label":"Fatura (parcelas antigas)","valor":-560},{"tipo":"saldo","label":"Sobrou","valor":80}],"rodape":"A Bia jurava que sobravam uns R$ 500 todo mês. <strong>Sobraram R$ 80.</strong>","headline":"Fluxo de caixa é só <em>entrada menos saída</em>","personagem":"Bia, 29, analista, CLT"}'::jsonb, NULL),
  ('cmsdk81cq000apb7ekx5tnx9h', '98eed272-8e9e-4247-b322-de8eb77f85aa', 2, 'quiz', 'Reflexão rápida', '{"opcoes":[{"letra":"A","texto":"Vários gastos médios somaram sem ela perceber","correta":true,"feedback":"Exato. O aluguel ela já esperava. O que a pegou foram os R$ 920 de mercado e delivery, que ela estimava em uns R$ 600, e as parcelas antigas que ela já nem lembrava de ter feito."},{"letra":"B","texto":"Ela fez um gasto grande demais em algo caro","correta":false,"feedback":"Não teve gasto fora da curva. O maior era o aluguel, previsto e fixo. O rombo veio da soma dos ''normais'', que é justamente o padrão mais difícil de enxergar."},{"letra":"C","texto":"Foi um mês atípico","correta":false,"feedback":"Quase todo mês tem essa cara quando ninguém abre o extrato. Não é atípico: é o padrão rodando invisível há meses."}],"headline":"Por que a Bia errou tanto a própria conta?"}'::jsonb, NULL),
  ('cmsdk81cq000bpb7e5zk3o274', '98eed272-8e9e-4247-b322-de8eb77f85aa', 3, 'conceito', 'O nome disso', '{"corpo":"R$ 39 de streaming. R$ 22 de café. R$ 48 da entrega de quarta. Nenhum parece grande. Mas trinta dias depois viram <strong>R$ 900</strong>, e você não lembra de quase nenhum deles.","insight":{"label":"O nome disso","texto":"Dor do pagamento: entregar dinheiro em espécie dói, e essa dor freia o gasto. Pix, cartão e um clique removem a dor. O cérebro quase não registra a saída, e o gasto pequeno some do radar."},"headline":"Gasto pequeno é <em>invisível</em>, até somar"}'::jsonb, NULL),
  ('cmsdk81cq000cpb7et53fohfy', '98eed272-8e9e-4247-b322-de8eb77f85aa', 4, 'input', 'Agora é com você', '{"aviso":"Isso fica só com você. Não salvamos nenhum valor.","campos":[{"id":"entrou","tipo":"decimal","emoji":"💸","label":"Entrou","placeholder":"R$ quanto entrou no mês passado?"},{"id":"saiu","tipo":"faixa","emoji":"🛒","label":"Saiu","opcoes":[{"label":"até R$ 1.500","valor":"1000"},{"label":"R$ 1.500–3.000","valor":"2200"},{"label":"R$ 3.000–5.000","valor":"4000"},{"label":"mais de R$ 5.000","valor":"6500"}]},{"id":"gasto","tipo":"texto","emoji":"🤔","label":"1 gasto","placeholder":"que você não lembrava até abrir a fatura"}],"headline":"Abre o extrato e preenche <em>só isso</em>","subtitulo":"3 campos. Não precisa ser exato."}'::jsonb, NULL),
  ('cmsdk81cq000dpb7egr4jo9ba', '98eed272-8e9e-4247-b322-de8eb77f85aa', 5, 'resultado', 'Seu resultado', '{"faixas":[{"cor":"green","condicao":"sobrou > 30pct","mensagem":"Sobrou mais de 30% do que entrou. Isso é raro e é uma base sólida. A pergunta agora é pra onde esse dinheiro está indo."},{"cor":"yellow","condicao":"sobrou > 0","mensagem":"Sobrou algo, mas foi apertado. O módulo 2 mostra como garantir esse espaço no dia do salário, em vez de torcer pra ele existir no dia 30."},{"cor":"red","condicao":"sobrou <= 0","mensagem":"Fechou no zero ou no vermelho. É mais comum do que parece, e ninguém fala. Agora você sabe o tamanho, e saber é o que torna o resto possível."}],"formula":"entrou_saiu_pct","headline":"Você gastou <em>≈ {pct}%</em> do que entrou","insightDinamico":"Você mencionou \"{gasto}\". Esse tipo de gasto é exatamente o que some primeiro do radar, e soma mais no fim do mês do que qualquer um estima."}'::jsonb, NULL),
  ('cmsdk81cq000epb7e77iuxvyr', '98eed272-8e9e-4247-b322-de8eb77f85aa', 6, 'conceito', 'Módulo completo', '{"corpo":"Você acabou de fazer o que a maioria adia por anos: <strong>olhar de frente pra onde foi o dinheiro.</strong> No próximo módulo você aprende a <strong>garantir um espaço antes de o mês começar a consumir tudo</strong>, sem abrir mão do que importa.","insight":{"label":"Módulo 1 completo","texto":"Fluxo de caixa = entrada − saída · Gasto pequeno soma mais do que parece · Você identificou seu primeiro gasto invisível."},"headline":"Consciência de fluxo <em>ativada</em>"}'::jsonb, NULL),
  ('cmsdk85dt001wpb7e3tvxck63', 'cmr9u5lzx000wo3zumirtdqzp', 0, 'conceito', 'Ponto de partida', '{"corpo":"Você já tentou ''gastar menos pra sobrar no fim do mês''. Não funcionou, e não é culpa sua. <strong>Guardar o que sobra é apostar contra o próprio cérebro.</strong> A solução é inverter a ordem.","insight":{"label":"Por que isso importa","texto":"Quem guarda primeiro não precisa de disciplina o mês inteiro. Precisa de uma decisão só, no dia em que o dinheiro cai."},"headline":"O que sobra no fim <em>nunca sobra.</em>"}'::jsonb, NULL),
  ('cmsdk85dt001xpb7e7o268kf7', 'cmr9u5lzx000wo3zumirtdqzp', 1, 'cenario', 'Conceito', '{"linhas":[{"tipo":"entrada","label":"Entrou (salário líquido)","valor":3800},{"tipo":"saida","label":"Separou no mesmo dia (10%)","valor":-380},{"tipo":"saida","label":"Viveu o mês com o resto","valor":-3420},{"tipo":"saldo","label":"Guardado no fim do mês","valor":380}],"rodape":"Mês passado sobraram R$ 80. Esse mês sobraram R$ 380. <strong>e ela não sentiu falta.</strong> A diferença foi só a ordem.","headline":"A Bia inverteu a <em>ordem</em>","personagem":"Bia, 29, analista, CLT"}'::jsonb, NULL),
  ('cmsdk85dt001ypb7ef1v4ugx2', 'cmr9u5lzx000wo3zumirtdqzp', 2, 'quiz', 'Reflexão rápida', '{"opcoes":[{"letra":"A","texto":"Ela decidiu uma vez só, no dia em que o salário caiu","correta":true,"feedback":"Exato. Uma decisão no dia 5 vence trinta pequenas decisões ao longo do mês. O cérebro se ajusta ao que enxerga como disponível."},{"letra":"B","texto":"Ela se controlou mais durante o mês","correta":false,"feedback":"Ela viveu o mês normalmente. Não se controlou nada. O truque é que os R$ 380 já não estavam na conta que ela olhava. A ordem fez o trabalho."},{"letra":"C","texto":"10% é pouco, por isso deu certo","correta":false,"feedback":"O valor ajuda a começar, mas o mecanismo é a ordem: o cérebro gasta o que enxerga como disponível, seja 100% ou 90% do saldo."}],"headline":"Por que separar antes funcionou pra Bia?"}'::jsonb, NULL),
  ('cmsdk85dt001zpb7ehykpztbn', 'cmr9u5lzx000wo3zumirtdqzp', 3, 'conceito', 'O nome disso', '{"corpo":"É a regra mais antiga das finanças pessoais: antes do mercado, do delivery e das assinaturas, você separa uma parte <strong>pra você do futuro.</strong> Não é sacrifício: é ordem de prioridade.","insight":{"label":"O tamanho certo","texto":"Comece pequeno: 10% é o clássico porque quase não dói. Melhor 10% que acontece todo mês do que 30% que você abandona no segundo."},"headline":"Pague <em>você</em> primeiro"}'::jsonb, NULL),
  ('cmsdk85dt0020pb7ekzj12dkw', 'cmr9u5lzx000wo3zumirtdqzp', 4, 'input', 'Agora é com você', '{"aviso":"Isso fica só com você. Não salvamos nenhum valor.","campos":[{"id":"entrou","tipo":"decimal","emoji":"💸","label":"Entra","placeholder":"R$ quanto entra por mês (líquido)?"},{"id":"pctRespiro","tipo":"decimal","emoji":"🫁","label":"Separo","placeholder":"% que você separa assim que cai (ex: 10)"}],"headline":"Define o <em>seu</em> respiro","subtitulo":"2 campos. Essa é a sua regra a partir de agora."}'::jsonb, NULL),
  ('cmsdk85dt0021pb7ee6lvhqau', 'cmr9u5lzx000wo3zumirtdqzp', 5, 'resultado', 'Seu resultado', '{"faixas":[{"cor":"yellow","condicao":"valor < 5","mensagem":"Menos de 5% cria reserva devagar demais. Se dá pra subir sem apertar, sobe, mas começar pequeno ainda é infinitamente melhor que não começar."},{"cor":"green","condicao":"valor <= 20","mensagem":"Faixa ideal pra começar: cria reserva de verdade sem sufocar o mês. Sustentável é o que vence no longo prazo."},{"cor":"yellow","condicao":"valor > 20","mensagem":"Ambicioso. Cuidado: respiro grande demais aperta o mês e aumenta a chance de você sacar de volta na terceira semana. Se sentir sufoco, desce. A constância vale mais que o valor."}],"formula":"respiro_valor","headline":"Seu respiro: <em>{respiro} por mês</em>","insightDinamico":"No dia em que o salário cair, transfere {respiro} pra outra conta. Antes do mercado, do delivery, do happy hour. As contas fixas seguem seu curso normal; o que muda é que o gasto variável passa a disputar um número menor."}'::jsonb, NULL),
  ('cmsdk85dt0022pb7e5dgwacdp', 'cmr9u5lzx000wo3zumirtdqzp', 6, 'conceito', 'Módulo completo', '{"corpo":"Você inverteu a ordem: agora guarda primeiro e vive com o resto. Não o contrário. No próximo módulo, esse respiro ganha <strong>um destino concreto</strong>, pra deixar de ser ''dinheiro parado'' e virar algo que você defende.","insight":{"label":"Módulo 2 completo","texto":"O que sobra no fim nunca sobra · Pague você primeiro · Uma decisão no dia do salário vence trinta no mês."},"headline":"Regra do respiro <em>ativada</em>"}'::jsonb, NULL),
  ('cmsdk869y002apb7e7y71g5iu', 'cmr9u5mx90014o3zu13537orx', 0, 'conceito', 'Ponto de partida', '{"corpo":"O respiro do módulo 2 tem um inimigo: a falta de propósito. Reserva ''pra nada'' é a primeira coisa que você saqueia quando o notebook trava ou aparece uma promoção. <strong>Reserva com nome e prazo, você defende.</strong>","insight":{"label":"Por que isso importa","texto":"Uma meta concreta transforma ''não gastar'' (chato) em ''estar quase lá'' (motivador). O cérebro persegue alvo, não abstração."},"headline":"Dinheiro guardado <em>sem nome</em> volta pro bolso"}'::jsonb, NULL),
  ('cmsdk869y002bpb7easmi9joi', 'cmr9u5mx90014o3zu13537orx', 1, 'input', 'Agora é com você', '{"aviso":"Isso fica só com você. Não salvamos nenhum valor.","campos":[{"id":"meta","tipo":"texto","emoji":"🎯","label":"Minha meta","placeholder":"o que você quer? (viagem, curso, trocar o notebook...)"},{"id":"custo","tipo":"decimal","emoji":"💰","label":"Custa","placeholder":"R$ quanto custa?"},{"id":"respiro","tipo":"decimal","emoji":"🫁","label":"Respiro","placeholder":"R$ do seu respiro mensal (módulo 2)"}],"headline":"Escolhe uma meta <em>alcançável</em>","subtitulo":"Algo que você consegue em alguns meses. Reancora seu respiro do módulo 2 aqui."}'::jsonb, NULL),
  ('cmsdk869y002cpb7eti9n8ff5', 'cmr9u5mx90014o3zu13537orx', 2, 'cenario', 'Conceito', '{"linhas":[{"tipo":"entrada","label":"Meta: viagem de fim de ano","valor":2280},{"tipo":"entrada","label":"Respiro mensal","valor":380},{"tipo":"saldo","label":"Meses até a meta","valor":6,"valorTexto":"6 meses"}],"rodape":"Seis meses. Cada mês que ela separa os R$ 380, <strong>a barra enche.</strong> Não é ''deixar de gastar'': é comprar a viagem em câmera lenta.","headline":"A conta da <em>Bia</em>","personagem":"Bia, 29, analista, CLT"}'::jsonb, NULL),
  ('cmsdk869y002dpb7egaoruf2u', 'cmr9u5mx90014o3zu13537orx', 3, 'quiz', 'Reflexão rápida', '{"opcoes":[{"letra":"A","texto":"Porque motivação não dura o ano inteiro, e meta longa cobra motivação o tempo todo","correta":true,"feedback":"Exato. Meta de três anos exige uma resistência que ainda não foi treinada. Uma meta de alguns meses entrega a vitória antes de o desânimo chegar, e vitória vira combustível."},{"letra":"B","texto":"Porque metas grandes são impossíveis","correta":false,"feedback":"São possíveis. Depois. Primeiro você prova pra si mesmo que consegue manter o respiro. A entrada do apartamento vem na sequência, com o músculo treinado."},{"letra":"C","texto":"Porque coisas baratas valem mais a pena","correta":false,"feedback":"Não é sobre o preço: é sobre o tempo até chegar lá. Curta significa retorno visível, e retorno visível é o que sustenta o hábito."}],"headline":"Por que a primeira meta precisa ser curta?"}'::jsonb, NULL),
  ('cmsdk869y002epb7e3qjr1ula', 'cmr9u5mx90014o3zu13537orx', 4, 'resultado', 'Seu resultado', '{"faixas":[{"cor":"green","condicao":"periodosNum <= 6","mensagem":"Dentro da janela ideal: dá pra enxergar a linha de chegada daqui. Cada mês de respiro é um passo visível, e visível é o que mantém o hábito de pé."},{"cor":"yellow","condicao":"periodosNum <= 12","mensagem":"Até um ano. Dá, mas é longo pra uma primeira meta. Se der pra aumentar um pouco o respiro ou escolher uma versão menor, a chance de chegar sobe bastante."},{"cor":"red","condicao":"periodosNum > 12","mensagem":"Mais de um ano é maratona, e você está começando a treinar agora. Escolhe algo menor pra primeira vitória. A meta grande continua existindo depois, e você chega nela com histórico."}],"formula":"semanas_meta","headline":"<em>{periodos} meses</em> até \"{meta}\"","insightDinamico":"\"{meta}\" agora tem preço, prazo e um caminho mensal. Quando bater vontade de sacar o respiro, lembra: cada saque adia a chegada em um mês inteiro."}'::jsonb, NULL),
  ('cmsdk869y002fpb7eapjoljjy', 'cmr9u5mx90014o3zu13537orx', 5, 'conceito', 'Módulo completo', '{"corpo":"Seu respiro deixou de ser dinheiro parado. Virou uma viagem, um curso, um notebook novo chegando em câmera lenta. Último módulo da trilha: <strong>o freio de 24 horas</strong>, pra nenhum impulso atropelar o caminho.","insight":{"label":"Módulo 3 completo","texto":"Reserva sem nome evapora · Meta curta = vitória antes do desânimo · Cada saque adia a chegada."},"headline":"Meta <em>ancorada</em>"}'::jsonb, NULL),
  ('cmsdk87a3002npb7e76pau54l', 'cmr9u5nps001bo3zu4s2piqp0', 0, 'conceito', 'Ponto de partida', '{"corpo":"Você já tem fluxo visível, respiro e meta. Falta proteger tudo isso do inimigo clássico: <strong>a compra que aparece do nada</strong>. A promoção, o achado, o ''em 10x sem juros''.","insight":{"label":"Por que isso importa","texto":"Não dá pra prever qual compra vai aparecer. Dá pra decidir ANTES o que acontece quando ela aparecer. Regra pré-combinada vence decisão tomada no calor do momento."},"headline":"Um gasto não planejado pode <em>desfazer um mês</em>"}'::jsonb, NULL),
  ('cmsdk87a3002opb7es7tqe7xc', 'cmr9u5nps001bo3zu4s2piqp0', 1, 'quiz', 'Situação real', '{"opcoes":[{"letra":"A","texto":"Anota, fecha o app e decide amanhã no mesmo horário","correta":true,"feedback":"Isso. Se amanhã ainda fizer sentido, e couber sem tocar no respiro. Compra. A maioria das ''promoções de hoje'' reaparece na semana seguinte com outro nome."},{"letra":"B","texto":"Compra. 30% off é economia, não gasto","correta":false,"feedback":"Desconto em algo que você não ia comprar não é economia: é gasto com marketing de urgência embutido. O ''só hoje'' foi desenhado exatamente pra impedir o seu amanhã."},{"letra":"C","texto":"Não compra nunca. Promoção é sempre armadilha","correta":false,"feedback":"Radical demais quebra no primeiro deslize. O freio não proíbe. Ele só move a decisão pra um momento em que você pensa melhor."}],"headline":"Sexta à noite: o notebook que você queria, 30% off, ''só hoje''. O que quem já treinou o freio faz?"}'::jsonb, NULL),
  ('cmsdk87a3002ppb7eq74kpoft', 'cmr9u5nps001bo3zu4s2piqp0', 2, 'conceito', 'O nome disso', '{"corpo":"Apps de compra removem cada obstáculo entre você e o ''comprar agora''. Um clique, cartão salvo, entrega amanhã, parcelamento sugerido. O freio de 24h <strong>devolve o obstáculo que eles tiraram.</strong>","insight":{"label":"Como calibrar","texto":"O freio não é pra tudo. Mercado não precisa de reunião. Ele vale a partir de um valor-limite que VOCÊ define. Abaixo dele, vida normal. Acima, 24 horas."},"headline":"Fricção <em>deliberada</em>"}'::jsonb, NULL),
  ('cmsdk87a3002qpb7eiild6ku8', 'cmr9u5nps001bo3zu4s2piqp0', 3, 'input', 'Agora é com você', '{"aviso":"Isso fica só com você. Não salvamos nenhum valor.","campos":[{"id":"valorLimite","tipo":"decimal","emoji":"🛑","label":"Meu limite","placeholder":"R$ a partir de quanto você espera 1 dia?"},{"id":"gastoRecente","tipo":"decimal","emoji":"🛒","label":"Teste","placeholder":"R$ do seu último gasto não planejado"}],"headline":"Define o <em>seu</em> limite de freio","subtitulo":"2 campos. Acima do limite = espera 24h."}'::jsonb, NULL),
  ('cmsdk87a3002rpb7eafa5y9n1', 'cmr9u5nps001bo3zu4s2piqp0', 4, 'resultado', 'Seu resultado', '{"faixas":[{"cor":"yellow","condicao":"acimaLimite == 1","mensagem":"Esse gasto teria caído no freio. Teria esperado 24 horas. Pergunta honesta: se você tivesse dormido antes de decidir, compraria mesmo assim? Se sim, ótimo. O freio não proíbe, só confirma. Se não, é exatamente pra isso que ele existe."},{"cor":"green","condicao":"acimaLimite == 0","mensagem":"Esse gasto passaria livre. Abaixo do seu limite, vida normal. O freio é pros gastos que doem, não pra te transformar em fiscal de si mesmo. Só confere se o limite não ficou alto demais: se quase nada cai nele, ele não freia nada."}],"formula":"freio_limite","headline":"Teste do freio no seu <em>último gasto</em>","insightDinamico":"Sua regra a partir de hoje: acima de R$ {valorLimite}, anota e decide amanhã. Uma regra só, decidida com a cabeça fria de hoje, protegendo todas as sextas à noite do futuro."}'::jsonb, NULL),
  ('cmsdk87a3002spb7ebq4q2mvw', 'cmr9u5nps001bo3zu4s2piqp0', 5, 'conceito', 'Trilha completa', '{"corpo":"Olha o sistema que você montou: <strong>enxerga o fluxo</strong> (M1), <strong>separa antes de gastar</strong> (M2), <strong>tem uma meta puxando</strong> (M3) e <strong>um freio protegendo</strong> (M4). Isso não é teoria: são quatro regras suas, com seus números.","insight":{"label":"Trilha completa","texto":"O jogo agora é manutenção: o respiro todo mês, o freio nos gastos grandes, e a meta enchendo. Quando ela completar. Escolhe a próxima e roda de novo."},"headline":"Trilha de fluxo de caixa <em>completa</em> 🏁"}'::jsonb, NULL),
  ('cmsdk885q0031pb7e8ky3lokw', 'cmr9u5oii001io3zuud2ghudb', 0, 'conceito', 'Ponto de partida', '{"corpo":"A culpa do módulo 1 tem uma causa: cada gasto seu passa por um julgamento interno. ''posso? devo? e se faltar?''. <strong>Trinta julgamentos por mês cansam qualquer um.</strong> A saída é julgar uma vez só.","insight":{"label":"Por que isso importa","texto":"Quando existe um valor mensal já autorizado pra você viver, gastar dentro dele não exige julgamento. A decisão já foi tomada. A culpa perde o emprego."},"headline":"E se gastar já viesse <em>pré-autorizado?</em>"}'::jsonb, NULL),
  ('cmsdk885q0032pb7e7lljscih', 'cmr9u5oii001io3zuud2ghudb', 1, 'cenario', 'Conceito', '{"linhas":[{"tipo":"entrada","label":"Entrou (projeto)","valor":5200},{"tipo":"saida","label":"Contas e essenciais","valor":-2900},{"tipo":"saida","label":"Guardado com propósito","valor":-1800},{"tipo":"saida","label":"Valor livre (pré-autorizado)","valor":-500},{"tipo":"saldo","label":"Folga","valor":0}],"rodape":"Os R$ 500 são dele pra viver. Jantar, show, viagem curta, o que for. <strong>Sem julgamento, porque o julgamento já aconteceu</strong> no dia em que ele definiu a regra.","headline":"O Théo criou uma <em>categoria nova</em>","personagem":"Théo, 34, designer, PJ"}'::jsonb, NULL),
  ('cmsdk885q0033pb7eo273bwg4', 'cmr9u5oii001io3zuud2ghudb', 2, 'quiz', 'Reflexão rápida', '{"opcoes":[{"letra":"A","texto":"Não. Gastar dentro de um plano É responsabilidade","correta":true,"feedback":"Exato. Responsabilidade não é gastar zero: é decidir com intenção. Os R$ 500 estavam no plano tanto quanto os R$ 1.800 guardados."},{"letra":"B","texto":"Sim. Ele podia ter guardado os R$ 500 também","correta":false,"feedback":"Essa é a voz do módulo 1 falando. Guardar quase tudo não trouxe paz pro Théo antes. Trouxe culpa e isolamento. Um plano com espaço pra viver é MAIS sustentável, não menos."},{"letra":"C","texto":"Depende do que ele fez no fim de semana","correta":false,"feedback":"Não depende. Esse é o ponto do valor livre: dentro dele, a escolha é 100% dele, sem prestação de contas. Julgar item por item é voltar pros trinta julgamentos."}],"headline":"O Théo gastou os R$ 500 num fim de semana fora. Ele foi menos responsável que antes?"}'::jsonb, NULL),
  ('cmsdk885q0034pb7e9tjrww8t', 'cmr9u5oii001io3zuud2ghudb', 3, 'conceito', 'O nome disso', '{"corpo":"Todo mundo acha que orçamento serve pra impedir gasto. Pra quem guarda bem é o contrário: <strong>o orçamento é o documento que AUTORIZA o gasto.</strong> Com limite claro, a liberdade dentro dele é total.","insight":{"label":"O tamanho certo","texto":"Entre 10% e 30% do que entra é uma faixa comum. Menos que isso e a regra quase não muda sua vida. O número exato é seu. O que importa é ele existir e ser usado."},"headline":"Orçamento não é corrente: é <em>alvará</em>"}'::jsonb, NULL),
  ('cmsdk885q0035pb7egszsf8sz', 'cmr9u5oii001io3zuud2ghudb', 4, 'input', 'Agora é com você', '{"aviso":"Isso fica só com você. Não salvamos nenhum valor.","campos":[{"id":"entrou","tipo":"decimal","emoji":"💸","label":"Entra","placeholder":"R$ quanto entra por mês?"},{"id":"pctLivre","tipo":"decimal","emoji":"🎟️","label":"Livre","placeholder":"% pré-autorizado pra você (ex: 20)"}],"headline":"Define o <em>seu</em> valor livre","subtitulo":"2 campos. O julgamento único do mês acontece agora."}'::jsonb, NULL),
  ('cmsdk885q0036pb7erd3ca9ub', 'cmr9u5oii001io3zuud2ghudb', 5, 'resultado', 'Seu resultado', '{"faixas":[{"cor":"yellow","condicao":"valor < 10","mensagem":"Menos de 10% é quase simbólico. A regra existe mas mal muda seu mês. Se a ideia de subir dá aperto no peito, repara nisso: é exatamente a dissonância do módulo 1 defendendo território."},{"cor":"green","condicao":"valor <= 30","mensagem":"Faixa de equilíbrio: espaço real pra viver sem comprometer o que você guarda. Agora a regra é usar. Valor livre que sobra todo mês vira poupança disfarçada, e aí nada mudou."},{"cor":"yellow","condicao":"valor > 30","mensagem":"Passo grande pra quem está acostumado a segurar, e pode ser ótimo. Só confere no fim do mês se foi confortável ou se a culpa apareceu. A regra certa é a que você consegue manter em paz."}],"formula":"valor_livre","headline":"Seu valor livre: <em>{livre} por mês</em>","insightDinamico":"{livre} por mês, seus, sem julgamento. Gastou dentro disso? Assunto encerrado, o plano já tinha aprovado."}'::jsonb, NULL),
  ('cmsdk885q0037pb7e86tt1hhb', 'cmr9u5oii001io3zuud2ghudb', 6, 'conceito', 'Módulo completo', '{"corpo":"Você trocou trinta julgamentos por um. No próximo módulo, a outra ponta: <strong>o dinheiro que você guarda tão bem vai começar a trabalhar</strong>, porque parado, ele encolhe todo ano.","insight":{"label":"Módulo 2 completo","texto":"Orçamento é alvará, não corrente · Gastar dentro do plano é responsabilidade · Um julgamento por mês, não trinta."},"headline":"Valor livre <em>definido</em>"}'::jsonb, NULL),
  ('cmsdk891l003fpb7e0kyphpd5', 'cmr9u5pba001qo3zuddvk4ibf', 0, 'conceito', 'Ponto de partida', '{"corpo":"O contrassenso de quem guarda bem: o dinheiro que você protege com tanto cuidado está <strong>perdendo valor em silêncio.</strong> Todo ano tudo fica mais caro, e R$ 20.000 parados continuam R$ 20.000, comprando menos.","insight":{"label":"Por que isso importa","texto":"Isso se chama inflação. Ela não cobra de quem gasta. Cobra de quem guarda parado. Ou seja: cobra exatamente de você. A defesa é fazer o guardado render pelo menos o suficiente pra empatar."},"headline":"Guardar você domina. Mas onde o dinheiro <em>dorme?</em>"}'::jsonb, NULL),
  ('cmsdk891l003gpb7eskila8z2', 'cmr9u5pba001qo3zuddvk4ibf', 1, 'input', 'Agora é com você', '{"aviso":"Isso fica só com você. Não salvamos nenhum valor.","campos":[{"id":"guardado","tipo":"decimal","emoji":"💤","label":"Parado","placeholder":"R$ quanto você tem parado em conta?"},{"id":"meses","tipo":"decimal","emoji":"📅","label":"Por","placeholder":"por quantos meses pretende deixar?"}],"headline":"Quanto do seu dinheiro está <em>dormindo?</em>","subtitulo":"2 campos. Vamos ver o que ele faria acordado."}'::jsonb, NULL),
  ('cmsdk891l003hpb7ekdn1ck6p', 'cmr9u5pba001qo3zuddvk4ibf', 2, 'cenario', 'Conceito', '{"linhas":[{"tipo":"entrada","label":"Parados na conta corrente","valor":22000},{"tipo":"entrada","label":"Em renda fixa conservadora","valor":24100,"valorTexto":"≈ R$ 24.100"},{"tipo":"saldo","label":"Diferença em 12 meses","valor":2100,"valorTexto":"≈ R$ 2.100"}],"rodape":"R$ 2.100 é quase metade de um mês de trabalho do Théo. <strong>por fazer exatamente o que ele já fazia de graça.</strong> A única mudança foi o lugar onde o dinheiro estava.","headline":"Os R$ 22.000 do Théo, <em>um ano depois</em>","personagem":"Théo, 34, designer, PJ"}'::jsonb, NULL),
  ('cmsdk891l003ipb7er2hgvks9', 'cmr9u5pba001qo3zuddvk4ibf', 3, 'quiz', 'Reflexão rápida', '{"opcoes":[{"letra":"A","texto":"Medo de perder. Parado parece mais seguro","correta":true,"feedback":"O medo clássico do perfil. Mas renda fixa conservadora (Tesouro Selic, CDB de liquidez diária) tem risco baixíssimo, e ''parado'' também tem risco: o de encolher todo ano, garantido. Seguro de verdade é acompanhar a inflação."},{"letra":"B","texto":"Investir é só pra quem tem muito dinheiro","correta":false,"feedback":"Dá pra começar com pouco mais de R$ 30 no Tesouro Direto. O valor de entrada não é o obstáculo. O obstáculo é abrir a conta e fazer a primeira aplicação."},{"letra":"C","texto":"A poupança já resolve. Rende a mesma coisa","correta":false,"feedback":"Não rende. Com a Selic acima de 8,5% ao ano, a poupança fica travada em 0,5% ao mês mais TR, enquanto o Tesouro Selic acompanha a taxa cheia. A diferença, num ano, é dinheiro que dá pra ver."}],"headline":"Por que o Théo hesitou em tirar o dinheiro da conta corrente?"}'::jsonb, NULL),
  ('cmsdk891l003jpb7ea1ll33yk', 'cmr9u5pba001qo3zuddvk4ibf', 4, 'resultado', 'Seu resultado', '{"faixas":[{"cor":"green","condicao":"rendeNum < 100","mensagem":"O valor ainda é modesto, mas o mecanismo é o mesmo em qualquer escala. Quem organiza isso agora chega nos R$ 100 mil com o processo já rodando no automático, em vez de começar do zero aos 45."},{"cor":"green","condicao":"rendeNum >= 100","mensagem":"Isso é dinheiro real deixado na mesa. Pago a quem simplesmente move o guardado de lugar. Seu talento de guardar somado a rendimento é a combinação mais forte que existe nas finanças pessoais."}],"formula":"render_simples","headline":"Dormindo, seu dinheiro deixa de gerar <em>≈ {rende}</em>","insightDinamico":"Estimativa ilustrativa (~0,8% ao mês em renda fixa conservadora. Não é recomendação de produto e não considera imposto). Próximo passo concreto: pesquisar ''Tesouro Selic'' e conferir se o banco onde você já tem conta oferece CDB com liquidez diária."}'::jsonb, NULL),
  ('cmsdk891l003kpb7e6ujwm5sn', 'cmr9u5pba001qo3zuddvk4ibf', 5, 'conceito', 'Módulo completo', '{"corpo":"Você descobriu que parado não é seguro: é encolhendo devagar. Último módulo da trilha: <strong>prazer com data marcada</strong>. Planejar um gasto bom com a mesma seriedade com que você guarda.","insight":{"label":"Módulo 3 completo","texto":"Inflação cobra de quem guarda parado · Renda fixa conservadora = risco baixíssimo · O mecanismo é igual em qualquer escala."},"headline":"Dinheiro <em>acordado</em>"}'::jsonb, NULL),
  ('cmsdk89x5003spb7eohagx4kh', 'cmr9u5q3y001xo3zuuo6thp2u', 0, 'conceito', 'Ponto de partida', '{"corpo":"Repara na assimetria: o que você guarda tem número, destino e disciplina. O que te dá prazer fica no ''um dia'', no ''quando der''. <strong>Esse módulo fecha a trilha invertendo isso uma vez.</strong>","insight":{"label":"Por que isso importa","texto":"Gasto planejado com antecedência tem um bônus escondido: a espera. Quem marca a viagem pra daqui a três meses aproveita duas vezes. Os três meses de expectativa e a viagem em si."},"headline":"Você planeja tudo, menos <em>o que te faz bem</em>"}'::jsonb, NULL),
  ('cmsdk89x5003tpb7em6xjhex0', 'cmr9u5q3y001xo3zuuo6thp2u', 1, 'quiz', 'Situação real', '{"opcoes":[{"letra":"A","texto":"Reserva R$ 200/mês do valor livre e compra o ingresso já","correta":true,"feedback":"Isso. Cabe no valor livre, tem data, tem plano. Comprar já garante o preço e transforma dois meses de espera em dois meses de expectativa boa."},{"letra":"B","texto":"Espera a véspera pra decidir se ''realmente vale a pena''","correta":false,"feedback":"Você conhece o final: na véspera o ingresso subiu ou esgotou, e a dúvida vence de novo. ''Decidir depois'' nesse perfil quase sempre significa ''não''."},{"letra":"C","texto":"Não vai. R$ 400 em renda fixa viram R$ 440 no fim do ano","correta":false,"feedback":"A conta está certa, e é essa a armadilha: pela matemática pura, TODO gasto perde pro rendimento, sempre. Se esse for o único critério, você guarda a vida inteira e não vive nenhuma parte dela."}],"headline":"O Théo quer ir num show daqui a 2 meses (R$ 400). O que quem planeja o prazer faz?"}'::jsonb, NULL),
  ('cmsdk89x5003upb7ezv64fo4u', 'cmr9u5q3y001xo3zuuo6thp2u', 2, 'conceito', 'O nome disso', '{"corpo":"A pesquisa sobre culpa financeira aponta uma saída consistente: a culpa some quando o gasto está <strong>conectado ao que importa de verdade pra você</strong>, e foi decidido com intenção, não no automático.","insight":{"label":"O critério","texto":"Antes de planejar, uma pergunta: o que te fez genuinamente feliz nos últimos doze meses? A resposta é o seu mapa de valores. Gasto alinhado a ele nunca é desperdício."},"headline":"Gasto alinhado a <em>valores</em>"}'::jsonb, NULL),
  ('cmsdk89x5003vpb7eloe6kq94', 'cmr9u5q3y001xo3zuuo6thp2u', 3, 'input', 'Agora é com você', '{"aviso":"Isso fica só com você. Não salvamos nenhuma resposta.","campos":[{"id":"experiencia","tipo":"texto","emoji":"🎫","label":"Quero","placeholder":"que experiência você quer viver?"},{"id":"custoExp","tipo":"decimal","emoji":"💰","label":"Custa","placeholder":"R$ quanto custa?"},{"id":"livre","tipo":"decimal","emoji":"🎟️","label":"Livre","placeholder":"R$ do seu valor livre mensal (módulo 2)"}],"headline":"Planeja <em>uma</em> experiência. Com data.","subtitulo":"3 campos. Reancora seu valor livre do módulo 2."}'::jsonb, NULL),
  ('cmsdk89x5003wpb7epo6bljwr', 'cmr9u5q3y001xo3zuuo6thp2u', 4, 'resultado', 'Seu resultado', '{"faixas":[{"cor":"green","condicao":"mesesJuntar <= 1","mensagem":"Cabe já no seu valor livre desse mês. Não tem mais desculpa matemática. Marca a data. De verdade: abre a agenda agora e marca."},{"cor":"green","condicao":"mesesJuntar <= 3","mensagem":"Reservando o valor livre por alguns meses, chega. Isso é um plano, e plano é o seu idioma. A diferença é que dessa vez o destinatário é você."},{"cor":"yellow","condicao":"mesesJuntar > 3","mensagem":"Mais de três meses de valor livre inteiro é pesado. Duas saídas dignas: uma versão menor da mesma experiência agora, ou a completa com prazo maior e parte vindo do guardado, que você tem, lembra?"}],"formula":"prazer_planejado","headline":"\"{experiencia}\" em <em>{mesesJuntar} mês(es)</em> de valor livre","insightDinamico":"Gasto planejado, alinhado ao que importa, dentro da sua regra. Se a culpa aparecer mesmo assim, ela não está te protegendo de nada: é só o hábito antigo fazendo barulho."}'::jsonb, NULL),
  ('cmsdk89x5003xpb7eo7uk13aq', 'cmr9u5q3y001xo3zuuo6thp2u', 5, 'conceito', 'Trilha completa', '{"corpo":"Olha o caminho: você entendeu a culpa (M1), criou seu valor livre (M2), acordou o dinheiro parado (M3) e <strong>marcou data com o próprio prazer</strong> (M4). Guardar continua sendo seu superpoder, agora com direção.","insight":{"label":"Trilha completa","texto":"Manutenção: valor livre todo mês (e USA ele), guardado rendendo, e pelo menos uma experiência com data marcada por vez. Segurança e vida, as duas ao mesmo tempo."},"headline":"Trilha de guardar e usar <em>completa</em> 🏁"}'::jsonb, NULL),
  ('cmsdk8asn0046pb7esb5mstcg', 'cmr9u5qwt0024o3zuaca3rt15', 0, 'conceito', 'Ponto de partida', '{"corpo":"No módulo 1 você mapeou seu gatilho. Agora a ferramenta, e ela NÃO é ''se controlar mais''. Força de vontade falha exatamente nos momentos em que você mais precisa dela. <strong>O que funciona é tempo.</strong>","insight":{"label":"Por que isso importa","texto":"O impulso é uma onda: sobe rápido, mas também desce rápido. Ele não sobrevive à espera. Quem aprende a deixar a onda passar não precisa lutar contra ela."},"headline":"Você não precisa de mais <em>força de vontade</em>"}'::jsonb, NULL),
  ('cmsdk8asn0047pb7ejdkobtx8', 'cmr9u5qwt0024o3zuaca3rt15', 1, 'cenario', 'Conceito', '{"linhas":[{"tipo":"saida","label":"Quinta: dia pesado + carrinho de R$ 520","valor":-520,"valorTexto":"no carrinho"},{"tipo":"entrada","label":"Regra nova: acima de R$ 200, dorme","valor":0,"valorTexto":"pausa de 24h"},{"tipo":"saldo","label":"Sexta: vontade que sobrou","valor":0,"valorTexto":"quase zero"}],"rodape":"Na sexta ela nem lembrava direito por que queria aquilo. <strong>Não foi disciplina. Foi a onda descendo sozinha.</strong> R$ 520 continuam com ela.","headline":"A Lari testou a <em>pausa</em>","personagem":"Lari, 27, agência de publicidade"}'::jsonb, NULL),
  ('cmsdk8asn0048pb7ep70fap2e', 'cmr9u5qwt0024o3zuaca3rt15', 2, 'quiz', 'Reflexão rápida', '{"opcoes":[{"letra":"A","texto":"A emoção que criou a vontade passou, e levou a vontade junto","correta":true,"feedback":"Exato. A compra era filha do dia pesado de quinta. Sem o dia pesado, ela ficou órfã. A pausa não mata o desejo real, só o desejo emprestado da emoção."},{"letra":"B","texto":"Ela percebeu que o produto era ruim","correta":false,"feedback":"O produto era o mesmo nos dois dias. O que mudou foi ela. De ''exausta buscando alívio'' pra ''descansada avaliando de verdade''."},{"letra":"C","texto":"Sorte. Normalmente esperar não muda nada","correta":false,"feedback":"É o padrão mais documentado do consumo por impulso: a intensidade da vontade despenca com o tempo. Se depois de 24h você AINDA quer, aí sim é desejo real, e pode virar compra planejada."}],"headline":"Por que a vontade da Lari quase sumiu em um dia?"}'::jsonb, NULL),
  ('cmsdk8asn0049pb7ehxpd69mc', 'cmr9u5qwt0024o3zuaca3rt15', 3, 'conceito', 'O nome disso', '{"corpo":"É a mesma lógica do direito de arrependimento de 7 dias em compras online: decisões tomadas no calor precisam de uma chance de revisão a frio. <strong>Você vai instalar essa lei em você mesmo</strong>, com um limite que dispara automático.","insight":{"label":"A calibragem que importa","texto":"O limite tem que ficar ABAIXO do seu impulso típico. Se seus impulsos são de R$ 300 e seu limite é R$ 800, a pausa nunca dispara, vira regra decorativa."},"headline":"Período de <em>esfriamento</em>"}'::jsonb, NULL),
  ('cmsdk8asn004apb7eizr9k1i9', 'cmr9u5qwt0024o3zuaca3rt15', 4, 'input', 'Agora é com você', '{"aviso":"Isso fica só com você. Não salvamos nenhum valor.","campos":[{"id":"gastoTipico","tipo":"faixa","emoji":"🛍️","label":"Meu impulso","opcoes":[{"label":"até R$ 100","valor":"70"},{"label":"R$ 100–300","valor":"200"},{"label":"R$ 300–700","valor":"500"},{"label":"mais de R$ 700","valor":"900"}]},{"id":"limiar","tipo":"decimal","emoji":"⏸️","label":"Minha pausa","placeholder":"R$ a partir de quanto você espera 24h?"}],"headline":"Calibra a <em>sua</em> pausa","subtitulo":"2 campos. O limite certo é o que pega o SEU impulso."}'::jsonb, NULL),
  ('cmsdk8asn004bpb7eioc1048t', 'cmr9u5qwt0024o3zuaca3rt15', 5, 'resultado', 'Seu resultado', '{"faixas":[{"cor":"green","condicao":"cobre == 1","mensagem":"Calibrada: seu impulso típico cai dentro da pausa. Da próxima vez que a emoção do módulo 1 aparecer com um carrinho na mão, a regra dispara sozinha. Anota, fecha o app, decide amanhã."},{"cor":"red","condicao":"cobre == 0","mensagem":"Descalibrada: seu limite está ACIMA do seu impulso típico. A pausa nunca vai disparar. Desce o limite pra baixo do valor que você costuma gastar. Regra que não dispara é decoração."}],"formula":"pausa_limiar","headline":"Teste de calibragem da <em>sua pausa</em>","insightDinamico":"Sua lei pessoal: acima de R$ {limiar} → anota o item, fecha o app, decide amanhã no mesmo horário. Se amanhã ainda quiser, é desejo real, e desejo real merece compra planejada, não culpa."}'::jsonb, NULL),
  ('cmsdk8asn004cpb7eylpn5wgx', 'cmr9u5qwt0024o3zuaca3rt15', 6, 'conceito', 'Módulo completo', '{"corpo":"Você não vai mais lutar contra a onda. Vai esperar ela passar. Mas a pausa deixa um vazio: a emoção continua lá, pedindo alívio. No próximo módulo, <strong>o que fazer nesse vazio</strong>, o alívio que não custa nada.","insight":{"label":"Módulo 2 completo","texto":"Impulso é onda: sobe e desce sozinho · Limite abaixo do impulso típico, senão é decoração · 24h separam desejo emprestado de desejo real."},"headline":"Pausa <em>instalada</em>"}'::jsonb, NULL),
  ('cmsdk8bog004kpb7e6i2owuhc', 'cmr9u5rp9002co3zuuw1x7ez7', 0, 'conceito', 'Ponto de partida', '{"corpo":"Módulo 1: você mapeou o gatilho. Módulo 2: instalou a pausa. Só que tem um buraco no plano. <strong>a emoção continua lá, pedindo alívio.</strong> Se você só bloquear a compra sem dar outra saída, a pressão acumula e uma hora estoura.","insight":{"label":"Por que isso importa","texto":"O impulso de compra é uma resposta aprendida: emoção ruim → comprar → alívio. Não dá pra apagar uma resposta aprendida, mas dá pra gravar outra por cima. Mesma emoção, nova saída."},"headline":"A pausa segura a compra. Mas e a <em>emoção?</em>"}'::jsonb, NULL),
  ('cmsdk8bog004lpb7erqi5xld1', 'cmr9u5rp9002co3zuuw1x7ez7', 1, 'input', 'Agora é com você', '{"aviso":"Isso fica só com você. Não salvamos nenhuma resposta.","campos":[{"id":"emocao","tipo":"texto","emoji":"🎭","label":"Gatilho","placeholder":"sua emoção-gatilho (do módulo 1)"},{"id":"substituto","tipo":"texto","emoji":"🔄","label":"Troco por","placeholder":"algo que te alivia e não custa (caminhar, treinar, ligar pra alguém...)"},{"id":"obstaculo","tipo":"texto","emoji":"🪨","label":"Meu risco","placeholder":"o que pode te fazer furar o plano?"}],"headline":"Monta o <em>seu</em> plano de troca","subtitulo":"3 campos. Reancora seu gatilho do módulo 1."}'::jsonb, NULL),
  ('cmsdk8bog004mpb7ekpcgkrh9', 'cmr9u5rp9002co3zuuw1x7ez7', 2, 'cenario', 'Conceito', '{"linhas":[{"tipo":"entrada","label":"Gatilho: semana pesada no trabalho","valor":0,"valorTexto":"mapeado"},{"tipo":"saida","label":"Resposta antiga: compra online","valor":-520,"valorTexto":"R$ 520 em média"},{"tipo":"saldo","label":"Resposta nova: caminhada de 15 min + playlist","valor":0,"valorTexto":"R$ 0"}],"rodape":"Mesma emoção, mesma necessidade de alívio. A diferença: <strong>a resposta nova alivia de verdade e não cobra nada depois</strong>, nem dinheiro, nem culpa, nem fatura.","headline":"O plano da <em>Lari</em>","personagem":"Lari, 27, agência de publicidade"}'::jsonb, NULL),
  ('cmsdk8bog004npb7etzcs403w', 'cmr9u5rp9002co3zuuw1x7ez7', 3, 'quiz', 'Reflexão rápida', '{"opcoes":[{"letra":"A","texto":"Um que ela consegue fazer em 2 minutos, de onde estiver","correta":true,"feedback":"Exato. O impulso aparece em segundos. O substituto tem que estar à mão na mesma velocidade. Simples e imediato vence perfeito e distante."},{"letra":"B","texto":"Rolar o feed pra distrair","correta":false,"feedback":"Armadilha clássica: o feed é exatamente onde moram os anúncios e as lojas. É apagar incêndio com álcool. O substituto precisa te tirar do ambiente de compra, não te devolver pra ele."},{"letra":"C","texto":"Prometer a si mesma ser mais forte na próxima","correta":false,"feedback":"Promessa não é plano. ''Ser mais forte'' falha exatamente no momento de fraqueza, por definição. Plano é: quando X acontecer, eu faço Y. Concreto, decidido antes."}],"headline":"Qual substituto teria MAIS chance de funcionar pra Lari?"}'::jsonb, NULL),
  ('cmsdk8bog004opb7eepsetenf', 'cmr9u5rp9002co3zuuw1x7ez7', 4, 'resultado', 'Seu resultado', '{"headline":"Seu plano: quando bater <em>{emocao}</em> → <em>{substituto}</em>","insightDinamico":"Esse formato ''quando X, faço Y'' é o que a pesquisa chama de plano se-então. Decidido a frio, executado no automático. Seu risco mapeado: \"{obstaculo}\". Já sabendo dele, você não é pego de surpresa. As primeiras vezes vão dar trabalho; da quinta em diante, o cérebro começa a puxar a resposta nova sozinho."}'::jsonb, NULL),
  ('cmsdk8bog004ppb7emrimicwy', 'cmr9u5rp9002co3zuuw1x7ez7', 5, 'conceito', 'Módulo completo', '{"corpo":"Gatilho mapeado, pausa instalada, resposta nova gravada. Último módulo da trilha: <strong>a lista que decide por você</strong>. O destino oficial de todo desejo que sobreviver à pausa.","insight":{"label":"Módulo 3 completo","texto":"Bloquear sem substituir acumula pressão · Substituto bom = imediato e fora do ambiente de compra · Quando X, faço Y, decidido antes."},"headline":"Alívio <em>trocado</em>"}'::jsonb, NULL),
  ('cmsdk8ck4004xpb7er8zvz7ux', 'cmr9u5shs002jo3zu340qqlea', 0, 'conceito', 'Ponto de partida', '{"corpo":"Nem todo impulso é falso alarme. Às vezes você espera um dia, espera dois. <strong>e ainda quer.</strong> Isso é desejo real, e desejo real merece respeito: um lugar oficial pra esperar a vez dele.","insight":{"label":"Por que isso importa","texto":"Sem a lista, todo desejo vira urgência disfarçada. Com a lista, os desejos competem entre si, e o tempo revela quais eram de verdade. Você compra os vencedores, sem culpa."},"headline":"E o desejo que <em>sobrevive</em> às 24 horas?"}'::jsonb, NULL),
  ('cmsdk8ck4004ypb7e5udo3xuu', 'cmr9u5shs002jo3zu340qqlea', 1, 'quiz', 'Situação real', '{"opcoes":[{"letra":"A","texto":"É desejo real. Pode virar compra planejada, sem culpa","correta":true,"feedback":"Exato. Sobreviver 10 dias sem a emoção do momento sustentando é o teste mais honesto que existe. Comprar agora não é impulso: é decisão."},{"letra":"B","texto":"Ela deveria esperar mais, só por garantia","correta":false,"feedback":"Esticar a espera pra sempre transforma a lista em prisão, e aí o sistema inteiro perde a graça e é abandonado. A lista precisa ter saída, senão vira só um jeito novo de se punir."},{"letra":"C","texto":"A lista falhou. O certo era o desejo sumir","correta":false,"feedback":"A lista não existe pra matar desejos. Existe pra separar os falsos dos verdadeiros. Um item que sobrevive é a lista FUNCIONANDO, não falhando."}],"headline":"Um item está há 10 dias na lista da Lari e ela ainda pensa nele. O que isso significa?"}'::jsonb, NULL),
  ('cmsdk8ck4004zpb7esn8hor61', 'cmr9u5shs002jo3zu340qqlea', 2, 'conceito', 'Como funciona', '{"corpo":"<strong>1.</strong> Todo desejo acima da sua pausa entra na lista, sem exceção, sem julgamento.<br><strong>2.</strong> Item que completar 7 dias e você ainda quiser: pode ser comprado, planejado, sem culpa.<br><strong>3.</strong> Item que você esqueceu que estava lá: sai da lista. Ele já disse tudo.","insight":{"label":"O efeito colateral bom","texto":"Depois de algumas semanas, a lista vira um espelho: você começa a ver os padrões do que deseja de verdade, e do que só desejava por quinze minutos."},"headline":"As 3 regras da <em>lista de espera</em>"}'::jsonb, NULL),
  ('cmsdk8ck40050pb7eitapwmng', 'cmr9u5shs002jo3zu340qqlea', 3, 'input', 'Agora é com você', '{"aviso":"Isso fica só com você. Não salvamos nenhuma resposta.","campos":[{"id":"desejo1","tipo":"texto","emoji":"1️⃣","label":"Desejo 1","placeholder":"o que você quer agora?"},{"id":"valor","tipo":"decimal","emoji":"💰","label":"Custa","placeholder":"R$ quanto custa o desejo 1?"},{"id":"onde","tipo":"texto","emoji":"📍","label":"Onde","placeholder":"onde a lista vai viver? (notas, planilha, papel...)"}],"headline":"Inaugura a <em>sua</em> lista","subtitulo":"3 campos. Os dois primeiros moradores e onde ela vai viver."}'::jsonb, NULL),
  ('cmsdk8ck40051pb7e27uatlyf', 'cmr9u5shs002jo3zu340qqlea', 4, 'resultado', 'Seu resultado', '{"faixas":[{"cor":"yellow","condicao":"valor > 500","mensagem":"Valor alto: esse merece o teste completo. 14 dias em vez de 7. Se sobreviver duas semanas, não só pode como MERECE ser comprado com planejamento (e à vista, se der)."},{"cor":"green","condicao":"valor <= 500","mensagem":"Teste padrão: 7 dias. Anota a data de entrada. Daqui uma semana, ou ele virou compra planejada ou virou história engraçada."}],"formula":"impulsivo_gatilho","headline":"\"{desejo1}\" entrou na lista. <em>Relógio rodando.</em>","insightDinamico":"Sua lista vive em: \"{onde}\". A partir de hoje o fluxo é um só: impulso → pausa → lista → 7 dias → decisão. Nenhuma etapa é proibição, todas são filtro."}'::jsonb, NULL),
  ('cmsdk8ck40052pb7emc9najyn', 'cmr9u5shs002jo3zu340qqlea', 5, 'conceito', 'Trilha completa', '{"corpo":"Olha o sistema: você <strong>conhece seu gatilho</strong> (M1), <strong>tem uma pausa que dispara sozinha</strong> (M2), <strong>um alívio que não custa</strong> (M3) e <strong>uma lista que separa desejo real de falso alarme</strong> (M4). O impulso não sumiu, ele só não manda mais.","insight":{"label":"Trilha completa","texto":"Manutenção: a pausa em todo gasto acima do limite, o substituto quando o gatilho bater, e a lista rodando. O que sobreviver, compra sem culpa, isso também é vitória."},"headline":"Trilha de compra por impulso <em>completa</em> 🏁"}'::jsonb, NULL),
  ('cmsdk8diu005bpb7ewwq06ree', 'cmr9u5taa002qo3zuc0g7kj1x', 0, 'conceito', 'Ponto de partida', '{"corpo":"No módulo 1 seu objetivo ganhou número e prazo. Perigo agora: a sensação de progresso SEM progresso. <strong>Definir a meta dá uma satisfação que engana</strong>. Parece que você já fez algo. Ainda não fez.","insight":{"label":"Por que isso importa","texto":"A diferença entre quem realiza e quem planeja não é o tamanho do primeiro passo: é a existência dele. Começado pequeno vence perfeito adiado, sempre."},"headline":"Meta definida não é meta <em>começada</em>"}'::jsonb, NULL),
  ('cmsdk8diu005cpb7emr0bri0q', 'cmr9u5taa002qo3zuc0g7kj1x', 1, 'cenario', 'Conceito', '{"linhas":[{"tipo":"entrada","label":"Meta: R$ 500/mês pra pós","valor":500,"valorTexto":"R$ 500/mês"},{"tipo":"saida","label":"Plano A: ''começo mês que vem, organizado''","valor":0,"valorTexto":"= nunca"},{"tipo":"saldo","label":"Plano B: transferiu R$ 50 no mesmo dia","valor":50}],"rodape":"R$ 50 não pagam pós nenhuma. Mas quebram algo maior: <strong>o zero.</strong> Quem saiu do zero tem um progresso pra defender. Quem ''vai começar'' tem só uma promessa pra adiar.","headline":"O Kaio quase caiu na <em>armadilha</em>","personagem":"Kaio, 31"}'::jsonb, NULL),
  ('cmsdk8diu005dpb7ewjeb2rgs', 'cmr9u5taa002qo3zuc0g7kj1x', 2, 'quiz', 'Reflexão rápida', '{"opcoes":[{"letra":"A","texto":"Porque existem, e o resto ainda é promessa","correta":true,"feedback":"Exato. R$ 50 reais mudam sua identidade de ''quem vai guardar'' pra ''quem guarda''. E identidade puxa comportamento: quem já começou tende a continuar."},{"letra":"B","texto":"Não valem, sem os R$ 500 completos, não conta","correta":false,"feedback":"Essa é a voz do perfeccionismo. A mesma que mantém todos os planos na cabeça há dois anos. ''Ou completo ou nada'' termina em nada. Sempre."},{"letra":"C","texto":"Valem porque R$ 50 rendem juros","correta":false,"feedback":"Renderiam centavos. O valor dos R$ 50 não é financeiro: é comportamental: eles provam que o plano saiu da cabeça. Essa prova não tem preço."}],"headline":"Por que os R$ 50 de hoje valem mais que os R$ 500 ''de mês que vem''?"}'::jsonb, NULL),
  ('cmsdk8diu005epb7ex32jjire', 'cmr9u5taa002qo3zuc0g7kj1x', 3, 'conceito', 'O nome disso', '{"corpo":"A pesquisa mostra que intenção vaga (''vou guardar todo mês'') falha, e intenção ancorada num evento (''QUANDO o salário cair, ENTÃO transfiro R$ 100'') executa quase sozinha. <strong>O evento vira o lembrete, você não depende de lembrar.</strong>","insight":{"label":"A fórmula","texto":"Quando [evento que sempre acontece] → eu transfiro [valor pequeno demais pra falhar] pra [meu objetivo]. Os três espaços preenchidos = plano. Qualquer espaço vago = desejo."},"headline":"Plano <em>se-então</em>"}'::jsonb, NULL),
  ('cmsdk8diu005fpb7e8snqkish', 'cmr9u5taa002qo3zuc0g7kj1x', 4, 'input', 'Agora é com você', '{"aviso":"Isso fica só com você. Não salvamos nenhuma resposta.","campos":[{"id":"sonho","tipo":"texto","emoji":"✨","label":"Pra","placeholder":"seu objetivo (do módulo 1)"},{"id":"quando","tipo":"texto","emoji":"⚡","label":"Quando","placeholder":"evento-gatilho (cair o salário, todo dia 5...)"},{"id":"quanto","tipo":"decimal","emoji":"🪙","label":"Transfiro","placeholder":"R$ pequeno demais pra falhar"}],"headline":"Preenche o <em>seu</em> se-então","subtitulo":"3 campos. Reancora seu objetivo do módulo 1."}'::jsonb, NULL),
  ('cmsdk8diu005gpb7ejsona0tk', 'cmr9u5taa002qo3zuc0g7kj1x', 5, 'resultado', 'Seu resultado', '{"faixas":[{"cor":"green","condicao":"valor <= 100","mensagem":"Pequeno demais pra falhar. Exatamente o tamanho certo. Depois que virar automático (umas quatro repetições), aí sim você aumenta. Começar pequeno não é falta de ambição: é estratégia."},{"cor":"yellow","condicao":"valor <= 300","mensagem":"Valor médio pra um primeiro passo. Funciona se couber com folga, mas se no segundo mês apertar, desce sem culpa. O hábito importa mais que o valor agora."},{"cor":"red","condicao":"valor > 300","mensagem":"Ambicioso demais pra um começo, e primeiro passo grande é o que mais falha. Corta pela metade. Sério. Você aumenta depois que a engrenagem estiver girando."}],"formula":"passo_minimo","headline":"Quando <em>{quando}</em> → transfiro <em>R$ {quanto}</em> pra \"{sonho}\"","insightDinamico":"E agora a parte que separa esse módulo de todos os planos que ficaram na cabeça: faz a primeira transferência HOJE. Não quando o evento chegar. Hoje, qualquer valor. Quebra o zero antes de fechar o app."}'::jsonb, NULL),
  ('cmsdk8diu005hpb7err6axbqm', 'cmr9u5taa002qo3zuc0g7kj1x', 6, 'conceito', 'Módulo completo', '{"corpo":"Seu objetivo tem número, prazo e agora um mecanismo que executa sozinho. Próximo módulo: <strong>a matemática dele contra a sua renda real</strong>. Porque plano que ignora a realidade volta a ser fantasia.","insight":{"label":"Módulo 2 completo","texto":"Definir não é começar · Quando X → transfiro Y pra Z · Pequeno demais pra falhar é o tamanho certo."},"headline":"Zero <em>quebrado</em>"}'::jsonb, NULL),
  ('cmsdk8eek005ppb7enkpmimsy', 'cmr9u5u2w002yo3zu8kefv41f', 0, 'conceito', 'Ponto de partida', '{"corpo":"Você tem objetivo (M1) e primeiro passo (M2). Falta o teste que quase ninguém faz: <strong>a meta cabe na SUA renda?</strong> Não na renda ideal, não na do mês do décimo terceiro, na real, do mês comum.","insight":{"label":"Por que isso importa","texto":"Meta impossível não motiva. Sabota. Três meses falhando ''por sua culpa'' (que era da matemática) e você desiste não só dessa meta, mas da ideia de ter metas. Melhor ajustar agora."},"headline":"Meta que ignora a renda vira <em>frustração agendada</em>"}'::jsonb, NULL),
  ('cmsdk8eek005qpb7eknp6zf40', 'cmr9u5u2w002yo3zu8kefv41f', 1, 'input', 'Agora é com você', '{"aviso":"Isso fica só com você. Não salvamos nenhum valor.","campos":[{"id":"entrou","tipo":"decimal","emoji":"💸","label":"Entra","placeholder":"R$ da sua renda mensal REAL (mês comum)"},{"id":"valorMes","tipo":"decimal","emoji":"🎯","label":"Meta pede","placeholder":"R$ por mês da sua meta (módulo 1)"}],"headline":"Bota os dois números <em>na mesa</em>","subtitulo":"2 campos. Reancora o valor/mês da sua meta do módulo 1."}'::jsonb, NULL),
  ('cmsdk8eek005rpb7el1xh57rq', 'cmr9u5u2w002yo3zu8kefv41f', 2, 'cenario', 'Conceito', '{"linhas":[{"tipo":"entrada","label":"Renda real (salário + freelas)","valor":4500},{"tipo":"saida","label":"Meta pede por mês","valor":-1200},{"tipo":"saldo","label":"Peso da meta na renda","valor":0,"valorTexto":"27%"}],"rodape":"27% da renda indo pra meta: aperta, mas passa no teste. <strong>Se desse 60%, o problema não seria disciplina. Seria física.</strong> E física não se resolve com força de vontade.","headline":"O teste do <em>Kaio</em>","personagem":"Kaio, 31"}'::jsonb, NULL),
  ('cmsdk8eek005spb7ekqyl2jje', 'cmr9u5u2w002yo3zu8kefv41f', 3, 'quiz', 'Reflexão rápida', '{"opcoes":[{"letra":"A","texto":"Esticar o prazo ou reduzir a meta. Ajustar a matemática","correta":true,"feedback":"Exato. Meta é ferramenta, não juramento. Ajustar o plano à realidade não é fracassar: é a diferença entre quem realiza devagar e quem desiste rápido."},{"letra":"B","texto":"Tentar mesmo assim. Quem quer, consegue","correta":false,"feedback":"Essa frase já enterrou mais metas que a preguiça. Viver com 40% da renda durante meses, pagando aluguel, não é questão de querer, e quando falhar, a culpa (injusta) vai ser sua. Matemática primeiro, motivação depois."},{"letra":"C","texto":"Desistir. Sinal de que não era pra ele","correta":false,"feedback":"Extremo oposto, mesmo erro. A meta continua válida. O PRAZO é que estava errado. Dobra o prazo, o peso cai pra 30%, e o plano segue vivo e possível."}],"headline":"Se a meta do Kaio pedisse 60% da renda, qual seria a atitude certa?"}'::jsonb, NULL),
  ('cmsdk8eek005tpb7e5k8ou261', 'cmr9u5u2w002yo3zu8kefv41f', 4, 'resultado', 'Seu resultado', '{"faixas":[{"cor":"green","condicao":"pctMeta <= 15","mensagem":"Confortável: a meta cabe com folga. Dá até pra considerar encurtar o prazo. Teste de realidade aprovado com sobra."},{"cor":"yellow","condicao":"pctMeta <= 30","mensagem":"Zona de esforço real: dá, mas exige escolhas conscientes todo mês. É sustentável se o aluguel, as contas e a comida couberem no que sobra. Confere isso antes de comemorar. Fica de olho nos dois primeiros meses."},{"cor":"red","condicao":"pctMeta > 30","mensagem":"Acima de 30%, a matemática está contra você, e ela sempre vence no longo prazo. Duas saídas honestas: esticar o prazo (o peso cai na proporção) ou reduzir a versão da meta. Ajustar AGORA é o que salva o plano."}],"formula":"realidade_meta","headline":"Sua meta pede <em>{pctMeta}%</em> da sua renda","insightDinamico":"Esse número. {pctMeta}%: é o teste que separa meta de fantasia. Você fez a conta que a maioria só descobre na frustração do terceiro mês. Se precisar ajustar, ajusta sem culpa: o plano agradece."}'::jsonb, NULL),
  ('cmsdk8eek005upb7eciyhf9vm', 'cmr9u5u2w002yo3zu8kefv41f', 5, 'conceito', 'Módulo completo', '{"corpo":"Meta com número, primeiro passo rodando e matemática conferida. Último módulo da trilha: <strong>o check de 5 minutos</strong>. O ritual que impede a empolgação de hoje de virar abandono no mês que vem.","insight":{"label":"Módulo 3 completo","texto":"Meta impossível sabota, não motiva · Ajustar prazo não é fracassar · Matemática primeiro, motivação depois."},"headline":"Realidade <em>testada</em>"}'::jsonb, NULL),
  ('cmsdk8fa30062pb7e07hj8rlf', 'cmr9u5uvh0035o3zut6f9o0d0', 0, 'conceito', 'Ponto de partida', '{"corpo":"Você conhece o ciclo: semana 1, tudo perfeito. Semana 3, ''esqueci''. Semana 5, o plano nem existe mais. <strong>Não é defeito seu: é o padrão de todo começo.</strong> O que os realizadores têm não é empolgação eterna: é um ritual que funciona sem ela.","insight":{"label":"Por que isso importa","texto":"Acompanhar o próprio progresso é um dos preditores mais fortes de meta cumprida. Não porque motiva, mas porque impede o desvio silencioso de virar abandono definitivo."},"headline":"A empolgação de hoje tem <em>prazo de validade</em>"}'::jsonb, NULL),
  ('cmsdk8fa30063pb7e8vtmzbrm', 'cmr9u5uvh0035o3zut6f9o0d0', 1, 'quiz', 'Situação real', '{"opcoes":[{"letra":"A","texto":"Registrar sem drama e ajustar a semana seguinte","correta":true,"feedback":"Exato. O check é painel de controle, não tribunal. Uma semana falhada e detectada custa uma semana. Uma semana falhada e escondida vira um mês, e depois vira o fim do plano."},{"letra":"B","texto":"Compensar dobrando o valor da próxima semana","correta":false,"feedback":"Punição transforma o check em coisa a evitar, e check evitado é plano morto. Além disso, dobrar o valor depois de falhar o normal é receita pra falhar de novo, agora com juros de culpa."},{"letra":"C","texto":"Nada. Falhou uma vez, o plano já era","correta":false,"feedback":"O pensamento tudo-ou-nada de novo. O maior inimigo de quem tem muitos planos. Todo plano de longo prazo tem semanas falhas. A diferença entre realizar e desistir é o que acontece na semana SEGUINTE."}],"headline":"Semana 4: o Kaio não transferiu nada e o check de domingo mostrou isso. O que o check deve fazer?"}'::jsonb, NULL),
  ('cmsdk8fa30064pb7ei1yznigy', 'cmr9u5uvh0035o3zut6f9o0d0', 2, 'conceito', 'Como funciona', '{"corpo":"<strong>1.</strong> Transferi o combinado essa semana? (sim/não, sem julgamento)<br><strong>2.</strong> Quanto falta pra meta? (o número atualizado)<br><strong>3.</strong> Alguma coisa muda semana que vem? (ajuste, se precisar)","insight":{"label":"A regra de ouro","texto":"Mesmo dia, mesmo horário, toda semana. Atrelado a algo que você JÁ faz (domingo à noite antes de dormir, sábado depois do almoço). Ritual sem âncora vira lembrança; com âncora, vira automático."},"headline":"O check tem <em>3 perguntas</em> e 5 minutos"}'::jsonb, NULL),
  ('cmsdk8fa30065pb7eaw0tkpxy', 'cmr9u5uvh0035o3zut6f9o0d0', 3, 'input', 'Agora é com você', '{"aviso":"Isso fica só com você. Não salvamos nenhuma resposta.","campos":[{"id":"dia","tipo":"texto","emoji":"📅","label":"Dia","placeholder":"que dia da semana?"},{"id":"ancora","tipo":"texto","emoji":"⚓","label":"Junto de","placeholder":"atrelado a quê? (depois do almoço, antes de dormir...)"},{"id":"onde","tipo":"texto","emoji":"📝","label":"Registro em","placeholder":"onde anota? (notas, caderno, planilha...)"}],"headline":"Marca o <em>seu</em> check","subtitulo":"3 campos. O compromisso mais leve e mais importante da trilha."}'::jsonb, NULL),
  ('cmsdk8fa30066pb7erre3o4np', 'cmr9u5uvh0035o3zut6f9o0d0', 4, 'resultado', 'Seu resultado', '{"headline":"Seu check: toda(o) <em>{dia}</em>, {ancora}","insightDinamico":"Registro em: \"{onde}\". Três perguntas, cinco minutos, toda semana. Esse ritual minúsculo é o que separa a sua trilha inteira de mais um plano bonito que ficou pela metade. Primeira sessão: já no próximo {dia}."}'::jsonb, NULL),
  ('cmsdk8fa30067pb7e054b7n1o', 'cmr9u5uvh0035o3zut6f9o0d0', 5, 'conceito', 'Trilha completa', '{"corpo":"Olha a jornada: um objetivo <strong>escolhido e ancorado</strong> (M1), um <strong>primeiro passo que quebrou o zero</strong> (M2), a <strong>matemática conferida</strong> (M3) e um <strong>ritual que sobrevive à empolgação</strong> (M4). Você não virou outra pessoa, virou alguém que executa o que planeja.","insight":{"label":"Trilha completa","texto":"Manutenção: o se-então rodando, o check toda semana, e quando a meta completar. Comemora de verdade, e só DEPOIS escolhe a próxima. Um objetivo por vez continua sendo a regra."},"headline":"Trilha de metas e planos <em>completa</em> 🏁"}'::jsonb, NULL),
  ('cmsdk70r60001z1zhth6iqeeo', 'cmschogq20000su6x1ka784k7', 0, 'conceito', 'O que é', '{"corpo":"Quando chega a fatura, o banco oferece um valor mínimo. Se você paga só ele, o resto não some: vira um empréstimo automático, no juro mais caro do país.\n\nNinguém assina nada. Não tem proposta, não tem simulação. O rotativo começa sozinho, no dia seguinte ao vencimento, e continua rodando enquanto sobrar saldo.","insight":{"label":"A taxa","texto":"O rotativo cobrava {{rotativo_medio}}. Para comparação, o crédito consignado, que é o mais barato do mercado, fica perto de {{consignado_clt}}."},"headline":"Rotativo é o pedaço da fatura que você não pagou"}'::jsonb, NULL),
  ('cmsdk70r60002z1zh9rnl9oae', 'cmschogq20000su6x1ka784k7', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saldo","label":"Fatura que chegou","valor":3400},{"tipo":"saida","label":"O mínimo que ela pagou","valor":510},{"tipo":"saldo","label":"Ficou rolando no rotativo","valor":2890}],"rodape":"No mês seguinte, a fatura veio maior que os R$ 2.890, mesmo sem ela ter comprado nada. Não foi erro do banco: foi o juro do rotativo entrando na conta.","headline":"A Renata pagou o mínimo e a fatura cresceu","personagem":"Renata, 33 anos, analista"}'::jsonb, NULL),
  ('cmsdk70r60003z1zhl0f82816', 'cmschogq20000su6x1ka784k7', 2, 'input', 'Seu chute', '{"aviso":"Sem consultar. O chute é o ponto do exercício.","campos":[{"id":"chute","tipo":"decimal","emoji":"🎯","label":"Meu chute","placeholder":"1500"}],"headline":"Chuta antes de ver","subtitulo":"Uma dívida de R$ 1.000 entra no rotativo hoje e fica lá 12 meses, sem você pagar nada. Em quanto ela se transforma?"}'::jsonb, NULL),
  ('cmsdk70r60004z1zhnyc66a02', 'cmschogq20000su6x1ka784k7', 3, 'resultado', 'A conta real', '{"faixas":[{"cor":"red","condicao":"subestimou > 0","mensagem":"Quase todo mundo chuta baixo, e não é falta de atenção: o cérebro humano projeta crescimento em linha reta, e juro composto não anda em linha reta. É por isso que a dívida surpreende mesmo quem sabe que ela é cara."},{"cor":"yellow","condicao":"valor > 0","mensagem":"Você chutou alto, e acertou a direção. A maioria das pessoas subestima, porque o cérebro projeta crescimento em linha reta e juro composto não anda em linha reta."}],"formula":"rotativo_bola_de_neve","headline":"Você chutou <strong>R$ {valor}</strong>. Pela taxa, seriam <strong>{semTeto}</strong>.","insightDinamico":"Mas existe um freio na lei. Desde janeiro de 2024, os encargos do rotativo não podem passar de {{teto_rotativo}}: os seus R$ 1.000 param em {comTeto}, não em {semTeto}. O teto protege, e continua sendo a dívida mais cara que você pode ter."}'::jsonb, NULL),
  ('cmsdk70r60005z1zh0cp82ux4', 'cmschogq20000su6x1ka784k7', 4, 'quiz', 'A saída', '{"opcoes":[{"letra":"A","texto":"Pago o mínimo e resolvo mês que vem","correta":false,"feedback":"É o caminho mais caro que existe. O mínimo não é uma opção de pagamento, é a porta de entrada do rotativo."},{"letra":"B","texto":"Peço pro banco parcelar a fatura","correta":true,"feedback":"Certo. O parcelamento da fatura é caro, mas custa uma fração do rotativo, e você passa a saber quanto vai pagar. Peça o CET antes de aceitar."},{"letra":"C","texto":"Busco um crédito mais barato pra quitar a fatura","correta":true,"feedback":"Também certo, e às vezes melhor. Trocar dívida cara por barata é a jogada mais eficiente que existe, desde que a nova dívida realmente quite a antiga."},{"letra":"D","texto":"Deixo vencer e negocio depois","correta":false,"feedback":"Atrasar acrescenta multa e mora, e ainda leva o nome para o cadastro de inadimplentes. Negociar antes de vencer é sempre mais barato."}],"headline":"A fatura não fecha esse mês. O que você faz?"}'::jsonb, NULL),
  ('cmsdk70r60006z1zh5ayqg7jp', 'cmschogq20000su6x1ka784k7', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"A regra prática: se a fatura não fecha, procure o banco ANTES do vencimento e peça o parcelamento com o CET na mão. Comparar pelo CET, e não pela parcela, é o que separa trocar dívida cara por barata de trocar de lugar."}],"headline":"Rotativo é o último recurso, nunca o padrão","insightDinamico":"E se já estiver no rotativo: ele é a primeira dívida a atacar, antes de qualquer outra. Nenhuma aplicação do mercado rende perto de {{rotativo_medio}}, então quitar rotativo é o melhor retorno garantido que você vai encontrar."}'::jsonb, NULL),
  ('cmsdk71fd0008z1zhh0u2x33a', 'cmsdemol800077hkzeza4hj9w', 0, 'conceito', 'O que trava', '{"corpo":"Quando uma dívida passa do prazo, o credor pode registrar seu CPF num cadastro de inadimplentes. A partir daí, quem consulta vê o registro: banco, loja, imobiliária, às vezes empregador.\n\nO que trava na prática é crédito novo, conta em algumas instituições, aluguel e compra parcelada. O que NÃO trava: receber salário, movimentar sua conta, sacar FGTS, trabalhar.","insight":{"label":"Você não está sozinho nisso","texto":"São {{inadimplentes}} com o nome restrito no Brasil, e a dívida média é de {{divida_media}}. É situação de multidão, não de exceção."},"headline":"Nome negativado não é sentença, é um aviso público"}'::jsonb, NULL),
  ('cmsdk71fd0009z1zhhfjc19gb', 'cmsdemol800077hkzeza4hj9w', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saldo","label":"O que ele gastou de verdade","valor":1800},{"tipo":"saida","label":"Juros e encargos acumulados","valor":520},{"tipo":"saida","label":"Multa e mora do atraso","valor":180},{"tipo":"saldo","label":"O que o credor cobrava","valor":2500}],"rodape":"A parte que cresceu foi a de encargos, não a da compra. É justamente essa parte que o credor tem margem para descontar numa negociação, ele prefere receber o principal a não receber nada.","headline":"O Marcos descobriu que a dívida tinha três partes","personagem":"Marcos, 38 anos, técnico"}'::jsonb, NULL),
  ('cmsdk71fd000az1zhzs0nevai', 'cmsdemol800077hkzeza4hj9w', 2, 'quiz', 'A lei que te protege', '{"opcoes":[{"letra":"A","texto":"Que a dívida é perdoada depois de 5 anos","correta":false,"feedback":"Não. O que caduca em 5 anos é o REGISTRO no cadastro de inadimplentes, não a dívida. Ela continua existindo e o credor pode cobrar."},{"letra":"B","texto":"Um plano de pagamento e a garantia do mínimo existencial","correta":true,"feedback":"Isso. A Lei 14.181/2021 permite repactuar dívidas num plano de até 5 anos e garante que sobre um mínimo para você viver. Nenhum acordo pode consumir tudo o que você ganha."},{"letra":"C","texto":"Que o banco é obrigado a aceitar sua proposta","correta":false,"feedback":"Não existe obrigação de aceitar um valor específico. O que a lei cria é o dever de negociar de boa-fé e o direito à audiência de conciliação."},{"letra":"D","texto":"Que você pode parar de pagar sem consequência","correta":false,"feedback":"Não. A lei protege quem está superendividado de boa-fé, e o caminho é repactuar, não parar de pagar."}],"headline":"A Lei do Superendividamento garante o quê?"}'::jsonb, NULL),
  ('cmsdk71fd000bz1zh3u09pnho', 'cmsdemol800077hkzeza4hj9w', 3, 'input', 'Sua dívida', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"divida","tipo":"decimal","emoji":"📄","label":"Total em atraso","placeholder":"2500"}],"headline":"Quanto está em atraso hoje?","subtitulo":"Só o que já passou do vencimento. Valor aproximado serve: o objetivo é ter um número na mão antes de ligar."}'::jsonb, NULL),
  ('cmsdk71fd000cz1zhssw44kr8', 'cmsdemol800077hkzeza4hj9w', 4, 'resultado', 'O que dá pra fazer', '{"faixas":[{"cor":"yellow","condicao":"acimaDaMedia > 0","mensagem":"Está acima da dívida média do país, e isso muda a estratégia: com valor maior, vale pedir a audiência de conciliação prevista na Lei do Superendividamento em vez de aceitar a primeira proposta do balcão."},{"cor":"green","condicao":"valor >= 0","mensagem":"Está na faixa em que a maioria dos acordos acontece. Credor prefere receber parte a não receber nada, e é por isso que a negociação costuma ter margem."}],"formula":"divida_negociada","headline":"Você tem <strong>R$ {valor}</strong> em atraso.","insightDinamico":"Para calibrar: o ticket médio de acordo no Brasil é {{ticket_acordo}}, e a dívida média de quem está negativado é {{divida_media}}. Isso não é promessa de desconto: depende do credor, do tempo de atraso e da campanha do mês. É só o retrato de onde as negociações costumam fechar."}'::jsonb, NULL),
  ('cmsdk71fd000dz1zhd58mcorp', 'cmsdemol800077hkzeza4hj9w', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"1. Liste tudo o que está em atraso, com credor e valor.\n2. Comece pela mais cara, não pela maior.\n3. Procure o canal oficial do credor ou os mutirões de renegociação. Nunca um intermediário que cobra para negociar.\n4. Antes de aceitar: peça o valor total do acordo, não a parcela. Parcela pequena com prazo longo pode custar mais que a dívida atual."}],"headline":"A ordem que funciona","insightDinamico":"E o mais importante: só feche um acordo que cabe. Acordo quebrado costuma voltar pior que a dívida original, e a Lei 14.181/2021 existe justamente para você não precisar assinar algo que não cabe no seu mês."}'::jsonb, NULL),
  ('cmsdk72e5000fz1zh0m2kc673', 'cmsdemp4t000e7hkz6c7xzzry', 0, 'conceito', 'O que é', '{"corpo":"Não é investimento e não é poupança para um objetivo. É um valor parado, de saque imediato, que cobre o mês quando algo quebra, some ou adoece.\n\nSem ela, todo imprevisto vira cartão. E cartão vira rotativo, que é a dívida mais cara do país. A reserva não é o passo depois de organizar as contas: é o que impede as contas de desorganizarem de novo.","insight":{"label":"Por que ela vem antes","texto":"{{sem_reserva_pct}} não têm reserva nenhuma. É também por isso que {{endividamento_familias}} estão endividadas: sem colchão, o imprevisto só tem um lugar para cair."},"headline":"Reserva é o dinheiro que existe pra você não pegar emprestado"}'::jsonb, NULL),
  ('cmsdk72e5000gz1zhk953210n', 'cmsdemp4t000e7hkz6c7xzzry', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saida","label":"O conserto","valor":1400},{"tipo":"saida","label":"Foi pro cartão, em 6x","valor":280},{"tipo":"saida","label":"Juros do parcelamento no ano","valor":190}],"rodape":"O conserto custou R$ 1.400. Ela pagou R$ 1.590. A diferença é o preço de não ter tido R$ 1.400 parados, e ela ficou com 6 meses de parcela comprometida, o que reduziu a chance de guardar para o próximo imprevisto.","headline":"A Carla não tinha reserva, e o carro quebrou","personagem":"Carla, 29 anos, autônoma"}'::jsonb, NULL),
  ('cmsdk72e5000hz1zh3qi0vp5q', 'cmsdemp4t000e7hkz6c7xzzry', 2, 'input', 'Seu custo fixo', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"custoFixo","tipo":"decimal","emoji":"🏠","label":"Custo fixo do mês","placeholder":"2800"}],"headline":"Quanto você gasta num mês só pra viver?","subtitulo":"Aluguel ou prestação, contas de casa, mercado, transporte, remédio. O essencial. Não inclua lazer nem o que dá pra cortar num mês apertado."}'::jsonb, NULL),
  ('cmsdk72e5000iz1zh3m75yecv', 'cmsdemp4t000e7hkz6c7xzzry', 3, 'resultado', 'Sua meta', '{"faixas":[{"cor":"green","condicao":"valor > 0","mensagem":"É de 3 a 6 meses do seu custo fixo, não da sua renda. A diferença é grande e é de propósito: a reserva precisa cobrir o que você GASTA para viver, não o que você ganha."}],"formula":"reserva_meta","headline":"Sua reserva cheia é entre <strong>{reserva3}</strong> e <strong>{reserva6}</strong>.","insightDinamico":"E o número cheio não é a meta de agora. A meta de agora é UM mês: R$ {valor}. É o suficiente para o próximo imprevisto não virar cartão, e é o que faz a maioria das pessoas continuar em vez de desistir olhando para {reserva6}."}'::jsonb, NULL),
  ('cmsdk72e5000jz1zhwp186xnb', 'cmsdemp4t000e7hkz6c7xzzry', 4, 'quiz', 'Onde deixar', '{"opcoes":[{"letra":"A","texto":"O maior rendimento possível","correta":false,"feedback":"Não. Rendimento alto costuma vir com prazo ou com risco, e reserva presa no dia do aperto deixa de ser reserva."},{"letra":"B","texto":"Poder sacar no mesmo dia, com risco baixo","correta":true,"feedback":"Isso. Liquidez primeiro, segurança depois, rendimento por último. A reserva não existe para render: existe para estar lá."},{"letra":"C","texto":"Deixar em casa, em dinheiro vivo","correta":false,"feedback":"Perde para a inflação todo mês e some num roubo ou num incêndio. Liquidez imediata dá para ter sem abrir mão de segurança."},{"letra":"D","texto":"Investir em algo que valorize no longo prazo","correta":false,"feedback":"Longo prazo é o oposto do que a reserva precisa. Se o imprevisto chega num mês ruim do mercado, você saca no prejuízo."}],"headline":"O que importa na hora de escolher onde deixar a reserva?"}'::jsonb, NULL),
  ('cmsdk72e5000kz1zhdhqphtp8', 'cmsdemp4t000e7hkz6c7xzzry', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Escolha um valor que sai da conta no dia em que o dinheiro entra, antes de qualquer gasto. Pode ser pequeno. O que faz a reserva existir é a repetição, não o tamanho do primeiro depósito."}],"headline":"Comece pelo mês, não pelo colchão inteiro","insightDinamico":"Regra prática: enquanto a reserva não fecha o primeiro mês, ela vem antes de qualquer investimento. Depois dela, aí sim faz sentido pensar em prazo e em render."}'::jsonb, NULL),
  ('cmsdk730k000mz1zh3igeliad', 'cmsdempoh000l7hkz0kgaxaos', 0, 'conceito', 'O que é', '{"corpo":"Uma compra de R$ 40 você percebe. Uma assinatura de R$ 40 por mês você percebe uma vez, no dia que assinou, e nunca mais.\n\nNão é distração: é como a cobrança foi desenhada. Ela não pede confirmação, não manda lembrete, e o valor é pequeno o bastante para não chamar atenção na fatura. O que aparece na fatura é o total, e o total não denuncia ninguém.","insight":{"label":"Quanto costuma ser","texto":"A maioria dos brasileiros gasta {{gasto_assinaturas}} com assinaturas e mensalidades recorrentes. Quase sempre é mais do que a pessoa imagina antes de conferir."},"headline":"Recorrência é o gasto que some da sua atenção"}'::jsonb, NULL),
  ('cmsdk730k000nz1zhn7kdw8lc', 'cmsdempoh000l7hkz0kgaxaos', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saida","label":"O que ele assistia","valor":40},{"tipo":"saida","label":"Assinado no teste grátis e esquecido","valor":35},{"tipo":"saida","label":"Da série que ele terminou em janeiro","valor":30},{"tipo":"saida","label":"Que ele nem lembrava de ter assinado","valor":35}],"rodape":"R$ 140 por mês, dos quais ele usava R$ 40. Não é que ele não pudesse pagar: é que ele estava pagando por três coisas que não queria, sem saber.","headline":"O João achou quatro streamings ativos","personagem":"João, 35 anos, vendedor"}'::jsonb, NULL),
  ('cmsdk730k000oz1zh210ogvgg', 'cmsdempoh000l7hkz0kgaxaos', 2, 'input', 'Seu chute', '{"aviso":"Sem consultar. O chute é o ponto do exercício.","campos":[{"id":"assinaturas","tipo":"decimal","emoji":"🔁","label":"Meu chute por mês","placeholder":"90"}],"headline":"Quanto você acha que gasta por mês com assinaturas?","subtitulo":"Streaming, música, academia, aplicativo, nuvem, clube de assinatura, jogo. Chuta antes de conferir a fatura."}'::jsonb, NULL),
  ('cmsdk730k000pz1zhdcroq2qb', 'cmsdempoh000l7hkz0kgaxaos', 3, 'resultado', 'No ano', '{"faixas":[{"cor":"yellow","condicao":"valor > 0","mensagem":"O número do mês é fácil de aceitar. O do ano costuma ser o que faz a pessoa abrir o extrato. É o mesmo dinheiro, contado de um jeito que dá pra sentir."}],"formula":"assinaturas_ano","headline":"<strong>R$ {valor}</strong> por mês são <strong>{ano}</strong> no ano.","insightDinamico":"Agora o teste que vale: abre a fatura do cartão e confere. Quase ninguém acerta o próprio chute, e a diferença entre o que você imaginou e o que está lá é exatamente o dinheiro que sai sem você decidir."}'::jsonb, NULL),
  ('cmsdk730k000qz1zh4uzf3x98', 'cmsdempoh000l7hkz0kgaxaos', 4, 'quiz', 'O que cortar', '{"opcoes":[{"letra":"A","texto":"Cancelo agora e reassino quando precisar","correta":true,"feedback":"Certo. Quase toda assinatura digital volta com um clique, e sem multa. O custo de reassinar é baixo; o de manter doze meses ligado, não."},{"letra":"B","texto":"Mantenho, porque é barato","correta":false,"feedback":"Barato por mês é caro por ano. E o problema não é o preço: é pagar por algo que você não escolheria hoje."},{"letra":"C","texto":"Espero acabar o ano pra decidir","correta":false,"feedback":"Adiar a decisão é a decisão de continuar pagando. Se você não usaria hoje, cada mês de espera é dinheiro que já foi."},{"letra":"D","texto":"Troco por um plano mais barato do mesmo serviço","correta":true,"feedback":"Também vale, quando você realmente usa. Plano com anúncio ou compartilhado costuma cortar metade do valor sem tirar o que você assiste."}],"headline":"Você achou uma assinatura que usa pouco. O que fazer?"}'::jsonb, NULL),
  ('cmsdk730k000rz1zhjz54vstc', 'cmsdempoh000l7hkz0kgaxaos', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Escolhe um dia fixo, logo depois de a fatura fechar. Abre o extrato, procura o que se repete, e pergunta de cada linha: eu assinaria isso hoje? O que não passar nesse teste, cancela na hora."}],"headline":"Uma varredura por mês, no mesmo dia","insightDinamico":"É a vitória mais rápida que existe em dinheiro: não exige ganhar mais, não exige cortar nada que você goste, e o efeito aparece já na próxima fatura. Cada assinatura cancelada vira o primeiro depósito da sua reserva."}'::jsonb, NULL),
  ('cmsdk73mz000tz1zh3oyc4ed0', 'cmsdfq85c000sqchzvaocxyrs', 0, 'conceito', 'O que é', '{"corpo":"Não tem juro, é verdade. Mas tem uma coisa que o juro também tem: ele compromete uma renda que ainda não chegou.\n\nCada 10x que você aceita hoje reserva um pedaço dos seus próximos dez meses. Quando várias se acumulam, o salário chega e já está gasto, e aí a compra do mês entra no cartão de novo, porque não sobrou dinheiro vivo.","insight":{"label":"O tamanho disso no Brasil","texto":"O parcelado sem juros já é {{parcelado_sem_juros}}, e {{compras_nao_planejadas}} admitem ter feito compras não planejadas no mês anterior."},"headline":"Parcelado sem juros é dívida, só que sem a palavra dívida"}'::jsonb, NULL),
  ('cmsdk73mz000uz1zhv64iola9', 'cmsdfq85c000sqchzvaocxyrs', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"entrada","label":"Salário do mês","valor":3200},{"tipo":"saida","label":"Celular, 8 de 10x","valor":280},{"tipo":"saida","label":"Sofá, 4 de 12x","valor":320},{"tipo":"saida","label":"Viagem, 3 de 6x","valor":300}],"rodape":"R$ 900 já estavam comprometidos antes de ela comprar comida. Nenhuma das três compras foi errada. O problema é que foram decididas em meses diferentes, e chegam todas no mesmo.","headline":"A Bruna recebeu o salário e ele já estava gasto","personagem":"Bruna, 31 anos, designer"}'::jsonb, NULL),
  ('cmsdk73mz000vz1zhayi60era', 'cmsdfq85c000sqchzvaocxyrs', 2, 'input', 'Suas parcelas', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"parcelas","tipo":"decimal","emoji":"🧾","label":"Parcelas do mês que vem","placeholder":"900"},{"id":"rendaMes","tipo":"decimal","emoji":"💰","label":"Quanto entra por mês","placeholder":"3200"}],"headline":"Some tudo que já está parcelado","subtitulo":"Abra a fatura e some as parcelas que vão cair no mês que vem. Depois me diga quanto entra por mês."}'::jsonb, NULL),
  ('cmsdk73mz000wz1zh7878u9y6', 'cmsdfq85c000sqchzvaocxyrs', 3, 'resultado', 'O mês que vem', '{"faixas":[{"cor":"red","condicao":"comprometidoNum >= 30","mensagem":"Acima de 30% comprometido, sobra pouco espaço para o imprevisto. Não é que você gastou demais: é que as decisões foram tomadas em meses diferentes e chegaram juntas."},{"cor":"yellow","condicao":"comprometidoNum >= 15","mensagem":"É uma faixa administrável, mas vale saber que ela existe antes de aceitar o próximo parcelamento."},{"cor":"green","condicao":"valor >= 0","mensagem":"Sobra espaço no mês que vem. É desse espaço que sai a reserva, e é ele que o próximo 10x consome."}],"formula":"parcelas_comprometem","headline":"<strong>{comprometido}%</strong> do mês que vem já está gasto.","insightDinamico":"A conta que quase ninguém faz antes de comprar: a parcela nova entra num mês que já tem parcelas velhas. O número que importa não é o da prestação, é este aqui."}'::jsonb, NULL),
  ('cmsdk73mz000xz1zhqobysh5r', 'cmsdfq85c000sqchzvaocxyrs', 4, 'quiz', 'Na hora da compra', '{"opcoes":[{"letra":"A","texto":"Quanto fica a parcela","correta":false,"feedback":"É a pergunta que a loja quer que você faça: parcela pequena parece barata. O total e o prazo somem da conversa."},{"letra":"B","texto":"Quanto fica à vista","correta":true,"feedback":"Certo. Muita loja dá desconto à vista, e aí o sem juros deixa de ser de graça: você está pagando o desconto que abriu mão."},{"letra":"C","texto":"Quanto eu já tenho comprometido nos próximos 10 meses","correta":true,"feedback":"Também certo, e é a pergunta que protege o mês. Parcela cabe sempre; o que não cabe é a soma delas."},{"letra":"D","texto":"Se dá pra parcelar em mais vezes","correta":false,"feedback":"Mais vezes é mais meses comprometidos. Alonga o problema em vez de resolvê-lo."}],"headline":"A vendedora oferece 10x sem juros. O que você pergunta primeiro?"}'::jsonb, NULL),
  ('cmsdk73mz000yz1zh7lyi9hqr', 'cmsdfq85c000sqchzvaocxyrs', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"1. Antes de aceitar qualquer parcelamento, some o que já está comprometido. Se passar de um terço do que entra, a resposta é não.\n\n2. Compra por impulso espera 24 horas. O desejo que sobrevive a um dia é desejo; o que some era o momento."}],"headline":"Duas regras que cabem na cabeça","insightDinamico":"E uma coisa que não é regra, é aritmética: quando você quita as parcelas, o dinheiro não aparece do nada. Ele volta a existir porque parou de estar reservado."}'::jsonb, NULL),
  ('cmsdk749x0010z1zhyxxtj47b', 'cmsdfq8p1000zqchzwkfdzaxb', 0, 'conceito', 'Bruto e líquido', '{"corpo":"Entre um e outro entram descontos obrigatórios:\n\n• INSS: sua contribuição para a Previdência. É o que garante aposentadoria, auxílio-doença e salário-maternidade.\n• IRRF: imposto de renda retido direto na fonte. Depende da faixa e de quantos dependentes você tem.\n• Outros: vale-transporte, plano de saúde, consignado, se houver.\n\nO FGTS não aparece como desconto: ele é depositado PELO empregador numa conta no seu nome. Não sai do seu líquido.","insight":{"label":"Por que isso é confuso","texto":"Só {{letramento_juros}} conseguem fazer um cálculo simples de juros. Não é falta de inteligência: é que ninguém ensina, e o holerite não foi escrito para ser entendido."},"headline":"O salário combinado é o bruto. O que cai é o líquido"}'::jsonb, NULL),
  ('cmsdk749x0011z1zhi9g1wyl5', 'cmsdfq8p1000zqchzwkfdzaxb', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"entrada","label":"Salário bruto","valor":4200},{"tipo":"saida","label":"INSS","valor":380},{"tipo":"saida","label":"IRRF","valor":145},{"tipo":"saida","label":"Vale-transporte","valor":175},{"tipo":"saldo","label":"Caiu na conta","valor":3500}],"rodape":"Além disso, o empregador depositou cerca de R$ 336 de FGTS numa conta no nome dele. Esse dinheiro existe e é dele, só não está disponível agora.","headline":"O Paulo combinou R$ 4.200 e recebeu R$ 3.500","personagem":"Paulo, 34 anos, CLT"}'::jsonb, NULL),
  ('cmsdk749x0012z1zhg0k4hp7k', 'cmsdfq8p1000zqchzwkfdzaxb', 2, 'quiz', 'Qual é qual', '{"opcoes":[{"letra":"A","texto":"IRRF","correta":false,"feedback":"IRRF é imposto de renda. Vai para o Tesouro, não para a sua Previdência."},{"letra":"B","texto":"INSS","correta":true,"feedback":"Isso. O INSS é a sua contribuição previdenciária: é ela que conta tempo e gera direito a aposentadoria, auxílio-doença e salário-maternidade."},{"letra":"C","texto":"FGTS","correta":false,"feedback":"O FGTS não é desconto seu, é depósito do empregador. Serve de reserva para demissão, e não conta como tempo de contribuição."},{"letra":"D","texto":"Vale-transporte","correta":false,"feedback":"É a sua parte do custo do transporte, limitada a 6% do salário. Não tem relação com aposentadoria."}],"headline":"Qual desconto vira a sua aposentadoria?"}'::jsonb, NULL),
  ('cmsdk749x0013z1zhvuxxswfp', 'cmsdfq8p1000zqchzwkfdzaxb', 3, 'input', 'O seu', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"bruto","tipo":"decimal","emoji":"📄","label":"Salário bruto","placeholder":"4200"},{"id":"liquido","tipo":"decimal","emoji":"🏦","label":"O que caiu","placeholder":"3500"}],"headline":"Pega o seu holerite","subtitulo":"Dois números: o salário bruto e o valor que caiu na conta."}'::jsonb, NULL),
  ('cmsdk749x0014z1zhqff3jc3h', 'cmsdfq8p1000zqchzwkfdzaxb', 4, 'resultado', 'A diferença', '{"faixas":[{"cor":"yellow","condicao":"pctMeta >= 25","mensagem":"É um desconto alto. Vale conferir linha por linha: além de INSS e IRRF, pode haver plano de saúde, consignado ou adiantamento que você não lembrava."},{"cor":"green","condicao":"valor > 0","mensagem":"Está na faixa comum para CLT. A maior parte costuma ser INSS e IRRF, nessa ordem."}],"formula":"holerite_descontos","headline":"Saíram <strong>{desconto}</strong>, ou <strong>{pctMeta}%</strong> do bruto.","insightDinamico":"Não reparti a diferença entre INSS e IRRF de propósito: as duas tabelas são progressivas, mudam todo ano e dependem dos seus dependentes. Um número estimado aqui pareceria exato e estaria errado. Os valores reais estão discriminados no seu holerite, linha por linha."}'::jsonb, NULL),
  ('cmsdk749x0015z1zhjrmt9w2x', 'cmsdfq8p1000zqchzwkfdzaxb', 5, 'resultado', 'O 13º', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Ele chega em duas parcelas, e a segunda vem com os descontos. A ordem que funciona:\n\n1. Se existe dívida cara, ela vem primeiro. Nenhuma aplicação rende perto do que o rotativo cobra.\n2. Sem dívida cara, ele vira reserva. É o único mês do ano em que dá para fechar vários meses de colchão de uma vez.\n3. O que sobrar depois disso é seu para gastar sem culpa."}],"headline":"O 13º não é bônus, é salário adiado","insightDinamico":"E o FGTS: ele rende pouco, mas não é dinheiro perdido. Ele existe para o caso de demissão sem justa causa, e sacar por antecipação troca essa proteção por dinheiro hoje."}'::jsonb, NULL),
  ('cmsdk74wf0017z1zh8p9wgbc2', 'cmsdfq98q0016qchzr647gezm', 0, 'conceito', 'Como funciona', '{"corpo":"Numa aposta equilibrada, com chance real de 50%, o pagamento justo seria 2 para 1. A casa paga menos que isso. 1,90, 1,85. A diferença é a margem dela.\n\nEssa margem não aparece em nenhum lugar, não é ilegal e não é trapaça. É o preço do serviço. E ela funciona igual ao juro composto: pequena em cada rodada, inevitável ao longo de muitas.\n\nPor isso apostar mais vezes não aumenta a chance de recuperar. Aumenta a certeza de que a margem vai aparecer.","insight":{"label":"O que os dados brasileiros mostram","texto":"O apostador ativo gasta em média {{gasto_medio_bets}}, e {{apostadores_negativados}} já foram negativados por dívida de aposta."},"headline":"A vantagem da casa é embutida, não escondida"}'::jsonb, NULL),
  ('cmsdk74wf0018z1zhc3zh5t2d', 'cmsdfq98q0016qchzr647gezm', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saida","label":"Apostou no primeiro mês","valor":100},{"tipo":"saida","label":"Perdeu, e dobrou pra recuperar","valor":200},{"tipo":"saida","label":"Perdeu de novo, dobrou de novo","valor":400}],"rodape":"A cada perda, a aposta seguinte cresceu. Não por vício de jogo, mas por uma conta que parece lógica: se eu recuperar, empato. O problema é que a margem da casa incide sobre o valor apostado, e o valor apostado estava crescendo.","headline":"O Diego estava tentando recuperar, não ganhar","personagem":"Diego, 30 anos, motorista"}'::jsonb, NULL),
  ('cmsdk74wf0019z1zh0vpteym8', 'cmsdfq98q0016qchzr647gezm', 2, 'input', 'Seu chute', '{"aviso":"Sem consultar. O chute é o ponto do exercício.","campos":[{"id":"chute","tipo":"decimal","emoji":"🎯","label":"Meu chute","placeholder":"900"}],"headline":"R$ 100 por mês, durante 12 meses","subtitulo":"Alguém aposta R$ 100 todo mês por um ano. No fim desse ano, com quanto essa pessoa fica, na média?"}'::jsonb, NULL),
  ('cmsdk74wf001az1zh09bzwgyp', 'cmsdfq98q0016qchzr647gezm', 3, 'resultado', 'Os dois caminhos', '{"faixas":[{"cor":"red","condicao":"valor > 1200","mensagem":"Você chutou acima do que foi apostado. Isso acontece porque a memória guarda os ganhos com muito mais nitidez que as perdas: é assim que o produto foi desenhado para ser lembrado."},{"cor":"yellow","condicao":"valor >= 0","mensagem":"A direção está certa: sai menos do que entrou. O que quase ninguém dimensiona é o tamanho da diferença ao longo de um ano."}],"formula":"bets_comparacao","headline":"Você chutou <strong>R$ {valor}</strong>. Saíram <strong>{apostado}</strong> da mão.","insightDinamico":"O apostador brasileiro médio perde cerca de {perda} em doze meses. Os mesmos R$ 100 por mês, guardados, viram cerca de {guardado}. A diferença entre os dois caminhos não é sorte: é a margem da casa, aplicada doze vezes."}'::jsonb, NULL),
  ('cmsdk74wf001bz1zhoeze55sf', 'cmsdfq98q0016qchzr647gezm', 4, 'quiz', 'Quando vira problema', '{"opcoes":[{"letra":"A","texto":"Apostar todo fim de semana","correta":false,"feedback":"Frequência sozinha não diz muito. Tem gente que aposta sempre um valor pequeno e planejado, e isso é lazer."},{"letra":"B","texto":"Apostar para recuperar o que já perdeu","correta":true,"feedback":"Esse é o sinal. Perseguir a perda é o mecanismo que transforma lazer em dívida, e é o mais comum de todos."},{"letra":"C","texto":"Perder uma aposta grande","correta":false,"feedback":"Perder faz parte, e uma perda grande isolada não define nada. O que define é o que se faz depois dela."},{"letra":"D","texto":"Usar aplicativo em vez de casa física","correta":false,"feedback":"O canal não muda a matemática. O que muda é a facilidade de repetir, e é por isso que perseguir a perda aparece mais rápido no aplicativo."}],"headline":"Qual destes é o sinal mais claro de que a aposta deixou de ser diversão?"}'::jsonb, NULL),
  ('cmsdk74wf001cz1zhsaplnfnb', 'cmsdfq98q0016qchzr647gezm', 5, 'resultado', 'Se precisar de ajuda', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Apostar é legal para maiores de idade, e este módulo não existe para dizer que você não pode. Ele existe porque a conta é conhecida e quase nunca é mostrada.\n\nSe a aposta virou uma forma de resolver dinheiro, ou se você já apostou dinheiro que precisava para outra coisa, isso tem nome, tem tratamento e não é fraqueza de caráter."}],"headline":"Isto não é sobre força de vontade","insightDinamico":"Onde procurar: o SUS atende transtorno do jogo pela rede de saúde mental, pelos CAPS. E o CVV atende 24 horas, de graça, pelo 188: para qualquer sofrimento, inclusive o de dívida."}'::jsonb, NULL),
  ('cmsdk75ik001ez1zhdpiozy7k', 'cmsdfq9sm001dqchzjfbi4gao', 0, 'conceito', 'Como funciona', '{"corpo":"Eles dependem de três coisas: pressa, medo e autoridade. A ligação diz que houve uma compra suspeita. O parente pede socorro com número novo. O boleto chega igual ao verdadeiro.\n\nO objetivo é sempre tirar de você o tempo de conferir. Por isso a defesa não é ser esperto: é ter uma regra fixa que não depende de como você está se sentindo naquele momento.","insight":{"label":"O tamanho disso","texto":"{{vitimas_golpe}} foram vítimas de golpe digital em 12 meses, e as perdas somaram {{perdas_golpe}} só em 2024."},"headline":"Nenhum golpe moderno depende de você ser distraído"}'::jsonb, NULL),
  ('cmsdk75ik001fz1zhcsxk8nuw', 'cmsdfq9sm001dqchzjfbi4gao', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saldo","label":"Compra suspeita que ela precisava cancelar","valor":2400},{"tipo":"saida","label":"O Pix de segurança que pediram","valor":2400}],"rodape":"Tudo batia: o atendente sabia o nome dela, os quatro últimos dígitos do cartão, e o número no visor era o do banco. O único detalhe fora do lugar era o pedido em si: banco nenhum pede transferência para conta segura, porque isso não existe.","headline":"A Aline recebeu uma ligação da central do banco","personagem":"Aline, 36 anos, professora"}'::jsonb, NULL),
  ('cmsdk75ik001gz1zh1oqbarvx', 'cmsdfq9sm001dqchzjfbi4gao', 2, 'quiz', 'O que fazer', '{"opcoes":[{"letra":"A","texto":"Confirmo os dados pra cancelar rápido","correta":false,"feedback":"É exatamente o que o golpe precisa. A pressa é a ferramenta, e confirmar dados entrega o que falta para eles."},{"letra":"B","texto":"Desligo e ligo eu mesma no número do cartão","correta":true,"feedback":"Certo, e é a única resposta que funciona sempre. Quem liga controla a ligação; quem retorna pelo número oficial controla a verificação."},{"letra":"C","texto":"Peço pra pessoa provar que é do banco","correta":false,"feedback":"Eles têm os seus dados: nome, final do cartão, às vezes até compras recentes. Provar identidade por telefone é justamente o que não dá para fazer."},{"letra":"D","texto":"Bloqueio o cartão pelo aplicativo e continuo ouvindo","correta":false,"feedback":"Bloquear é bom, continuar na linha não. Enquanto você fala, eles trabalham, e o número no visor pode ser clonado."}],"headline":"A ligação diz que há uma compra suspeita e pede confirmação. Você:"}'::jsonb, NULL),
  ('cmsdk75ik001hz1zhh8g1yxsq', 'cmsdfq9sm001dqchzjfbi4gao', 3, 'input', 'O que nunca se passa', '{"aviso":"Não tem pegadinha: todos abaixo são pedidos que banco nenhum faz.","campos":[{"id":"pedido","tipo":"faixa","emoji":"🚫","label":"O mais suspeito","opcoes":[{"valor":"senha","rotulo":"A senha do aplicativo"},{"valor":"pix","rotulo":"Um Pix para conta segura"},{"valor":"codigo","rotulo":"O código que chegou por SMS"},{"valor":"cartao","rotulo":"Entregar o cartão a um portador"}]}],"headline":"Marque o que um banco NUNCA vai te pedir","subtitulo":"Escolha o que você considera o pedido mais suspeito de todos."}'::jsonb, NULL),
  ('cmsdk75ik001iz1zhtwb7l3zp', 'cmsdfq9sm001dqchzjfbi4gao', 4, 'resultado', 'A regra fixa', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Senha, código de SMS, Pix para conta segura, cartão na mão de um portador: nada disso é procedimento de banco nenhum, em nenhuma circunstância.\n\nA regra que resolve todos de uma vez: desconfie, desligue, confirme pelo canal oficial. Não é preciso identificar o golpe: basta nunca agir dentro da ligação que chegou até você."}],"headline":"Todos eram o mais suspeito. Nenhum banco pede nenhum deles","insightDinamico":"E vale para o parente no WhatsApp também: número novo pedindo dinheiro, você liga para o número ANTIGO. Se for verdade, a pessoa atende."}'::jsonb, NULL),
  ('cmsdk75ik001jz1zh949r35fe', 'cmsdfq9sm001dqchzjfbi4gao', 5, 'resultado', 'Se já aconteceu', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"O que fazer, na ordem, e rápido:\n\n1. Avise o banco pelo aplicativo ou pelo telefone oficial e peça o Mecanismo Especial de Devolução do Pix.\n2. Registre boletim de ocorrência, mesmo online. Ele é necessário para qualquer contestação.\n3. Troque as senhas que você informou.\n4. Se houve empréstimo feito no seu nome, conteste formalmente por escrito."}],"headline":"Cair num golpe não é burrice, é a engenharia funcionando","insightDinamico":"Quanto mais rápido o banco souber, maior a chance de bloquear o dinheiro antes de ele sair da conta destino. As primeiras horas valem mais que qualquer coisa que se faça depois."}'::jsonb, NULL),
  ('cmsdk7650001lz1zhx0zl20a1', 'cmsdfuvfw001kn15lnxtqi7i7', 0, 'conceito', 'A assinatura da fraude', '{"corpo":"Investimento de verdade tem os três presos por um elástico: quanto maior o retorno, maior o risco, ou menor a liquidez. Sempre. Quem promete os três no máximo não descobriu um atalho, está pagando os antigos com o dinheiro dos novos.\n\nIsso tem nome: esquema Ponzi. Funciona enquanto entra gente nova, e quebra no dia em que para de entrar. Não é possibilidade: é aritmética.","insight":{"label":"Como reconhecer em uma frase","texto":"Se o retorno é fixo, alto e não depende de nada, o dinheiro não vem de um investimento. Vem de outra pessoa."},"headline":"Retorno alto, garantido e sem risco: os três juntos não existem"}'::jsonb, NULL),
  ('cmsdk7650001mz1zhel508098', 'cmsdfuvfw001kn15lnxtqi7i7', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saida","label":"Entrou com","valor":5000},{"tipo":"entrada","label":"Recebeu nos 3 primeiros meses","valor":1500},{"tipo":"saida","label":"Aportou mais, convencido","valor":15000}],"rodape":"Os primeiros pagamentos são a parte mais importante do esquema: eles não são o retorno, são o marketing. Servem para você confiar, aportar mais e trazer gente. Quando o Rafael tentou sacar os R$ 20 mil, o site estava fora do ar.","headline":"O Rafael foi convidado para um robô de trade","personagem":"Rafael, 32 anos, autônomo"}'::jsonb, NULL),
  ('cmsdk7650001nz1zhda3x1js0', 'cmsdfuvfw001kn15lnxtqi7i7', 2, 'quiz', 'Os sinais', '{"opcoes":[{"letra":"A","texto":"Promete rendimento fixo alto todo mês","correta":true,"feedback":"Esse é o sinal definitivo. Nenhum investimento com retorno alto consegue prometer valor fixo: quem promete não está investindo."},{"letra":"B","texto":"Envolve criptomoeda","correta":false,"feedback":"Cripto é o disfarce da vez, não a fraude em si. Já foi boi gordo, já foi imóvel na planta. O que denuncia é a promessa, não o produto."},{"letra":"C","texto":"Você ganha por indicar amigos","correta":true,"feedback":"Também é sinal forte. Quando a remuneração vem de trazer gente, e não do que o dinheiro rende, você já é parte do mecanismo."},{"letra":"D","texto":"Tem site bonito e escritório","correta":false,"feedback":"Aparência não diz nada, e os grandes esquemas brasileiros tinham os dois. Estrutura cara é despesa de marketing, paga com o dinheiro de quem entrou."}],"headline":"Qual destes é o sinal mais forte de pirâmide?"}'::jsonb, NULL),
  ('cmsdk7650001oz1zh1jyvi4rj', 'cmsdfuvfw001kn15lnxtqi7i7', 3, 'input', 'Avalie a promessa', '{"aviso":"Não tem pegadinha. Escolha o que você faria.","campos":[{"id":"reacao","tipo":"faixa","emoji":"🧠","label":"Minha leitura","opcoes":[{"valor":"bom","rotulo":"Parece bom, vou pesquisar"},{"valor":"duvida","rotulo":"Desconfio, mas quero entender"},{"valor":"nao","rotulo":"Não existe. É fraude."}]}],"headline":"Te ofereceram 10% ao mês, garantido","subtitulo":"O que isso deveria te dizer, antes de qualquer outra coisa?"}'::jsonb, NULL),
  ('cmsdk7650001pz1zhnf1fwiz0', 'cmsdfuvfw001kn15lnxtqi7i7', 4, 'resultado', 'Fazendo a conta', '{"faixas":[{"cor":"red","condicao":"valor >= 0","mensagem":"Se alguém conseguisse isso de forma garantida, não precisaria do seu dinheiro: bastaria pegar emprestado a qualquer taxa do mercado e embolsar a diferença. O fato de precisarem captar com você já responde a pergunta."}],"headline":"10% ao mês são mais de 200% ao ano","insightDinamico":"Como conferir de verdade, em dois minutos: procure o nome da empresa no site da CVM e no do Banco Central. Quem pode captar dinheiro do público é autorizado, e a autorização é pública. Não achou? A resposta é essa."}'::jsonb, NULL),
  ('cmsdk7650001qz1zhz1i8clrw', 'cmsdfuvfw001kn15lnxtqi7i7', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Cripto existe, é legal e algumas pessoas ganham dinheiro com ela. Isso não a torna investimento: sem fluxo de caixa, o preço depende só de alguém pagar mais caro depois.\n\nO Finlow não indica ativo nenhum, e quem indica sem ser autorizado pela CVM está cometendo infração: não fazendo um favor."}],"headline":"Especular não é investir, e nenhum dos dois é apostar","insightDinamico":"A regra que evita quase todo prejuízo: dinheiro que você não pode perder não entra em nada que você não saiba explicar para outra pessoa."}'::jsonb, NULL),
  ('cmsdk76rj001sz1zhcheiy3in', 'cmsdfuw00001rn15lslam76vc', 0, 'conceito', 'O incentivo', '{"corpo":"Todo conteúdo tem um incentivo por trás, e nem sempre ele é ruim. O problema é quando o incentivo é invisível: link de afiliado, comissão por abertura de conta, patrocínio não declarado.\n\nEducação financeira e publicidade podem se parecer muito. A diferença é que uma explica um mecanismo, e a outra encaminha para um produto.","insight":{"label":"Por que isso pega tanto","texto":"Só {{letramento_juros}} conseguem fazer um cálculo de juros simples. Quem não tem como conferir precisa confiar, e é exatamente aí que a confiança vira produto."},"headline":"A pergunta não é se a dica é boa. É quem ganha se você seguir"}'::jsonb, NULL),
  ('cmsdk76rj001tz1zhnt1lta7w', 'cmsdfuw00001rn15lslam76vc', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saida","label":"Aplicou onde indicaram","valor":8000},{"tipo":"entrada","label":"Sacou seis meses depois","valor":6400}],"rodape":"O produto não era fraude: era um investimento de risco alto, apresentado como oportunidade e sem uma palavra sobre risco. O canal recebia comissão por cada conta aberta pelo link. Nada ilegal, nada declarado.","headline":"A Tati seguiu a dica de quem ela achava que era professor","personagem":"Tati, 28 anos, enfermeira"}'::jsonb, NULL),
  ('cmsdk76rj001uz1zh7yrebuc0', 'cmsdfuw00001rn15lslam76vc', 2, 'quiz', 'Educação ou propaganda', '{"opcoes":[{"letra":"A","texto":"Educativo explica o mecanismo; propaganda te leva a um produto","correta":true,"feedback":"Isso. Conteúdo que ensina serve mesmo que você nunca compre nada. Se a conclusão é sempre um link, era anúncio."},{"letra":"B","texto":"Educativo é gratuito, propaganda é paga","correta":false,"feedback":"Quase tudo nas redes é gratuito para quem assiste. Quem paga é o anunciante, e é por isso que o preço não indica nada."},{"letra":"C","texto":"Educativo tem números, propaganda não","correta":false,"feedback":"Anúncio bom é cheio de números. O que importa é se eles vêm com a fonte e com o risco, não se existem."},{"letra":"D","texto":"Educativo é feito por quem tem certificação","correta":false,"feedback":"Certificação ajuda, mas há conteúdo excelente sem ela e propaganda com ela. O teste do incentivo funciona melhor."}],"headline":"O que separa conteúdo educativo de publicidade disfarçada?"}'::jsonb, NULL),
  ('cmsdk76rj001vz1zhd1wnbsxv', 'cmsdfuw00001rn15lslam76vc', 3, 'input', 'O sinal de alerta', '{"aviso":"Não tem resposta certa: serve para você reparar.","campos":[{"id":"sinal","tipo":"faixa","emoji":"🚩","label":"O que mais vejo","opcoes":[{"valor":"retorno","rotulo":"Promessa de retorno específico"},{"valor":"urgencia","rotulo":"Urgência: acaba hoje, últimas vagas"},{"valor":"semrisco","rotulo":"Nenhuma menção a risco"},{"valor":"link","rotulo":"Link de cadastro na descrição"}]}],"headline":"Qual sinal você mais vê por aí?","subtitulo":"Todos abaixo são bandeiras vermelhas. Escolha a que mais aparece no seu feed."}'::jsonb, NULL),
  ('cmsdk76rj001wz1zhjhxz5gzl', 'cmsdfuw00001rn15lslam76vc', 4, 'resultado', 'O checklist', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"1. Quem ganha se eu fizer isso?\n2. Qual é o risco, dito em voz alta?\n3. A pessoa é autorizada pela CVM a recomendar produto?\n4. A dica serve para qualquer pessoa, ou depende da minha situação?\n\nA quarta é a que mais elimina: nenhuma recomendação séria vale para todo mundo ao mesmo tempo."}],"headline":"Quatro perguntas antes de seguir qualquer dica","insightDinamico":"E vale saber: recomendar produto específico sem autorização da CVM é infração. Explicar como funciona um investimento é permitido a qualquer um: dizer em qual você deve pôr o seu dinheiro, não."}'::jsonb, NULL),
  ('cmsdk76rj001xz1zhqarnxiho', 'cmsdfuw00001rn15lslam76vc', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Urgência é ferramenta de venda, nunca de ensino. Quem quer que você entenda te dá tempo; quem quer que você compre, não.\n\nSe uma oportunidade só existe hoje, ela não era oportunidade. Era prazo de campanha."}],"headline":"O conteúdo bom não te apressa","insightDinamico":"Este app também tem um incentivo, e ele é declarado: o Finlow explica mecanismo e nunca indica onde investir. Quem recomenda produto específico é profissional autorizado pela CVM."}'::jsonb, NULL),
  ('cmsdk77e3001zz1zhnv6fda1z', 'cmsdfuwjq001yn15l8kmfumv8', 0, 'conceito', 'Por que os métodos falham', '{"corpo":"Aquela divisão em porcentagens funciona bem quando entra o mesmo valor todo mês. Com renda que varia, ela quebra: no mês bom sobra e você gasta, no mês ruim falta e você usa o cartão.\n\nPara renda irregular, o que funciona é inverter a lógica. Em vez de dividir o que entrou, você define quanto TIRA, um valor fixo, calculado pela média dos meses ruins, e deixa o excedente numa conta separada, para cobrir os meses fracos.","insight":{"label":"Não é caso raro","texto":"{{sem_controle_orcamento}} não controlam o orçamento, e a informalidade chega a {{informalidade}}. Renda que varia é a regra para muita gente, não a exceção."},"headline":"Quase todo método de orçamento assume salário fixo"}'::jsonb, NULL),
  ('cmsdk77e30020z1zhgdvzn02k', 'cmsdfuwjq001yn15l8kmfumv8', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"entrada","label":"Melhor mês do ano","valor":4100},{"tipo":"entrada","label":"Pior mês do ano","valor":1900},{"tipo":"saldo","label":"O que ele passou a tirar por mês","valor":2200}],"rodape":"Ele parou de gastar conforme entrava e passou a se pagar R$ 2.200 fixos, um pouco acima do pior mês. O que entra além disso fica numa conta separada e cobre os meses fracos. O mês ruim deixou de ser emergência.","headline":"O Sérgio ganha entre R$ 2.000 e R$ 4.000","personagem":"Sérgio, 37 anos, motorista de aplicativo"}'::jsonb, NULL),
  ('cmsdk77e30021z1zhsj1l4wkw', 'cmsdfuwjq001yn15l8kmfumv8', 2, 'quiz', 'Qual método', '{"opcoes":[{"letra":"A","texto":"Dividir cada entrada em porcentagens fixas","correta":false,"feedback":"Com renda variável, a porcentagem do mês bom te acostuma a um padrão que o mês ruim não sustenta."},{"letra":"B","texto":"Tirar um valor fixo por mês, calculado pelo pior mês","correta":true,"feedback":"Isso. Você vira seu próprio empregador e se paga um salário. O excedente do mês bom vira o colchão do mês ruim."},{"letra":"C","texto":"Gastar pouco em tudo, o tempo todo","correta":false,"feedback":"Aperto permanente não é método, é desgaste. Ele funciona algumas semanas e depois estoura."},{"letra":"D","texto":"Esperar a renda estabilizar para organizar","correta":false,"feedback":"É a ordem invertida. O método é justamente o que estabiliza: a renda pode continuar variando para sempre."}],"headline":"Com renda que varia, o que funciona melhor?"}'::jsonb, NULL),
  ('cmsdk77e30022z1zhmkv65ieb', 'cmsdfuwjq001yn15l8kmfumv8', 3, 'input', 'Seus números', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"rendaMedia","tipo":"decimal","emoji":"📈","label":"Média do que entra","placeholder":"3000"},{"id":"gastoFixo","tipo":"decimal","emoji":"🏠","label":"Essencial do mês","placeholder":"1900"}],"headline":"Dois números pra montar o esqueleto","subtitulo":"A média do que entra e o que você gasta com o essencial num mês."}'::jsonb, NULL),
  ('cmsdk77e30023z1zh2t75wl4q', 'cmsdfuwjq001yn15l8kmfumv8', 4, 'resultado', 'Seu esqueleto', '{"faixas":[{"cor":"red","condicao":"pctMeta >= 80","mensagem":"Com o essencial acima de 80%, não há método que resolva sozinho: o caminho é mexer numa conta fixa grande, ou na renda. Método organiza; ele não cria dinheiro."},{"cor":"yellow","condicao":"pctMeta >= 60","mensagem":"É apertado mas administrável. A ordem que funciona: primeiro separa o que vai guardar, depois vive com o resto. Nunca o contrário."},{"cor":"green","condicao":"valor > 0","mensagem":"Você tem folga real. O risco aqui não é faltar: é a folga sumir sem você perceber para onde foi."}],"formula":"orcamento_esqueleto","headline":"O essencial come <strong>{pctMeta}%</strong>. Sobram <strong>{sobra}</strong>.","insightDinamico":"A regra do pague-se primeiro: no dia em que o dinheiro entra, a primeira transferência é para você. O que sobra é o orçamento do mês, e não o contrário, que é como quase todo mundo faz."}'::jsonb, NULL),
  ('cmsdk77e30024z1zhzok4e2st', 'cmsdfuwjq001yn15l8kmfumv8', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Defina um valor fixo mensal, um pouco acima do seu pior mês. Tire só ele. O que entrar além fica separado e cobre os meses fracos.\n\nCom o tempo, esse valor sobe. Mas ele sobe por decisão sua, não porque um mês foi bom."}],"headline":"Um salário para você, pago por você","insightDinamico":"Quem tem renda variável precisa de mais reserva que quem tem salário fixo, não de menos: o colchão faz o papel que a previsibilidade faria."}'::jsonb, NULL),
  ('cmsdk780z0026z1zhz54b3evt', 'cmsdfux390025n15lvjppkfla', 0, 'conceito', 'O que acontece', '{"corpo":"Registrar gasto numa planilha custa: abrir o arquivo, lembrar a categoria, digitar, salvar. Um minuto, talvez dois. Parece nada: mas é um minuto multiplicado por várias vezes ao dia, todo dia, para um benefício que só aparece no fim do mês.\n\nÉ o pior desenho possível para o cérebro humano: custo imediato, recompensa distante. Não existe força de vontade que segure isso por muito tempo, e não deveria mesmo.","insight":{"label":"A pergunta certa","texto":"Não é ''como eu me disciplino mais''. É ''como eu faço isso custar menos''. Todo método que dura resolveu a segunda pergunta."},"headline":"Você não desistiu por preguiça. Desistiu porque custava caro"}'::jsonb, NULL),
  ('cmsdk780z0027z1zh3ch1zx7k', 'cmsdfux390025n15lvjppkfla', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saldo","label":"Primeira tentativa, durou","valor":18},{"tipo":"saldo","label":"Segunda, com app mais completo","valor":11},{"tipo":"saldo","label":"Terceira, com planilha própria","valor":6}],"rodape":"Dias, não reais. Cada tentativa durou MENOS que a anterior, e a razão é contraintuitiva: cada ferramenta era mais completa que a última. Mais campos, mais categorias, mais atrito.","headline":"A Fernanda abandonou três aplicativos","personagem":"Fernanda, 33 anos, arquiteta"}'::jsonb, NULL),
  ('cmsdk780z0028z1zhygmnirjo', 'cmsdfux390025n15lvjppkfla', 2, 'quiz', 'O que reduz o atrito', '{"opcoes":[{"letra":"A","texto":"Categorizar tudo com precisão","correta":false,"feedback":"Precisão é o principal inimigo da constância. Categoria errada e valor aproximado servem; planilha abandonada não serve para nada."},{"letra":"B","texto":"Levar menos de trinta segundos","correta":true,"feedback":"Isso. Abaixo de meio minuto, o registro cabe na vida real: no ônibus, na fila, esperando o café."},{"letra":"C","texto":"Fazer uma vez por semana, com calma","correta":false,"feedback":"Semanal parece mais fácil e é mais difícil: você não lembra dos gastos pequenos, e a sessão vira uma tarefa grande que dá para adiar."},{"letra":"D","texto":"Estar preso a algo que você já faz todo dia","correta":true,"feedback":"Também certo. Hábito novo pega carona em hábito velho: depois do café, na fila do almoço, ao deitar."}],"headline":"O que faz um registro sobreviver a dois meses?"}'::jsonb, NULL),
  ('cmsdk780z0029z1zhu69xwo9j', 'cmsdfux390025n15lvjppkfla', 3, 'input', 'Seu gancho', '{"aviso":"Escolha o que for verdade pra você, não o que parece mais certo.","campos":[{"id":"momento","tipo":"faixa","emoji":"⏰","label":"Meu momento","opcoes":[{"valor":"manha","rotulo":"De manhã, com o café"},{"valor":"almoco","rotulo":"Na pausa do almoço"},{"valor":"volta","rotulo":"Na volta pra casa"},{"valor":"noite","rotulo":"Antes de dormir"}]}],"headline":"Quando você vai fazer o seu check de trinta segundos?","subtitulo":"Escolha um momento que já existe no seu dia. O horário importa menos que ele ser fixo."}'::jsonb, NULL),
  ('cmsdk780z002az1zhjtwvvbmc', 'cmsdfux390025n15lvjppkfla', 4, 'resultado', 'A conta do esforço', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Não porque somam mais tempo: somam menos. Ganham porque acontecem.\n\nA planilha caprichada de uma hora tem duas propriedades ruins: é fácil de adiar, e quando você adia duas vezes, ela vira uma dívida de trabalho que ninguém quer pagar."}],"headline":"Trinta segundos por dia ganham de uma hora por mês","insightDinamico":"Comece pelo mínimo que você consegue manter numa semana ruim, não numa semana boa. É a semana ruim que decide se o hábito sobrevive."}'::jsonb, NULL),
  ('cmsdk780z002bz1zhmnho82y7', 'cmsdfux390025n15lvjppkfla', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Você não precisa registrar centavo. Precisa saber a ordem de grandeza: quanto foi para comida, quanto foi para transporte, quanto foi para o resto.\n\nO Finlow foi desenhado para isso: você conta no chat, ele entende, e você confirma. É o registro mais barato que consegui imaginar."}],"headline":"Aproximado e feito ganha de exato e abandonado","insightDinamico":"E se falhar um dia, não recomeça do zero. Falhar um dia é normal; tratar a falha como fracasso é o que faz parar de vez."}'::jsonb, NULL),
  ('cmsdk78nt002dz1zh2omqtfna', 'cmsdg6eqb002c13u2wkr6ztmi', 0, 'conceito', 'O que muda', '{"corpo":"CNPJ para emitir nota, uma alíquota fixa mensal no lugar de imposto sobre cada serviço, e cobertura previdenciária: aposentadoria, auxílio-doença, salário-maternidade.\n\nO MEI paga o DAS, uma guia única e barata, todo mês. Quem não formaliza e não contribui como autônomo não acumula tempo: continua trabalhando, mas sem nada por trás se ficar doente ou parar.","insight":{"label":"O tamanho e o buraco","texto":"São {{mei_total}} no Brasil, mas {{mei_inadimplente_das}}. Guia atrasada não conta tempo de contribuição: é o erro mais caro e mais silencioso do MEI."},"headline":"Formalizar é trocar informalidade por três coisas concretas"}'::jsonb, NULL),
  ('cmsdk78nt002ez1zhkey7tvs4', 'cmsdg6eqb002c13u2wkr6ztmi', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"entrada","label":"Fatura por mês, em média","valor":3200},{"tipo":"saida","label":"Custo do DAS se fosse MEI","valor":76},{"tipo":"saldo","label":"Tempo de contribuição acumulado","valor":0}],"rodape":"Doze anos de trabalho que não contam para nada. O valor mensal que resolveria isso é menor do que ela gasta com transporte numa semana: o problema nunca foi o preço, foi ninguém ter explicado o que estava em jogo.","headline":"A Luana trabalha há 12 anos e tem zero de contribuição","personagem":"Luana, 35 anos, manicure"}'::jsonb, NULL),
  ('cmsdk78nt002fz1zhla36ksua', 'cmsdg6eqb002c13u2wkr6ztmi', 2, 'quiz', 'O que o DAS cobre', '{"opcoes":[{"letra":"A","texto":"Só o imposto, nada de Previdência","correta":false,"feedback":"A maior parte do DAS é justamente a contribuição previdenciária. É ela que garante o benefício."},{"letra":"B","texto":"Aposentadoria por idade, auxílio-doença e salário-maternidade","correta":true,"feedback":"Isso. Com o DAS em dia você tem cobertura previdenciária básica. A aposentadoria do MEI é por idade e no valor de um salário mínimo."},{"letra":"C","texto":"Aposentadoria por tempo de contribuição","correta":false,"feedback":"Não com a alíquota padrão do MEI. Para contar tempo integral é preciso complementar a contribuição."},{"letra":"D","texto":"FGTS e férias","correta":false,"feedback":"Esses são direitos de vínculo CLT. MEI não tem patrão, então não tem FGTS nem férias remuneradas."}],"headline":"Pagar o DAS do MEI garante o quê?"}'::jsonb, NULL),
  ('cmsdk78nt002gz1zhlsiody2l', 'cmsdg6eqb002c13u2wkr6ztmi', 3, 'input', 'Seu faturamento', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"faturamento","tipo":"decimal","emoji":"💼","label":"Faturamento mensal","placeholder":"3200"}],"headline":"Quanto você fatura por mês, em média?","subtitulo":"O total que entra pelo trabalho, antes de descontar material e custos."}'::jsonb, NULL),
  ('cmsdk78nt002hz1zh2b0qzaz4', 'cmsdg6eqb002c13u2wkr6ztmi', 4, 'resultado', 'Cabe no MEI?', '{"faixas":[{"cor":"green","condicao":"cabe > 0","mensagem":"Cabe no MEI. O teto é anual, não mensal: o que importa é a soma dos doze meses, então um mês forte não desenquadra ninguém."},{"cor":"yellow","condicao":"valor > 0","mensagem":"Passa do teto do MEI. O caminho seria Microempresa, com contabilidade e alíquota diferentes. Vale conversar com um contador antes de decidir."}],"formula":"mei_cabe","headline":"No ano isso dá <strong>{anual}</strong>.","insightDinamico":"O teto do MEI é {{teto_mei}}. E o custo mensal é uma guia fixa e baixa, que não sobe quando você fatura mais: dentro do teto."}'::jsonb, NULL),
  ('cmsdk78nt002iz1zhwql5m9u1', 'cmsdg6eqb002c13u2wkr6ztmi', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"DAS atrasado não conta como contribuição, e é aí que quase 7 milhões de MEIs estão. Programe o débito automático: é o tipo de coisa que ninguém esquece por desleixo, esquece porque a vida acontece.\n\nSe você não é MEI e não contribui, dá para contribuir como autônomo pelo GPS, sem abrir empresa."}],"headline":"A guia em dia é o que vira tempo","insightDinamico":"Regra tributária muda todo ano. Este módulo explica o mecanismo; os valores e alíquotas de hoje você confere no Portal do Empreendedor antes de decidir."}'::jsonb, NULL),
  ('cmsdk79al002kz1zhyfcyr64d', 'cmsdg6faq002j13u2gy4k54uz', 0, 'conceito', 'O que entra no preço', '{"corpo":"O preço mínimo tem três partes: o que você gastou de material, o tempo que levou, e uma margem para o negócio existir.\n\nA parte esquecida é sempre a segunda. Quando você cobra só o material mais um pouco, está trabalhando de graça e chamando isso de lucro, e como o dinheiro entra, demora meses para perceber.","insight":{"label":"Não é impressão","texto":"Quem trabalha por aplicativo ganha em média {{rendimento_app}}, com renda por hora 8,3% menor que a dos demais trabalhadores. Tempo mal precificado tem escala nacional."},"headline":"Quase todo mundo esquece de cobrar o próprio tempo"}'::jsonb, NULL),
  ('cmsdk79al002lz1zhd72xyjmv', 'cmsdg6faq002j13u2gy4k54uz', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"entrada","label":"Cobrava por bolo","valor":60},{"tipo":"saida","label":"Ingredientes","valor":32},{"tipo":"saida","label":"Gás, energia, embalagem","valor":8},{"tipo":"saldo","label":"Sobrava","valor":20}],"rodape":"Vinte reais por três horas de trabalho: menos de R$ 7 por hora. Ela não estava lucrando pouco, estava se pagando abaixo de qualquer piso, e o negócio parecia dar certo porque o dinheiro entrava.","headline":"A Camila vendia bolo no prejuízo e não sabia","personagem":"Camila, 31 anos, confeiteira nas horas vagas"}'::jsonb, NULL),
  ('cmsdk79al002mz1zhumfgur4i', 'cmsdg6faq002j13u2gy4k54uz', 2, 'input', 'Seu produto', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"custoMaterial","tipo":"decimal","emoji":"📦","label":"Material e custos","placeholder":"40"},{"id":"horas","tipo":"decimal","emoji":"⏱️","label":"Horas que leva","placeholder":"3"},{"id":"valorHora","tipo":"decimal","emoji":"💪","label":"Quanto vale sua hora","placeholder":"30"}],"headline":"Pensa num produto ou serviço que você faz","subtitulo":"Quanto custa o material, quanto tempo leva, e quanto vale a sua hora."}'::jsonb, NULL),
  ('cmsdk79al002nz1zho4hwvdz1', 'cmsdg6faq002j13u2gy4k54uz', 3, 'resultado', 'Seu piso', '{"faixas":[{"cor":"green","condicao":"precoNum > 0","mensagem":"Esse é o PISO, não o preço. Ele cobre material e o seu tempo, e não deixa nada para o negócio crescer, para o imprevisto ou para o imposto."}],"formula":"preco_minimo","headline":"Abaixo de <strong>{preco}</strong> você está pagando pra trabalhar.","insightDinamico":"O preço de venda fica acima do piso. Quanto acima depende do que o mercado paga e do que você entrega de diferente: mas nunca abaixo, porque abaixo do piso cada venda te empobrece."}'::jsonb, NULL),
  ('cmsdk79al002oz1zhfniiss94', 'cmsdg6faq002j13u2gy4k54uz', 4, 'quiz', 'PF e PJ', '{"opcoes":[{"letra":"A","texto":"Porque é proibido","correta":false,"feedback":"Não é proibido para autônomo. Atrapalha por outro motivo, mais prático."},{"letra":"B","texto":"Porque você não sabe se o negócio dá lucro","correta":true,"feedback":"Isso. Com tudo junto, o dinheiro do cliente vira dinheiro do mercado e você nunca sabe se ganhou ou perdeu no mês."},{"letra":"C","texto":"Porque o banco cobra mais caro","correta":false,"feedback":"Tarifa é detalhe. O problema real é não enxergar o resultado do que você faz."},{"letra":"D","texto":"Porque atrapalha o imposto de renda","correta":true,"feedback":"Também. Na hora de declarar ou de justificar movimentação, separar economiza tempo e evita explicação difícil."}],"headline":"Por que misturar a conta pessoal com a do trabalho atrapalha?"}'::jsonb, NULL),
  ('cmsdk79al002pz1zhe6xcttc0', 'cmsdg6faq002j13u2gy4k54uz', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Uma conta recebe o que os clientes pagam. Dali sai o material, e uma parte fica como reserva do trabalho: para o equipamento que quebra, o mês fraco, o imposto.\n\nO que sobra você transfere para a sua conta pessoal. Isso é o seu salário, e ele passa a ser um número que você conhece."}],"headline":"Duas contas, e uma reserva do negócio","insightDinamico":"Preço baixo demais não traz cliente fiel: traz cliente que some quando alguém cobra menos. Quem compra por preço vai embora por preço."}'::jsonb, NULL),
  ('cmsdk79x2002rz1zhlvbyb2mu', 'cmsdg6fvy002q13u2iddowm46', 0, 'conceito', 'Declarar x pagar', '{"corpo":"Muita gente que declara não paga nada, e muita gente que não é obrigada a declarar deveria: porque tem imposto retido a devolver.\n\nA obrigação depende de renda no ano, bens, atividade rural e algumas outras situações. A isenção depende da faixa. São dois testes distintos, e confundi-los é o erro mais comum.","insight":{"label":"O que mudou","texto":"Desde janeiro de 2026, quem ganha até {{isencao_ir}} ficou isento do imposto na fonte, o que alcançou cerca de 16 milhões de contribuintes."},"headline":"Declarar e pagar são coisas diferentes"}'::jsonb, NULL),
  ('cmsdk79x2002sz1zhdn055oiu', 'cmsdg6fvy002q13u2iddowm46', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saida","label":"Imposto retido na fonte no ano","valor":1840},{"tipo":"saldo","label":"Devido, depois das deduções","valor":620},{"tipo":"entrada","label":"Restituição que ele quase perdeu","valor":1220}],"rodape":"Ele tinha dois dependentes e despesas de saúde que nunca informou. Não declarar não economizou nada: só deixou com a Receita um dinheiro que era dele.","headline":"O Ricardo achou que não precisava declarar","personagem":"Ricardo, 39 anos, dois filhos"}'::jsonb, NULL),
  ('cmsdk79x2002tz1zhwgwmck0m', 'cmsdg6fvy002q13u2iddowm46', 2, 'quiz', 'O que deduz', '{"opcoes":[{"letra":"A","texto":"Saúde, educação, dependentes e pensão alimentícia judicial","correta":true,"feedback":"Isso. Saúde não tem teto; educação e dependentes têm limites anuais. Pensão só a fixada judicialmente."},{"letra":"B","texto":"Aluguel que você paga","correta":false,"feedback":"Aluguel pago não deduz. Aluguel RECEBIDO, por outro lado, é renda tributável."},{"letra":"C","texto":"Supermercado e contas de casa","correta":false,"feedback":"Despesa de consumo não entra. A lógica das deduções é outra: saúde, educação e dependentes."},{"letra":"D","texto":"Financiamento do imóvel","correta":false,"feedback":"A parcela não deduz. O imóvel entra na declaração de bens pelo valor pago, o que é coisa diferente."}],"headline":"O que pode ser deduzido na declaração completa?"}'::jsonb, NULL),
  ('cmsdk79x2002uz1zhbedwnui0', 'cmsdg6fvy002q13u2iddowm46', 3, 'input', 'Sua situação', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"rendaMes","tipo":"decimal","emoji":"💰","label":"Renda mensal","placeholder":"4200"}],"headline":"Quanto você recebe por mês?","subtitulo":"Some tudo que é tributável: salário, pró-labore, aluguel recebido, aposentadoria."}'::jsonb, NULL),
  ('cmsdk79x2002vz1zhqb1v14dp', 'cmsdg6fvy002q13u2iddowm46', 4, 'resultado', 'A faixa', '{"faixas":[{"cor":"green","condicao":"cabe > 0","mensagem":"Você está na faixa de isenção do imposto retido na fonte. Isso NÃO quer dizer que está dispensado de declarar: obrigação de declarar e isenção de pagar são testes diferentes, e vale conferir os dois."},{"cor":"yellow","condicao":"valor > 0","mensagem":"Acima da faixa de isenção, há imposto retido. Nesse caso as deduções são o que decide se você recebe restituição ou paga a diferença."}],"formula":"ir_isencao","headline":"Com <strong>R$ {valor}</strong> por mês:","insightDinamico":"A isenção hoje é para quem ganha até {{isencao_ir}}. As regras e os limites mudam todo ano, este módulo explica o mecanismo, e os números do ano você confere no site da Receita."}'::jsonb, NULL),
  ('cmsdk79x2002wz1zhleijnic1', 'cmsdg6fvy002q13u2iddowm46', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Uma pasta, física ou no celular, com recibo de saúde, boleto de escola e informe de rendimento. Em março isso vira meia hora em vez de um fim de semana.\n\nE o que mais cai na malha é bobagem: valor de saúde diferente do que o profissional declarou, dependente informado por duas pessoas, renda esquecida de um trabalho antigo."}],"headline":"Guardar comprovante durante o ano é metade do trabalho","insightDinamico":"Isto aqui não é assessoria contábil. Para caso complicado, vários rendimentos, empresa, ganho de capital, exterior, meia hora com um contador custa menos que uma malha fina."}'::jsonb, NULL),
  ('cmsdk7ajh002yz1zhl48yz4x1', 'cmsdg6gj1002x13u2t0r1z1dv', 0, 'conceito', 'Por que dá briga', '{"corpo":"Casais brigam menos por gastar demais e mais por descobrir depois. Uma compra combinada, mesmo grande, raramente vira discussão; uma pequena escondida, quase sempre.\n\nO que resolve não é gastar menos: é ter um lugar onde os números ficam à vista, e um combinado sobre o que precisa de conversa antes.","insight":{"label":"O tamanho disso","texto":"{{brigas_por_dinheiro}} dizem que dinheiro é o principal motivo de briga no relacionamento, e quase metade já escondeu um problema financeiro do parceiro."},"headline":"Quase sempre a briga não é sobre o valor, é sobre a surpresa"}'::jsonb, NULL),
  ('cmsdk7ajh002zz1zh0pngeib9', 'cmsdg6gj1002x13u2t0r1z1dv', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"entrada","label":"Ela ganha","valor":2800},{"tipo":"entrada","label":"Ele ganha","valor":5200},{"tipo":"saida","label":"Cada um pagava, das contas de casa","valor":1900}],"rodape":"Meio a meio parece justo e não é: os R$ 1.900 eram 68% do que ela ganhava e 37% do que ele ganhava. Ela vivia apertada e ele achava que estavam no mesmo barco.","headline":"A Renata e o Paulo dividiam tudo meio a meio","personagem":"Renata e Paulo, 33 e 36, dois filhos"}'::jsonb, NULL),
  ('cmsdk7ajh0030z1zh4em4mlfw', 'cmsdg6gj1002x13u2t0r1z1dv', 2, 'quiz', 'Como dividir', '{"opcoes":[{"letra":"A","texto":"Meio a meio, porque é igual","correta":false,"feedback":"Igual não é justo quando as rendas são diferentes: o mesmo valor pesa muito mais no bolso menor."},{"letra":"B","texto":"Proporcional à renda de cada um","correta":true,"feedback":"Isso. Cada um entra com a mesma FATIA do que ganha, e assim sobra proporcionalmente o mesmo para os dois."},{"letra":"C","texto":"Quem ganha mais paga tudo","correta":false,"feedback":"Cria dependência de um lado e peso de decisão do outro. Costuma virar fonte de conflito, não solução."},{"letra":"D","texto":"Cada um paga contas específicas","correta":false,"feedback":"Funciona no começo e desanda quando as contas mudam de valor. É divisão sem regra, e regra é o que evita a discussão."}],"headline":"Com rendas diferentes, qual divisão costuma funcionar?"}'::jsonb, NULL),
  ('cmsdk7ajh0031z1zhlwurwjkp', 'cmsdg6gj1002x13u2t0r1z1dv', 3, 'input', 'As duas rendas', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"rendaA","tipo":"decimal","emoji":"🙋","label":"Renda de quem ganha mais","placeholder":"5200"},{"id":"rendaB","tipo":"decimal","emoji":"🙋‍♂️","label":"Renda de quem ganha menos","placeholder":"2800"}],"headline":"Quanto entra de cada lado?","subtitulo":"A renda líquida de cada um, o que efetivamente cai na conta."}'::jsonb, NULL),
  ('cmsdk7ajh0032z1zhf21awmls', 'cmsdg6gj1002x13u2t0r1z1dv', 4, 'resultado', 'A divisão justa', '{"faixas":[{"cor":"green","condicao":"valor > 0","mensagem":"Das despesas comuns, cada um entra com essa fatia. Não é caridade nem dependência: é a mesma proporção de esforço dos dois lados, e é isso que faz sobrar o mesmo para cada um."}],"formula":"divisao_casal","headline":"A conta proporcional dá <strong>{pctA}%</strong> e <strong>{pctB}%</strong>.","insightDinamico":"O resto de cada renda continua sendo de cada um, sem prestação de contas. A parte que é comum fica clara; a parte que é sua continua sua, e é justamente isso que faz o combinado durar."}'::jsonb, NULL),
  ('cmsdk7ajh0033z1zhbbf8zogo', 'cmsdg6gj1002x13u2t0r1z1dv', 5, 'resultado', 'E os filhos', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Valor pequeno, data fixa, e liberdade real de errar. Criança que só pode gastar com o que os pais aprovam não está aprendendo a decidir, está executando decisão dos outros.\n\nO erro barato aos oito anos é o que evita o caro aos vinte e oito."}],"headline":"Mesada não é presente, é aula","insightDinamico":"E sobre pensão, se for o caso: o valor sai do binômio necessidade de quem recebe e possibilidade de quem paga. Não existe percentual automático em lei, apesar de a prática girar em torno de 20% a 30% da renda líquida."}'::jsonb, NULL),
  ('cmsdk7bgy0035z1zhpusa9fd6', 'cmsdg6h4t003413u2cpmq9r8m', 0, 'conceito', 'O que falta', '{"corpo":"Toda meta grande precisa de três coisas: valor, prazo e aporte mensal. Faltando qualquer uma, ela não compete com os gastos do dia a dia, e perde sempre, porque o presente sempre grita mais alto.\n\nO aporte é o que transforma a meta em item do orçamento. Enquanto ela for ''um dia'', ela nunca disputa espaço com nada.","insight":{"label":"Onde as pessoas param","texto":"{{pouparam_no_ano}} conseguiram poupar no último ano, mas só uma pequena parte transformou isso em algo com destino. Poupar sem meta costuma virar dinheiro reabsorvido pelo mês seguinte."},"headline":"Meta sem número é desejo, e desejo não entra na conta do mês"}'::jsonb, NULL),
  ('cmsdk7bgy0036z1zhwdpx4suw', 'cmsdg6h4t003413u2cpmq9r8m', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saldo","label":"Entrada que ela precisa","valor":60000},{"tipo":"saida","label":"Dividido por 36 meses","valor":1667},{"tipo":"entrada","label":"O que ela consegue guardar hoje","valor":900}],"rodape":"A conta não fechou, e isso é informação, não fracasso. Com R$ 900 por mês, a mesma entrada leva 67 meses. Ela escolheu esticar para cinco anos e continuar, em vez de descobrir no terceiro ano que não ia dar.","headline":"A Bianca queria dar entrada num apê em três anos","personagem":"Bianca, 30 anos, analista"}'::jsonb, NULL),
  ('cmsdk7bgy0037z1zhwwd5c6ng', 'cmsdg6h4t003413u2cpmq9r8m', 2, 'input', 'Sua meta', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"custo","tipo":"decimal","emoji":"🎯","label":"Quanto custa","placeholder":"60000"},{"id":"meses","tipo":"decimal","emoji":"📅","label":"Em quantos meses","placeholder":"36"}],"headline":"Escolhe uma, a que mais te puxa","subtitulo":"Quanto custa, e em quantos meses você quer chegar lá."}'::jsonb, NULL),
  ('cmsdk7bgy0038z1zho2nmel4m', 'cmsdg6h4t003413u2cpmq9r8m', 3, 'resultado', 'O aporte', '{"faixas":[{"cor":"green","condicao":"porMesNum > 0","mensagem":"Esse é o número que decide tudo. Ou ele cabe no seu mês, ou a meta precisa mudar de prazo, de tamanho, ou você precisa de renda extra. Não existe quarta opção."}],"formula":"sonhador_por_mes","headline":"São <strong>{porMes}</strong> por mês.","insightDinamico":"E ele é conservador de propósito: não contei rendimento nenhum. Se o dinheiro render, você chega antes: o que é uma surpresa boa. O contrário, planejar contando com rendimento que não veio, é a surpresa ruim."}'::jsonb, NULL),
  ('cmsdk7bgy0039z1zh2wrvdmhy', 'cmsdg6h4t003413u2cpmq9r8m', 4, 'quiz', 'Quando não cabe', '{"opcoes":[{"letra":"A","texto":"Esticar o prazo","correta":true,"feedback":"É o ajuste mais simples e o menos doloroso. Dois anos a mais com aporte que cabe vence três anos com aporte que você abandona no segundo mês."},{"letra":"B","texto":"Manter o plano e torcer","correta":false,"feedback":"É o caminho que mais desanima: você falha todo mês contra uma régua impossível, e desiste achando que o problema é você."},{"letra":"C","texto":"Cortar um gasto grande e recorrente","correta":true,"feedback":"Também vale, e rende mais que cortar vários pequenos. Um aluguel, um carro, uma assinatura cara mexem mais que dez cafés."},{"letra":"D","texto":"Financiar o valor todo","correta":false,"feedback":"Financiar a entrada é trocar uma meta por uma dívida. O juro faz o objetivo custar bem mais do que ele custa hoje."}],"headline":"O aporte não cabe no seu mês. O que fazer?"}'::jsonb, NULL),
  ('cmsdk7bgy003az1zh3osm8qfx', 'cmsdg6h4t003413u2cpmq9r8m', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Três metas ao mesmo tempo é o mesmo que nenhuma: o aporte se divide, nenhuma anda visivelmente, e você desiste das três.\n\nEscolhe uma. Bota o aporte no automático no dia em que o dinheiro entra. E revisa a cada três meses, não todo dia."}],"headline":"Uma meta por vez, com data no calendário","insightDinamico":"Importante: a reserva de emergência vem antes da meta. Sem colchão, o primeiro imprevisto consome o que você juntou, e aí a meta volta ao zero junto com a motivação."}'::jsonb, NULL),
  ('cmsdk7c77003cz1zhtk4rnk25', 'cmsdgd4ll003b13cj40cyh79r', 0, 'conceito', 'Nem todo crédito é igual', '{"corpo":"Consignado é desconto direto na folha: como o risco de calote é baixo, o juro é o menor do mercado. Crédito pessoal sem garantia custa várias vezes mais. Rotativo custa várias vezes o crédito pessoal.\n\nQuem tem dívida cara e acesso a crédito barato tem uma jogada disponível que quase ninguém faz: trocar uma pela outra. O total devido não muda; o que cresce em cima dele, sim.","insight":{"label":"A distância entre eles","texto":"Consignado CLT ficava em {{consignado_clt}}. Crédito pessoal comum, perto de {{credito_pessoal}}. E o rotativo do cartão, {{rotativo_medio}}."},"headline":"A diferença entre os créditos é maior que a diferença entre gastar e não gastar"}'::jsonb, NULL),
  ('cmsdk7c77003dz1zhyxtj76sr', 'cmsdgd4ll003b13cj40cyh79r', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saldo","label":"Saldo que rolava no cartão","valor":5000},{"tipo":"saida","label":"Juro que corria por mês","valor":750},{"tipo":"saida","label":"Juro no consignado","valor":160}],"rodape":"A dívida continuou sendo R$ 5.000. O que mudou foi o quanto ela crescia por mês. Trocar não apaga dívida: para de fazer ela correr.","headline":"O Marcos trocou o rotativo por consignado","personagem":"Marcos, 38 anos, CLT"}'::jsonb, NULL),
  ('cmsdk7c77003ez1zhcg5eh1f8', 'cmsdgd4ll003b13cj40cyh79r', 2, 'input', 'Sua dívida', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"saldo","tipo":"decimal","emoji":"💳","label":"Saldo devedor","placeholder":"5000"},{"id":"taxaAtual","tipo":"decimal","emoji":"📈","label":"Taxa ao mês (%)","placeholder":"15"}],"headline":"Qual dívida você tem hoje?","subtitulo":"O saldo devedor e a taxa mensal que ela cobra. A taxa está no extrato ou na fatura."}'::jsonb, NULL),
  ('cmsdk7c77003fz1zho3jk5hpr', 'cmsdgd4ll003b13cj40cyh79r', 3, 'resultado', 'A troca', '{"faixas":[{"cor":"green","condicao":"cabe > 0","mensagem":"A troca faz sentido pela taxa. Mas só vale se o dinheiro novo QUITAR a dívida antiga: pegar consignado e manter o cartão rolando é ficar com as duas."},{"cor":"yellow","condicao":"valor > 0","mensagem":"A sua taxa já está próxima ou abaixo do consignado. Nesse caso a troca não compensa: o ganho seria pequeno e você criaria um novo compromisso."}],"formula":"troca_divida","headline":"Trocar pelo consignado economizaria <strong>{economia}</strong> por mês.","insightDinamico":"E compare sempre pelo CET, não pela taxa nem pela parcela. O CET inclui tarifa, seguro e IOF: é o único número que dá para comparar entre bancos."}'::jsonb, NULL),
  ('cmsdk7c77003gz1zhuyq2yozv', 'cmsdgd4ll003b13cj40cyh79r', 4, 'quiz', 'Quando vira armadilha', '{"opcoes":[{"letra":"A","texto":"Quando o crédito barato vira consumo, não quitação","correta":true,"feedback":"Esse é o desvio mais comum. O consignado foi tomado para trocar dívida, o dinheiro caiu na conta e virou outra coisa, e agora são duas dívidas."},{"letra":"B","texto":"Quando antecipa o saque-aniversário do FGTS","correta":true,"feedback":"Também. Ao aderir, você troca o saque em caso de demissão por parcelas anuais antecipadas. Se for demitido, o dinheiro que existiria para te segurar está comprometido."},{"letra":"C","texto":"Quando a parcela cabe no orçamento","correta":false,"feedback":"Caber é requisito mínimo, não sinal de alerta. O alerta é a parcela caber e o total ser maior do que você percebe."},{"letra":"D","texto":"Quando o prazo é curto","correta":false,"feedback":"Prazo curto costuma ser melhor: parcela maior, juro total menor. O perigoso é o prazo longo com parcela pequena."}],"headline":"Quando o consignado ou o FGTS deixam de ser boa ideia?"}'::jsonb, NULL),
  ('cmsdk7c77003hz1zhxo374upz', 'cmsdgd4ll003b13cj40cyh79r', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"1. Qual é o CET? Não a taxa, não a parcela.\n2. Esse dinheiro vai QUITAR a dívida cara hoje, ou só entrar na conta?\n3. Se eu perder o emprego, o que acontece com essa parcela e com o meu FGTS?\n\nSe a terceira não tem resposta boa, o crédito é caro mesmo com juro baixo."}],"headline":"Três perguntas antes de assinar","insightDinamico":"Regras de consignado e FGTS mudam com frequência. Este módulo explica o mecanismo; os limites e percentuais do momento você confere antes de contratar."}'::jsonb, NULL),
  ('cmsdk7ctq003jz1zh0ae6c76n', 'cmsdgd55b003i13cj883q2dzs', 0, 'conceito', 'Os dois sistemas', '{"corpo":"No Price, a parcela é fixa do começo ao fim. Nas primeiras, quase tudo é juro e quase nada abate a dívida.\n\nNo SAC, você devolve sempre o mesmo pedaço da dívida, e o juro incide sobre um saldo que cai. A parcela começa mais alta e diminui todo mês.\n\nMesma taxa, mesmo prazo: o SAC custa menos juro no total. O Price cabe melhor no orçamento de quem está apertado no começo.","insight":{"label":"Onde as taxas estão","texto":"O financiamento imobiliário ficava em {{financiamento_imovel}}. Bancos costumam limitar a parcela a 30% da renda bruta."},"headline":"A diferença não é a taxa, é como a dívida é devolvida"}'::jsonb, NULL),
  ('cmsdk7ctq003kz1zhjgdhgotw', 'cmsdgd55b003i13cj883q2dzs', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saida","label":"Primeira parcela no Price","valor":2900},{"tipo":"saida","label":"Primeira parcela no SAC","valor":3600},{"tipo":"saida","label":"Parcela do SAC no ano 15","valor":2100}],"rodape":"O SAC começa R$ 700 mais caro e termina bem mais barato. Escolher entre os dois é escolher entre folga agora e economia total, e a resposta depende de qual dos dois aperta mais a sua vida.","headline":"O Paulo e a Renata escolheram entre os dois","personagem":"Paulo e Renata, 36 e 33"}'::jsonb, NULL),
  ('cmsdk7ctq003lz1zhdzjs73do', 'cmsdgd55b003i13cj883q2dzs', 2, 'quiz', 'Qual é qual', '{"opcoes":[{"letra":"A","texto":"Price","correta":false,"feedback":"No Price a parcela é fixa. O que muda por dentro é a proporção entre juro e amortização, mas o valor não muda."},{"letra":"B","texto":"SAC","correta":true,"feedback":"Isso. Amortização constante faz o saldo cair mais rápido, e como o juro incide sobre o saldo, a parcela diminui todo mês."},{"letra":"C","texto":"Os dois, na mesma proporção","correta":false,"feedback":"Só o SAC decresce. É a característica que dá nome ao sistema."},{"letra":"D","texto":"Depende do banco","correta":false,"feedback":"Não depende: são fórmulas padronizadas. O que muda entre bancos é a taxa e as tarifas, não o comportamento da parcela."}],"headline":"Qual sistema começa com parcela maior e vai caindo?"}'::jsonb, NULL),
  ('cmsdk7ctq003mz1zh0d84mk5t', 'cmsdgd55b003i13cj883q2dzs', 3, 'input', 'Seu financiamento', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"valorFinanciado","tipo":"decimal","emoji":"🏢","label":"Valor financiado","placeholder":"300000"},{"id":"anos","tipo":"decimal","emoji":"📅","label":"Prazo em anos","placeholder":"30"}],"headline":"Quanto e por quanto tempo?","subtitulo":"O valor financiado, depois da entrada, e o prazo em anos."}'::jsonb, NULL),
  ('cmsdk7ctq003nz1zhbdwknwhi', 'cmsdgd55b003i13cj883q2dzs', 4, 'resultado', 'A diferença', '{"faixas":[{"cor":"yellow","condicao":"valor > 0","mensagem":"A diferença entre os dois costuma ser maior que o valor do imóvel em prazos longos. É a conta que menos aparece na hora de assinar, e a que mais pesa no total."}],"formula":"price_vs_sac","headline":"Juros no Price: <strong>{jurosPrice}</strong>. No SAC: <strong>{jurosSac}</strong>.","insightDinamico":"Isto é aproximação didática, para você entender a direção: não substitui a planilha do banco. Peça a simulação nos dois sistemas e compare o CET, que é o número que inclui tarifa e seguro."}'::jsonb, NULL),
  ('cmsdk7ctq003oz1zhosdvp13g', 'cmsdgd55b003i13cj883q2dzs', 5, 'resultado', 'Amortizar', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Abater PRAZO economiza muito mais juro: você corta os meses do fim, que são os que mais tempo tiveram para acumular.\n\nAbater PARCELA alivia o mês, e faz sentido quando o orçamento está apertado agora. As duas são válidas: o que não vale é não saber que existem duas."}],"headline":"Amortizar prazo ou parcela?","insightDinamico":"E a pergunta antes de amortizar: existe alguma dívida mais cara? Nenhum imóvel tem juro perto do rotativo, então quitar cartão vem sempre antes de amortizar financiamento."}'::jsonb, NULL),
  ('cmsdk7dg8003qz1zh5g3z27wj', 'cmsdgd5v8003p13cj0plagmjf', 0, 'conceito', 'O que acontece', '{"corpo":"Não é força de expressão. Em exames de imagem, pensar em si mesmo no futuro distante ativa regiões parecidas com as de pensar em outra pessoa.\n\nIsso explica por que é tão difícil guardar: você está sendo convidado a tirar algo de você agora para dar a alguém que o seu cérebro não reconhece como você. O presente ganha sempre: não por indisciplina, por arquitetura.","insight":{"label":"O que a pesquisa mostrou","texto":"Pessoas que viram uma imagem envelhecida de si mesmas passaram a destinar mais dinheiro à aposentadoria. Tornar o eu futuro concreto muda a decisão de hoje."},"headline":"Seu cérebro trata o você de daqui a dez anos como um estranho"}'::jsonb, NULL),
  ('cmsdk7dg8003rz1zhnlp5sdct', 'cmsdgd5v8003p13cj0plagmjf', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saida","label":"O que ele guardaria por mês","valor":300},{"tipo":"saldo","label":"Meses que ele adiou","valor":24},{"tipo":"entrada","label":"O que existiria hoje","valor":7200}],"rodape":"Ele nunca decidiu não guardar. Decidiu começar mês que vem, vinte e quatro vezes seguidas. Cada adiamento isolado foi razoável; a soma deles custou uma reserva inteira.","headline":"O Diego adia guardar há dois anos","personagem":"Diego, 30 anos, vendedor"}'::jsonb, NULL),
  ('cmsdk7dg8003sz1zhd5y3of9k', 'cmsdgd5v8003p13cj0plagmjf', 2, 'input', 'Daqui a cinco anos', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"futuro","tipo":"texto","emoji":"🔮","label":"Em cinco anos, eu…","placeholder":"…moro num lugar meu e não devo pra ninguém"}],"headline":"Onde você quer estar em cinco anos?","subtitulo":"Escreva uma frase. Não precisa ser grandiosa: precisa ser sua."}'::jsonb, NULL),
  ('cmsdk7dg8003tz1zhz88fmow4', 'cmsdgd5v8003p13cj0plagmjf', 3, 'resultado', 'O preço disso', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"O que você escreveu não vai virar realidade por vontade, nem por lembrar dele de vez em quando. Vai virar por um valor que sai da sua conta todo mês, sem passar pela sua decisão.\n\nEsse é o único mecanismo que atravessa o viés do presente: não depender de você estar disposto no dia."}],"headline":"Isso não acontece por decisão. Acontece por transferência","insightDinamico":"Por isso o automático funciona e a força de vontade não. Não porque você é fraco: porque o débito automático acontece antes de existir uma decisão para tomar."}'::jsonb, NULL),
  ('cmsdk7dg8003uz1zhc0xl2wn6', 'cmsdgd5v8003p13cj0plagmjf', 4, 'quiz', 'O que funciona', '{"opcoes":[{"letra":"A","texto":"Guardar o que sobrar no fim do mês","correta":false,"feedback":"Nunca sobra. Não por falta de disciplina: o gasto se expande até ocupar o que existe, e o fim do mês é quando você tem menos disposição."},{"letra":"B","texto":"Transferência automática no dia que o dinheiro entra","correta":true,"feedback":"Isso. Você decide uma vez, e a decisão passa a acontecer sozinha. É o oposto de decidir todo mês."},{"letra":"C","texto":"Se cobrar mais e ter mais disciplina","correta":false,"feedback":"Disciplina é recurso que acaba. Qualquer plano que dependa dela em janeiro vai falhar em março."},{"letra":"D","texto":"Colocar um lembrete no celular","correta":false,"feedback":"Lembrete resolve esquecimento, e o problema não é esquecer: é lembrar e adiar mesmo assim."}],"headline":"Qual estratégia vence o viés do presente?"}'::jsonb, NULL),
  ('cmsdk7dg8003vz1zhk88hr9y4', 'cmsdgd5v8003p13cj0plagmjf', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Escolhe um valor que você não vai sentir falta na primeira semana. Programa para o dia seguinte ao pagamento. E não mexe.\n\nO valor pode ser pequeno. O que importa é que ele acontece sem você."}],"headline":"Automatize, e depois esqueça","insightDinamico":"Um detalhe que faz diferença: deixe em uma conta separada, de preferência num banco que você não usa no dia a dia. O atrito de transferir de volta é o que protege a decisão que você já tomou."}'::jsonb, NULL),
  ('cmsdk7e2k003xz1zh34k7esig', 'cmsdgd6eo003w13cjq8cyew1p', 0, 'conceito', 'Como funciona', '{"corpo":"Quase todo mundo sabe que deveria guardar, comparar antes de comprar, pagar antes do vencimento. A distância entre saber e fazer não se fecha com mais informação.\n\nO que fecha é um plano com gatilho: ''SE acontecer X, ENTÃO eu faço Y''. A frase parece boba e o efeito é dos mais consistentes que a psicologia comportamental já mediu. Ela funciona porque tira a decisão do momento e a coloca antes dele.","insight":{"label":"Por que isso pega","texto":"Intenção genérica compete com o cansaço, a pressa e o humor do dia. Um plano se-então não compete: quando o gatilho acontece, a resposta já está decidida."},"headline":"Saber o que fazer é a parte fácil, e quase nunca é o que falta"}'::jsonb, NULL),
  ('cmsdk7e2k003yz1zh7gcyx72x', 'cmsdgd6eo003w13cjq8cyew1p', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saldo","label":"Meses tentando guardar por vontade","valor":7},{"tipo":"saldo","label":"Quanto tinha guardado ao fim deles","valor":0},{"tipo":"entrada","label":"Guardado nos 3 meses seguintes, com a regra","valor":900}],"rodape":"A regra dela cabia numa linha: se cair o salário, então transfiro R$ 300 na hora. Não mudou nada na renda nem na disciplina: mudou onde a decisão acontecia.","headline":"A Fernanda trocou uma intenção por uma regra","personagem":"Fernanda, 33 anos"}'::jsonb, NULL),
  ('cmsdk7e2k003zz1zh1bkmg29r', 'cmsdgd6eo003w13cjq8cyew1p', 2, 'input', 'O seu plano', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"gatilho","tipo":"texto","emoji":"⚡","label":"SE acontecer…","placeholder":"cair o salário"},{"id":"acao","tipo":"texto","emoji":"✅","label":"ENTÃO eu…","placeholder":"transfiro R$ 200 na hora"}],"headline":"Escreve o seu, agora","subtitulo":"Duas partes: um gatilho que acontece de verdade, e uma ação pequena o bastante para caber."}'::jsonb, NULL),
  ('cmsdk7e2k0040z1zhpfl0z3cf', 'cmsdgd6eo003w13cjq8cyew1p', 3, 'resultado', 'Por que funciona', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"O que diferencia esse plano de uma intenção é o gatilho. ''Vou guardar mais'' compete com tudo que acontecer no dia. ''Se cair o salário, então transfiro'' não compete com nada: ou o gatilho aconteceu, ou não.\n\nQuanto mais específico o gatilho, melhor funciona. ''Quando eu puder'' não é gatilho."}],"headline":"Você acabou de tirar uma decisão do calor do momento","insightDinamico":"Vale para gasto também, e talvez funcione ainda melhor: se der vontade de comprar algo acima de R$ 200, então espero até amanhã. A regra decide antes de o desejo aparecer."}'::jsonb, NULL),
  ('cmsdk7e2k0041z1zhz282syk4', 'cmsdgd6eo003w13cjq8cyew1p', 4, 'quiz', 'Trava de compromisso', '{"opcoes":[{"letra":"A","texto":"Algo que torna o caminho errado mais difícil","correta":true,"feedback":"Isso. Tirar o cartão do celular, deixar a reserva em outro banco, cancelar o um-clique. Você não fica mais forte: o desvio fica mais caro."},{"letra":"B","texto":"Prometer para si mesmo com firmeza","correta":false,"feedback":"Promessa não é trava: ela depende exatamente do recurso que costuma faltar na hora."},{"letra":"C","texto":"Contar o plano pra alguém","correta":true,"feedback":"Também funciona. Compromisso público cria um custo social para desistir, e esse custo age sem você precisar querer."},{"letra":"D","texto":"Anotar num papel e guardar","correta":false,"feedback":"Anotar ajuda a lembrar, mas não muda o custo de desviar. Trava é o que muda o custo."}],"headline":"O que é uma boa trava de compromisso?"}'::jsonb, NULL),
  ('cmsdk7e2k0042z1zhnixsbyid', 'cmsdgd6eo003w13cjq8cyew1p', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Cinco regras ao mesmo tempo viram nenhuma. Escolhe uma, deixa ela rodar por um mês, e só depois acrescenta a segunda.\n\nE se falhar, não é sinal de que não funciona: é sinal de que o gatilho estava vago ou a ação era grande demais. Ajusta o plano, não a sua opinião sobre você."}],"headline":"Um plano por vez, e específico","insightDinamico":"O Finlow pode ser o gatilho: se você registrar um gasto e a conversa mostrar que o mês está apertado, essa é a hora do plano entrar."}'::jsonb, NULL),
  ('cmsdk7eoy0044z1zh3sw28hfa', 'cmsdgd6yk004313cjat22a8pd', 0, 'conceito', 'Nominal e real', '{"corpo":"Ganho nominal é o que aparece no contracheque. Ganho real é o que sobra depois de descontar a inflação: o quanto o seu dinheiro compra de verdade.\n\nUm aumento de 4% num ano em que os preços subiram 4,64% não é aumento: é uma perda de poder de compra disfarçada de boa notícia. E dinheiro parado, sem render nada, perde essa diferença todo ano, em silêncio.","insight":{"label":"Onde estamos","texto":"O IPCA acumulava {{ipca_12m}}, contra uma meta de {{meta_inflacao}}. É o quanto o dinheiro parado encolheu em doze meses."},"headline":"O número subiu. A pergunta é se comprou mais"}'::jsonb, NULL),
  ('cmsdk7eoy0045z1zhffcqr5lm', 'cmsdgd6yk004313cjat22a8pd', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"entrada","label":"Salário antes","valor":3000},{"tipo":"entrada","label":"Depois do aumento de 4%","valor":3120},{"tipo":"saldo","label":"O que precisaria pra empatar","valor":3139}],"rodape":"Ele ganhou R$ 120 a mais e ficou R$ 19 mais pobre. Não é pegadinha nem má-fé do empregador: é o que acontece quando o reajuste fica abaixo da inflação, e quase ninguém faz essa conta.","headline":"O Sérgio comemorou um aumento que foi perda","personagem":"Sérgio, 37 anos"}'::jsonb, NULL),
  ('cmsdk7eoz0046z1zhjo1ijcl8', 'cmsdgd6yk004313cjat22a8pd', 2, 'input', 'Seu dinheiro parado', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"parado","tipo":"decimal","emoji":"🧊","label":"Parado hoje","placeholder":"5000"}],"headline":"Quanto você tem parado, sem render?","subtitulo":"Conta corrente, dinheiro em casa, qualquer valor que não esteja rendendo nada."}'::jsonb, NULL),
  ('cmsdk7eoz0047z1zhqhj060p9', 'cmsdgd6yk004313cjat22a8pd', 3, 'resultado', 'A perda', '{"faixas":[{"cor":"yellow","condicao":"valor > 0","mensagem":"O número na conta continua o mesmo. O que muda é o que ele compra. É a perda mais silenciosa que existe: não aparece em extrato nenhum."}],"formula":"perda_inflacao","headline":"Em um ano isso perde <strong>{perda}</strong> de poder de compra.","insightDinamico":"Isso NÃO quer dizer correr para investir em qualquer coisa. A reserva de emergência pode e deve ficar em algo de saque imediato, mesmo rendendo pouco: o custo de não ter liquidez na hora do aperto é maior que o da inflação."}'::jsonb, NULL),
  ('cmsdk7eoz0048z1zhipdmm6sa', 'cmsdgd6yk004313cjat22a8pd', 4, 'quiz', 'Os índices', '{"opcoes":[{"letra":"A","texto":"IPCA","correta":true,"feedback":"Isso. É o índice oficial, calculado pelo IBGE, e é a ele que a meta de inflação se refere."},{"letra":"B","texto":"IGP-M","correta":false,"feedback":"O IGP-M pega preços no atacado e é bem mais volátil. Ficou conhecido por reajustar aluguel, não por medir o custo de vida."},{"letra":"C","texto":"INPC","correta":false,"feedback":"O INPC é parecido com o IPCA, mas mede famílias de renda mais baixa. Costuma ser usado em reajuste salarial."},{"letra":"D","texto":"Selic","correta":false,"feedback":"Selic é a taxa básica de juros, não índice de preço. Ela é uma das ferramentas para controlar a inflação, não a medida dela."}],"headline":"Qual índice mede a inflação oficial do país?"}'::jsonb, NULL),
  ('cmsdk7eoz0049z1zh5k1cc0wy', 'cmsdgd6yk004313cjat22a8pd', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Na hora do reajuste, compare com a inflação do período: abaixo dela é perda, mesmo que o número tenha subido.\n\nE separe o dinheiro por função. O que é reserva fica líquido, mesmo rendendo pouco. O que não vai ser usado tão cedo é que precisa de destino."}],"headline":"Pense em real, não em nominal","insightDinamico":"O Finlow explica como funciona, mas não indica onde aplicar. Quem recomenda produto específico é profissional autorizado pela CVM."}'::jsonb, NULL),
  ('cmsdk7fbx004bz1zhclh4onpo', 'cmsdgd7i4004a13cj5yivfwoo', 0, 'conceito', 'Juro sobre juro', '{"corpo":"Juro simples incide sempre sobre o valor inicial. Juro composto incide sobre o que já tinha rendido, e é essa diferença que faz o crescimento acelerar sozinho.\n\nO problema é que ninguém consegue simular isso mentalmente. Pedem para você estimar quanto algo vira em dez anos e você projeta uma reta, porque é o que o cérebro sabe fazer. Erra sempre para menos, e erra muito.","insight":{"label":"Não é falta de estudo","texto":"Só {{letramento_juros}} conseguem fazer um cálculo simples de juros. E mesmo quem consegue subestima o crescimento composto: o viés é de projeção, não de conta."},"headline":"O cérebro humano projeta em linha reta. Juro composto não é reta"}'::jsonb, NULL),
  ('cmsdk7fbx004cz1zhw1lcwlxm', 'cmsdgd7i4004a13cj5yivfwoo', 1, 'cenario', 'Começar cedo x aportar muito', '{"linhas":[{"tipo":"entrada","label":"Ela guardou por mês, dos 25 aos 35","valor":200},{"tipo":"entrada","label":"Ele guardou por mês, dos 35 aos 55","valor":400},{"tipo":"saldo","label":"Anos que ela ficou parada, sem aportar","valor":20}],"rodape":"Ela aportou por dez anos e parou. Ele aportou por vinte, o dobro por mês. Aos 55, os montantes chegam perto, e em muitos cenários o dela é maior. A diferença não é quanto: é quando.","headline":"A Camila começou cedo. O irmão dela aportou o dobro","personagem":"Camila, 31 anos"}'::jsonb, NULL),
  ('cmsdk7fbx004dz1zh9txni7di', 'cmsdgd7i4004a13cj5yivfwoo', 2, 'input', 'Seu chute', '{"aviso":"Sem consultar. O chute é o ponto do exercício.","campos":[{"id":"taxaAno","tipo":"decimal","emoji":"📈","label":"Taxa ao ano (%)","placeholder":"10"},{"id":"chute","tipo":"decimal","emoji":"🎯","label":"Anos pra dobrar, no meu chute","placeholder":"10"}],"headline":"A que taxa anual você quer testar?","subtitulo":"Escolha uma taxa e chute em quantos anos o dinheiro dobra a ela."}'::jsonb, NULL),
  ('cmsdk7fbx004ez1zhis8yd6qu', 'cmsdgd7i4004a13cj5yivfwoo', 3, 'resultado', 'A regra do 72', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"A regra do 72 é o atalho: divida 72 pela taxa anual e você tem, por aproximação, os anos para o dinheiro dobrar. Serve para fazer de cabeça, em qualquer conversa, sem calculadora."}],"formula":"regra_72","headline":"Você chutou <strong>{chute}</strong> anos. A conta dá <strong>{anosDobrar}</strong>.","insightDinamico":"E ela vale nos dois sentidos. Uma dívida a 6% ao mês dobra em cerca de um ano. É a mesma matemática que faz o aporte crescer: só que trabalhando contra você."}'::jsonb, NULL),
  ('cmsdk7fbx004fz1zhhnv1j6wy', 'cmsdgd7i4004a13cj5yivfwoo', 4, 'quiz', 'O que pesa mais', '{"opcoes":[{"letra":"A","texto":"Aportar valores altos","correta":false,"feedback":"Ajuda, mas perde para o tempo em prazos longos. Cada ano a mais multiplica tudo que veio antes."},{"letra":"B","texto":"Começar cedo, mesmo com pouco","correta":true,"feedback":"Isso. O tempo é o único fator que não dá para recuperar depois. Dinheiro você consegue aportar mais tarde; anos, não."},{"letra":"C","texto":"Encontrar a aplicação de maior retorno","correta":false,"feedback":"Retorno alto atrai atenção e costuma vir com risco alto. Consistência ao longo de anos ganha de retorno alto por pouco tempo."},{"letra":"D","texto":"Acertar o momento de entrar","correta":false,"feedback":"Tentar acertar o momento é a estratégia que mais custa dinheiro para quem não é profissional, e para muitos que são."}],"headline":"O que pesa mais no montante final?"}'::jsonb, NULL),
  ('cmsdk7fbx004gz1zhdkz94m75', 'cmsdgd7i4004a13cj5yivfwoo', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Juro composto é a coisa mais poderosa a favor de quem guarda e a mais destrutiva contra quem deve. Não existem duas matemáticas: existe uma, e você escolhe de que lado dela fica.\n\nPor isso quitar dívida cara vem antes de investir. Você está do lado errado da mesma alavanca."}],"headline":"O mesmo mecanismo, dos dois lados","insightDinamico":"As taxas aqui são ilustrativas, para mostrar o mecanismo. O Finlow não indica onde aplicar nem promete retorno."}'::jsonb, NULL),
  ('cmsdk7fy6004iz1zhywui2hvn', 'cmsdgd81s004h13cjo5bbbpvo', 0, 'conceito', 'Quem é quem', '{"corpo":"O Banco Central define a Selic a cada 45 dias. Ela é a referência do custo do dinheiro no país: quando sobe, crédito fica mais caro e aplicação pós-fixada rende mais; quando cai, o contrário.\n\nO CDI é a taxa entre bancos, e anda quase colada na Selic. Por isso muita aplicação é descrita como ''% do CDI''. 100% do CDI significa render praticamente o mesmo que a taxa básica.","insight":{"label":"Onde está agora","texto":"A Selic estava em {{selic_atual}}. Mesmo assim, {{poupanca_pct}} ainda mantêm dinheiro na poupança."},"headline":"A Selic é o juro base. Todo o resto anda em volta dela"}'::jsonb, NULL),
  ('cmsdk7fy6004jz1zh0d444q6n', 'cmsdgd81s004h13cjo5bbbpvo', 1, 'cenario', 'A regra da poupança', '{"linhas":[{"tipo":"saldo","label":"Guardado na poupança","valor":10000},{"tipo":"entrada","label":"Rendimento em um ano","valor":600},{"tipo":"saida","label":"O que a inflação levou no mesmo ano","valor":464}],"rodape":"Rendeu 6% e a inflação comeu 4,64%. O ganho real foi de pouco mais de 1%. A poupança não é perda garantida: é um rendimento baixo que muita gente acha que é alto porque o número na conta sobe.","headline":"A Aline tinha dinheiro na poupança e não sabia quanto rendia","personagem":"Aline, 36 anos"}'::jsonb, NULL),
  ('cmsdk7fy6004kz1zhy44csbdz', 'cmsdgd81s004h13cjo5bbbpvo', 2, 'input', 'Seu dinheiro', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"guardadoPoupanca","tipo":"decimal","emoji":"🐷","label":"Na poupança","placeholder":"10000"}],"headline":"Quanto você tem na poupança hoje?","subtitulo":"Se não tiver nada, chuta um valor pra ver a conta funcionando."}'::jsonb, NULL),
  ('cmsdk7fy6004lz1zh99wd9xzu', 'cmsdgd81s004h13cjo5bbbpvo', 3, 'resultado', 'O rendimento', '{"faixas":[{"cor":"yellow","condicao":"valor > 0","mensagem":"Com a Selic acima de 8,5% ao ano, a poupança rende 0,5% ao mês mais TR, e essa regra não muda por mais que a Selic suba. É por isso que ela descola das outras aplicações pós-fixadas quando o juro está alto."}],"formula":"poupanca_rende","headline":"Isso rende cerca de <strong>{guardado}</strong> em um ano.","insightDinamico":"Compare com o que a Selic está pagando: {{selic_atual}}. A diferença entre os dois é o custo de deixar na poupança, e é maior justamente quando o juro está alto, que é agora."}'::jsonb, NULL),
  ('cmsdk7fy6004mz1zhpp4ftym0', 'cmsdgd81s004h13cjo5bbbpvo', 4, 'quiz', '% do CDI', '{"opcoes":[{"letra":"A","texto":"O dobro da Selic","correta":false,"feedback":"100% quer dizer o valor inteiro do CDI, não o dobro de nada. É a taxa cheia, não multiplicada."},{"letra":"B","texto":"Praticamente o mesmo que a taxa básica","correta":true,"feedback":"Isso. O CDI anda quase colado na Selic, então 100% do CDI rende quase o que a taxa básica paga."},{"letra":"C","texto":"100% de lucro sobre o aplicado","correta":false,"feedback":"Esse é o mal-entendido mais comum. O percentual é sobre a TAXA, não sobre o dinheiro aplicado."},{"letra":"D","texto":"Um valor fixo, independente da Selic","correta":false,"feedback":"Ao contrário: é pós-fixado. Se a Selic cair, o rendimento cai junto."}],"headline":"Uma aplicação que paga 100% do CDI rende o quê?"}'::jsonb, NULL),
  ('cmsdk7fy6004nz1zhoslu5o3h', 'cmsdgd81s004h13cjo5bbbpvo', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"É a leitura que serve para os dois lados da sua vida financeira. Com juro alto, quitar dívida vale ainda mais, porque ela cresce mais rápido, e dinheiro parado custa ainda mais caro.\n\nCom juro baixo, o oposto: crédito fica mais acessível e aplicação conservadora rende pouco."}],"headline":"Selic sobe: dívida fica mais cara, aplicação rende mais","insightDinamico":"O Finlow explica o mecanismo e não indica produto: qual aplicação escolher é conversa com profissional autorizado pela CVM."}'::jsonb, NULL),
  ('cmsdk7gkp004pz1zhea05ib0z', 'cmsdgd8ln004o13cj1guggvz9', 0, 'conceito', 'O tripé', '{"corpo":"Toda aplicação equilibra três coisas. Quer sacar a qualquer momento e com risco baixo? O retorno vai ser modesto. Quer retorno alto com segurança? Vai precisar deixar o dinheiro parado por bastante tempo.\n\nNão é opinião nem esperteza de mercado: é como o preço do dinheiro funciona. Quando alguém oferece os três no máximo, o que está sendo omitido é o risco.","insight":{"label":"Quem já está lá","texto":"O Brasil fechou o ano com {{investidores}} investindo, contra 31% em 2021. Ainda são mais de 100 milhões de adultos fora."},"headline":"Liquidez, rentabilidade e segurança: escolha duas"}'::jsonb, NULL),
  ('cmsdk7gkp004qz1zhwen1o8ld', 'cmsdgd8ln004o13cj1guggvz9', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saldo","label":"O que ela tinha","valor":20000},{"tipo":"saldo","label":"Precisava em 6 meses, para a entrada","valor":20000}],"rodape":"Com prazo curto e destino certo, o que importa é o dinheiro estar lá no dia: não render mais alguns por cento. Prazo curto elimina sozinho quase todas as opções, e isso simplifica a decisão em vez de limitá-la.","headline":"A Bianca queria render mais, mas precisava do dinheiro em seis meses","personagem":"Bianca, 30 anos"}'::jsonb, NULL),
  ('cmsdk7gkp004rz1zhja4dekd4', 'cmsdgd8ln004o13cj1guggvz9', 2, 'quiz', 'Para a reserva', '{"opcoes":[{"letra":"A","texto":"Rentabilidade","correta":false,"feedback":"Reserva não existe para render. Existe para estar disponível no pior dia, e rendimento alto costuma custar prazo."},{"letra":"B","texto":"Liquidez, e depois segurança","correta":true,"feedback":"Isso. Poder sacar hoje é o requisito. Segurança vem em seguida, e rendimento é o que sobra da conta: não o objetivo."},{"letra":"C","texto":"Diversificação","correta":false,"feedback":"Diversificar faz sentido para patrimônio de longo prazo. Para a reserva, complexidade é atrito na hora de sacar."},{"letra":"D","texto":"Isenção de imposto","correta":false,"feedback":"Isenção é vantagem, não critério. Muitas aplicações isentas têm prazo de carência, que é justamente o que a reserva não tolera."}],"headline":"Para a reserva de emergência, o que prioriza?"}'::jsonb, NULL),
  ('cmsdk7gkp004sz1zh7zjnzrjk', 'cmsdgd8ln004o13cj1guggvz9', 3, 'input', 'Seu horizonte', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"horizonte","tipo":"faixa","emoji":"⏳","label":"Quando vou precisar","opcoes":[{"valor":"emergencia","rotulo":"Não sei, é pra emergência"},{"valor":"curto","rotulo":"Menos de 2 anos"},{"valor":"medio","rotulo":"De 2 a 5 anos"},{"valor":"longo","rotulo":"Mais de 5 anos"}]}],"headline":"Pra quando é esse dinheiro?","subtitulo":"O prazo muda tudo, mais do que qualquer outra coisa."}'::jsonb, NULL),
  ('cmsdk7gkp004tz1zhuqbabebq', 'cmsdgd8ln004o13cj1guggvz9', 4, 'resultado', 'O que o prazo decide', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Dinheiro de emergência: liquidez imediata, sempre, mesmo rendendo pouco.\n\nMenos de dois anos: não pode oscilar. Prazo curto não dá tempo de recuperar de uma queda.\n\nDe dois a cinco anos: cabe alguma oscilação, desde que a data não seja rígida.\n\nMais de cinco anos: o tempo passa a trabalhar a favor, e aí faz sentido conversar sobre risco com quem pode recomendar."}],"headline":"O prazo é o que escolhe, não o produto","insightDinamico":"Repare que nenhuma dessas frases cita um produto. É de propósito, e é a fronteira do que o Finlow pode dizer: explicar o critério é educação; dizer onde aplicar é recomendação, e recomendação é de profissional autorizado pela CVM."}'::jsonb, NULL),
  ('cmsdk7gkp004uz1zhsea0rija', 'cmsdgd8ln004o13cj1guggvz9', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Renda fixa: você sabe a regra do rendimento na hora de aplicar. Pode ser prefixada, pós-fixada ou atrelada à inflação. Menos oscilação, retorno mais previsível.\n\nRenda variável: o retorno depende do que acontecer. Pode render muito mais e pode dar prejuízo. Só faz sentido com prazo longo e com dinheiro que você não vai precisar."}],"headline":"Renda fixa e renda variável, sem mistério","insightDinamico":"E a ordem que não muda: dívida cara primeiro, reserva depois, investimento por último. Investir com rotativo aberto é como encher um balde furado."}'::jsonb, NULL),
  ('cmsdk7h7m004wz1zhtm5mxull', 'cmsdgd96a004v13cjlo1qvrrf', 0, 'conceito', 'Nominal e efetiva', '{"corpo":"Multiplicar dá a taxa nominal, que não existe na prática. A taxa efetiva considera que o juro do mês incide sobre o juro dos meses anteriores.\n\nÉ por isso que 2% ao mês não são 24% ao ano. São quase 27%. Parece pouca diferença num exemplo pequeno; num financiamento longo, é dinheiro que dá para comprar um carro.","insight":{"label":"O número que resolve","texto":"O CET, Custo Efetivo Total, é o único que junta juro, tarifa, seguro e IOF numa taxa só. É obrigatório informá-lo, e é o único que dá para comparar entre bancos."},"headline":"Uma taxa mensal não vira taxa anual multiplicando por doze"}'::jsonb, NULL),
  ('cmsdk7h7m004xz1zh8c5yoy37', 'cmsdgd96a004v13cjlo1qvrrf', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saldo","label":"Banco A, taxa anunciada de 1,9% a.m.","valor":12400},{"tipo":"saldo","label":"Banco B, taxa anunciada de 2,1% a.m.","valor":11800}],"rodape":"O total pago no banco A foi maior, apesar do juro menor. A diferença estava em tarifa de cadastro e seguro embutido: coisas que a taxa anunciada não mostra e o CET mostra.","headline":"O Ricardo escolheu o crédito de juro menor e pagou mais caro","personagem":"Ricardo, 39 anos"}'::jsonb, NULL),
  ('cmsdk7h7m004yz1zhhibabk3p', 'cmsdgd96a004v13cjlo1qvrrf', 2, 'input', 'Converta', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"taxaMes","tipo":"decimal","emoji":"📊","label":"Taxa ao mês (%)","placeholder":"2"}],"headline":"Qual taxa mensal você quer converter?","subtitulo":"Pega uma taxa de um crédito que te ofereceram, ou testa com qualquer valor."}'::jsonb, NULL),
  ('cmsdk7h7m004zz1zh2tu40kgk', 'cmsdgd96a004v13cjlo1qvrrf', 3, 'resultado', 'No ano', '{"faixas":[{"cor":"yellow","condicao":"valor > 0","mensagem":"Sempre mais que multiplicar por doze. A diferença é o juro sobre juro, e ela cresce rápido conforme a taxa sobe: o que faz taxas altas serem muito piores do que parecem."}],"formula":"taxa_anual","headline":"<strong>{taxaMes}%</strong> ao mês são <strong>{taxaAnual}%</strong> ao ano.","insightDinamico":"É o mesmo motivo pelo qual o rotativo tem número tão alto: uma taxa de dois dígitos ao mês, composta doze vezes, produz um número que ninguém estimaria de cabeça."}'::jsonb, NULL),
  ('cmsdk7h7m0050z1zh4u9t89ha', 'cmsdgd96a004v13cjlo1qvrrf', 4, 'quiz', 'O que o CET inclui', '{"opcoes":[{"letra":"A","texto":"Tarifas, seguro e IOF","correta":true,"feedback":"Isso. São custos reais que você paga e que a taxa anunciada não mostra. Por isso comparar por taxa engana e comparar por CET, não."},{"letra":"B","texto":"Só o juro, calculado direito","correta":false,"feedback":"Se fosse só o juro, taxa e CET seriam iguais. A diferença entre os dois é exatamente o que está embutido."},{"letra":"C","texto":"A inflação do período","correta":false,"feedback":"O CET não corrige por inflação. Ele soma os custos do contrato, não o efeito dos preços."},{"letra":"D","texto":"O lucro do banco","correta":false,"feedback":"O lucro está diluído no juro e nas tarifas, mas não é uma linha separada. O CET mostra o que você paga, não como o banco reparte."}],"headline":"O que entra no CET e não aparece na taxa de juros?"}'::jsonb, NULL),
  ('cmsdk7h7m0051z1zhbyzbq0u7', 'cmsdgd96a004v13cjlo1qvrrf', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"''Qual é o CET desta operação?'' O banco é obrigado a informar, e a resposta é o número que você compara com o de outro banco.\n\nNunca compare pela parcela: parcela pequena com prazo longo esconde total maior. Parcela é sobre caber no mês; CET é sobre quanto custa."}],"headline":"Uma pergunta antes de qualquer crédito","insightDinamico":"Vale para câmbio também: a cotação anunciada raramente é a que você paga. Entre o spread da casa e o IOF, o custo real fica bem acima do número da vitrine, e a lógica de perguntar o total é a mesma."}'::jsonb, NULL),
  ('cmsdk7hu10053z1zhn6n5vl4v', 'cmsdgd9ux005213cjaywxjdbt', 0, 'conceito', 'Fluxo e estoque', '{"corpo":"Renda é quanto passa pela sua mão por mês. Patrimônio é quanto ficou. São coisas independentes: dá para ter renda alta e patrimônio zero, e é bem mais comum do que parece.\n\nQuem confunde os dois mede sucesso pelo salário. Mas salário some quando o emprego some; patrimônio é o que continua existindo, e é ele que dá escolha.","insight":{"label":"Por que isso engana","texto":"Renda alta traz padrão de vida alto, e padrão de vida alto consome o aumento inteiro. O rio engrossa e o reservatório continua vazio."},"headline":"Renda é o rio. Patrimônio é o reservatório"}'::jsonb, NULL),
  ('cmsdk7hu10054z1zhccedkexz', 'cmsdgd9ux005213cjaywxjdbt', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"entrada","label":"Ganha por mês","valor":9000},{"tipo":"saida","label":"Gasta por mês","valor":8800},{"tipo":"saldo","label":"Patrimônio depois de 8 anos","valor":19000}],"rodape":"Ela passou quase R$ 900 mil pela conta em oito anos e reteve 2% disso. Não houve desperdício óbvio: cada aumento veio junto com um carro melhor, um aluguel maior, uma vida um pouco mais cara.","headline":"A Luana ganha bem há oito anos e não tem nada guardado","personagem":"Luana, 35 anos"}'::jsonb, NULL),
  ('cmsdk7hu20055z1zhj0fnv9lv', 'cmsdgd9ux005213cjaywxjdbt', 2, 'input', 'Seus dois números', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"rendaMensal","tipo":"decimal","emoji":"💵","label":"Renda mensal","placeholder":"5000"},{"id":"patrimonio","tipo":"decimal","emoji":"🏛️","label":"Guardado hoje","placeholder":"15000"}],"headline":"Quanto passa e quanto ficou","subtitulo":"Renda mensal, e tudo que você tem guardado ou investido hoje."}'::jsonb, NULL),
  ('cmsdk7hu20056z1zhldbdr4st', 'cmsdgd9ux005213cjaywxjdbt', 3, 'resultado', 'Quanto tempo você tem', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Esse é o número que mede independência, não o salário. Ele responde a única pergunta que importa quando algo dá errado: quanto tempo eu aguento sem receber?"}],"formula":"fluxo_estoque","headline":"Você tem <strong>{mesesRenda}</strong> meses de renda guardados.","insightDinamico":"E ele sobe de dois jeitos: guardando mais, ou precisando de menos. O segundo caminho é mais rápido do que parece: cortar uma despesa fixa alta melhora os dois lados da conta ao mesmo tempo."}'::jsonb, NULL),
  ('cmsdk7hu20057z1zho5ejboh6', 'cmsdgd9ux005213cjaywxjdbt', 4, 'quiz', 'Custo de oportunidade', '{"opcoes":[{"letra":"A","texto":"Compare com o valor da sua hora","correta":true,"feedback":"Isso. R$ 25 por hora pode ser ótimo ou péssimo, e a única forma de saber é comparar com o que a sua hora já vale hoje."},{"letra":"B","texto":"Aceite: dinheiro extra é sempre bom","correta":false,"feedback":"Nem sempre. Oito horas gastas mal custam o descanso, e às vezes custam a energia que renderia mais no trabalho principal."},{"letra":"C","texto":"Considere também o que deixa de fazer","correta":true,"feedback":"Também certo, e é a parte que quase ninguém soma. Custo de oportunidade é o valor da melhor alternativa que você abandonou."},{"letra":"D","texto":"Recuse: bico atrapalha carreira","correta":false,"feedback":"Generalização. Tem bico que abre porta e ensina, e tem bico que só consome tempo. A conta é caso a caso."}],"headline":"Te oferecem um bico de 8 horas por R$ 200. Como avaliar?"}'::jsonb, NULL),
  ('cmsdk7hu20058z1zh1cdolfia', 'cmsdgd9ux005213cjaywxjdbt', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Todo aumento é uma bifurcação, e ela acontece rápido demais para ser percebida. Se o padrão de vida sobe junto, o rio engrossa e o reservatório continua igual.\n\nA regra que funciona: quando a renda subir, direcione uma parte do aumento para o estoque ANTES de ajustar o padrão. Metade dele já muda tudo em poucos anos."}],"headline":"Aumento vira patrimônio ou vira padrão","insightDinamico":"E calcule sua hora pelo menos uma vez. Renda mensal dividida pelas horas realmente trabalhadas, incluindo deslocamento. O número costuma ser menor do que se imagina, e ele muda decisões."}'::jsonb, NULL),
  ('cmsgcmvm90001mv7uex7n3ssb', 'cmsgcmv8s0000mv7unlahq3xd', 0, 'conceito', 'Dinheiro é um acordo', '{"corpo":"Dinheiro não tem valor por si. Uma cédula é papel; um saldo no app é um registro digital. O que sustenta os dois é um acordo coletivo: todo mundo aceita porque confia que os outros também vão aceitar. Antes das moedas, sociedades usaram sal, gado, conchas e metal. Cada formato resolveu um problema de troca e criou limites novos.","headline":"O dinheiro vale porque as pessoas combinaram que vale."}'::jsonb, NULL),
  ('cmsgcmvma0002mv7utkepv387', 'cmsgcmv8s0000mv7unlahq3xd', 1, 'cenario', 'A nota na gaveta', '{"linhas":[{"tipo":"saldo","label":"Nota de 50 cruzados novos","valor":0,"valorTexto":"não compra nada hoje"},{"tipo":"saida","label":"Pix ao pedreiro","valor":300},{"tipo":"saldo","label":"Caixa de laranjas do quintal","valor":0,"valorTexto":"quitou parte, sem registro"}],"rodape":"Tarcísio tem 58 anos e guarda uma nota de 50 cruzados novos numa gaveta. Em 1989 ela comprava um mês de feira; hoje não compra nada, é só lembrança. No mesmo mês, ele pagou o pedreiro de casa com R$ 300 em Pix e ainda deu uma caixa de laranjas do quintal, como o pai dele fazia. As duas coisas quitaram a dívida. Só uma delas aparece em algum registro.","headline":"O que a nota antiga perdeu, e o que a caixa de laranjas nunca teve?","personagem":"Tarcísio"}'::jsonb, NULL),
  ('cmsgcmvma0003mv7u5hpjc9up', 'cmsgcmv8s0000mv7unlahq3xd', 2, 'quiz', 'Por que parou de valer', '{"opcoes":[{"letra":"A","texto":"Porque o papel dela envelheceu e se desgastou.","correta":false,"feedback":"O estado físico não define o valor. Cédulas novas daquela mesma moeda também não compram mais nada hoje."},{"letra":"B","texto":"Porque o acordo coletivo que sustentava aquela moeda foi substituído por outro.","correta":true,"feedback":"Exatamente. Quando a regra e a confiança mudam, o valor migra para a nova moeda e a antiga vira objeto de memória."},{"letra":"C","texto":"Porque o governo escondeu o ouro que garantia o valor dela.","correta":false,"feedback":"Nenhuma das duas moedas era lastreada em ouro. O que muda é a regra e a aceitação das pessoas, não um estoque de metal."}],"headline":"Por que uma cédula antiga como a de Tarcísio deixou de comprar qualquer coisa?"}'::jsonb, NULL),
  ('cmsgcmvma0004mv7udreiily2', 'cmsgcmv8s0000mv7unlahq3xd', 3, 'input', 'Papel ou tela', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"💵","label":"Em papel, dos últimos 7 dias","placeholder":"10%"}],"headline":"Quanto do dinheiro que passou pelas suas mãos nos últimos sete dias foi em papel, e não digital?","subtitulo":"Estimativa serve; não precisa conferir extrato nem contar moedas."}'::jsonb, NULL),
  ('cmsgcmvma0005mv7uq2rfiybk', 'cmsgcmv8s0000mv7unlahq3xd', 4, 'resultado', 'Mesmo acordo, outros rastros', '{"faixas":[{"cor":"green","condicao":"valor == 0","mensagem":"Sua vida financeira já é toda digital. Isso facilita comprovar pagamentos e concentra em poucas empresas o registro do que você compra."},{"cor":"green","condicao":"valor <= 30","mensagem":"É o arranjo mais comum hoje: o papel virou exceção, usado onde o digital falha, custa caro ou não é aceito."},{"cor":"yellow","condicao":"resto","mensagem":"O papel ainda pesa no seu dia a dia. Costuma indicar renda informal, comércio local ou acesso instável à internet, cada um com vantagens e riscos próprios."}],"formula":"valor_direto","headline":"Você estimou <strong>{valorCru}%</strong> em papel","insightDinamico":"Você estimou {valorCru} em papel. Não existe número certo aqui: a proporção muda com a região, a idade e o tipo de trabalho de cada um. O que importa é perceber que dinheiro vivo e saldo digital carregam o mesmo acordo, mas deixam rastros diferentes — em taxa, em privacidade, em prova de que o pagamento aconteceu.\n\nPróximo passo: Pergunte a alguém com mais de 50 anos qual moeda ele usava aos 20."}'::jsonb, NULL),
  ('cmsgcmw640007mv7ubduczi8y', 'cmsgcmvzh0006mv7up6d4mz86', 0, 'conceito', 'O preço tem camadas', '{"corpo":"O preço que você paga não é o custo do produto com um pouco a mais. Ele junta custo de produção, transporte, impostos, aluguel, salários e a margem que o vendedor quer. Em cima disso, oferta e demanda empurram para os dois lados: pouca coisa e muita gente procurando sobe; estoque parado desce. Publicidade e marca também entram na conta.","headline":"Custo é o que o vendedor gasta. Preço é o que ele consegue cobrar."}'::jsonb, NULL),
  ('cmsgcmw640008mv7uqg29zjh4', 'cmsgcmvzh0006mv7up6d4mz86', 1, 'cenario', 'O bolo de pote da Késia', '{"linhas":[{"tipo":"entrada","label":"Preço de venda do pote","valor":12},{"tipo":"saida","label":"Custo por pote","valor":4.2},{"tipo":"saida","label":"Fixos da semana","valor":60},{"tipo":"saldo","label":"Vendidos por semana","valor":0,"valorTexto":"90 potes"},{"tipo":"saldo","label":"Lucro da semana","valor":642}],"rodape":"Késia tem 24 anos e vende bolo de pote na saída da faculdade. Cada pote custa R$ 4,20 em ingredientes e embalagem, e ela gasta R$ 60 por semana com transporte e gás. Vende a R$ 12 e escoa 90 potes por semana. Uma concorrente abriu do lado cobrando R$ 9. Késia pensa em baixar para R$ 9,50, mas aí a margem de cada pote cai quase pela metade.","headline":"Baixar o preço para acompanhar a concorrente vale a pena para Késia?","personagem":"Késia"}'::jsonb, NULL),
  ('cmsgcmw650009mv7u24tvcuuv', 'cmsgcmvzh0006mv7up6d4mz86', 2, 'quiz', 'A conta de baixar o preço', '{"opcoes":[{"letra":"A","texto":"O lucro cai de R$ 642 para R$ 417 por semana, a menos que ela venda mais.","correta":true,"feedback":"Isso. A margem por pote cai de R$ 7,80 para R$ 5,30; para manter o mesmo lucro ela precisaria vender cerca de 133 potes."},{"letra":"B","texto":"O lucro fica igual, porque o custo de cada pote não mudou.","correta":false,"feedback":"O custo não muda, mas quem absorve a diferença é a margem. São R$ 2,50 a menos por pote, ou R$ 225 por semana."},{"letra":"C","texto":"Ela passa a ter prejuízo, porque o preço fica abaixo do custo.","correta":false,"feedback":"R$ 9,50 ainda cobre os R$ 4,20 de custo e as despesas fixas da semana. Continua havendo lucro, só que bem menor."}],"headline":"Com 90 potes por semana, o que acontece com o lucro de Késia se ela baixar de R$ 12 para R$ 9,50?"}'::jsonb, NULL),
  ('cmsgcmw65000amv7umdc9kjl9', 'cmsgcmvzh0006mv7up6d4mz86', 3, 'input', 'Quanto é custo', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"🏷️","label":"Fatia que foi custo","placeholder":"60%"}],"headline":"Pense na última coisa que você comprou. Que fatia do preço você acha que foi custo do vendedor?","subtitulo":"É um palpite: ninguém sabe a planilha do outro de cabeça."}'::jsonb, NULL),
  ('cmsgcmw65000bmv7uq2r86u6u', 'cmsgcmvzh0006mv7up6d4mz86', 4, 'resultado', 'Margem à vista', '{"faixas":[{"cor":"yellow","condicao":"valor < 40","mensagem":"Você imagina uma margem enorme. Ela existe em setores como cosméticos e moda de marca, mas é exceção, não regra."},{"cor":"green","condicao":"valor <= 75","mensagem":"Está na faixa mais comum do comércio. Nela, uma queda de 10% no preço pode derrubar o lucro em muito mais que 10%."},{"cor":"yellow","condicao":"resto","mensagem":"Você vê pouca folga para o vendedor. Em produtos de giro rápido isso é realista; se você achar que é sempre assim, investigue por que o mesmo item varia tanto entre lojas."}],"formula":"valor_direto","headline":"Você chutou <strong>{valorCru}%</strong> de custo","insightDinamico":"Você chutou {valorCru} de custo. No varejo comum, a mercadoria costuma ficar entre 50% e 70% do preço, e o resto paga aluguel, impostos, salários, perdas e o lucro de quem vende. Quem compra quer que essa fatia seja alta; quem vende precisa que sobre. Saber que existe margem é o que permite comparar, questionar e negociar.\n\nPróximo passo: Compare o mesmo produto em três lojas e liste o que explica a diferença."}'::jsonb, NULL),
  ('cmsgcmwpr000dmv7uzyoi44ew', 'cmsgcmwj4000cmv7u4psicxai', 0, 'conceito', 'Onde mora a informação', '{"corpo":"Todo documento financeiro tem um lugar fixo onde a informação que importa aparece. Na fatura do cartão: total, vencimento, encargos e a linha de cada compra. No contrato: prazo, multa por cancelamento, reajuste e o que está fora da cobertura. No boleto: o beneficiário e o valor após o vencimento. Ler é conferir se esses campos batem com o que foi combinado.","headline":"Assinar sem ler não anula seus direitos, mas dificulta muito provar."}'::jsonb, NULL),
  ('cmsgcmwpr000emv7ucokxgk5s', 'cmsgcmwj4000cmv7u4psicxai', 1, 'cenario', 'A fatura que cresceu', '{"linhas":[{"tipo":"saida","label":"Plano contratado","valor":99.9},{"tipo":"saida","label":"Antivírus que ele não pediu","valor":24.9},{"tipo":"saida","label":"Taxa de instalação parcelada","valor":12.6},{"tipo":"saldo","label":"Fatura que chegou","valor":137.4}],"rodape":"Wellington tem 31 anos e assinou um plano de internet por R$ 99,90 ao mês. Na terceira fatura veio R$ 137,40: R$ 99,90 do plano, R$ 24,90 de um pacote de antivírus que ele não pediu e R$ 12,60 de taxa de instalação parcelada. O contrato, na cláusula 8, diz que serviços adicionais dependem de aceite expresso. Ele guardou o e-mail da contratação, sem nenhuma menção ao antivírus.","headline":"O que Wellington deve fazer antes de simplesmente pagar a fatura inteira?","personagem":"Wellington"}'::jsonb, NULL),
  ('cmsgcmwpr000fmv7upiaeq3tr', 'cmsgcmwj4000cmv7u4psicxai', 2, 'quiz', 'Contestar do jeito certo', '{"opcoes":[{"letra":"A","texto":"Não pagar nada até a empresa resolver, já que a cobrança está errada.","correta":false,"feedback":"Deixar a fatura inteira vencer gera juros e negativação sobre a parte que ele realmente deve. Contestar não suspende o que foi contratado."},{"letra":"B","texto":"Pagar o valor que reconhece, abrir reclamação com protocolo e guardar contrato e e-mail.","correta":true,"feedback":"Isso o mantém em dia com o que contratou e cria a prova documental que sustenta o pedido de estorno da cobrança indevida."},{"letra":"C","texto":"Pagar tudo agora e reclamar depois, porque contestar antes é considerado calote.","correta":false,"feedback":"Contestar cobrança indevida é um direito, não calote. Pagar tudo sem registrar a contestação dificulta a devolução depois."}],"headline":"Diante da cobrança do antivírus que não pediu, qual é a atitude que mais protege Wellington?"}'::jsonb, NULL),
  ('cmsgcmwpr000gmv7uyl0x3pxx', 'cmsgcmwj4000cmv7u4psicxai', 3, 'input', 'Você lê o que assina?', '{"campos":[{"id":"valor","tipo":"faixa","emoji":"📄","label":"Documentos lidos até o fim","opcoes":[{"label":"Nenhum","valor":"0"},{"label":"Um ou dois","valor":"1"},{"label":"Metade","valor":"2"},{"label":"Quase todos","valor":"3"},{"label":"Todos","valor":"4"}]}],"headline":"Quantos dos documentos financeiros que você recebeu no último mês você abriu e leu até o fim?","subtitulo":"Vale a impressão geral; não precisa conferir a caixa de entrada."}'::jsonb, NULL),
  ('cmsgcmwpr000hmv7ul8u1fsxi', 'cmsgcmwj4000cmv7u4psicxai', 4, 'resultado', 'Checagem de dois minutos', '{"faixas":[{"cor":"yellow","condicao":"valor <= 1","mensagem":"Cobranças pequenas e recorrentes passam despercebidas justamente aí. Comece pela fatura de maior valor do mês."},{"cor":"green","condicao":"valor <= 3","mensagem":"O hábito já existe. Falta padronizar: sempre os mesmos quatro campos, sempre no mesmo dia do mês."},{"cor":"green","condicao":"resto","mensagem":"Leitura completa é raro. O passo seguinte é guardar contrato, protocolo e comprovante no mesmo lugar, para o dia em que precisar provar algo."}],"formula":"valor_direto","headline":"O que passa sem leitura costuma ser pequeno e mensal","insightDinamico":"Você respondeu {valorCru}. Ler tudo, sempre, não é realista. O que funciona é uma checagem curta e fixa: valor total, vencimento, cobranças que você não reconhece e o que mudou desde o mês passado. Menos de dois minutos por documento já resolve a maior parte dos casos, e o registro de uma contestação vale mais do que a sua memória.\n\nPróximo passo: Abra a última fatura e procure uma cobrança que você não sabe explicar."}'::jsonb, NULL),
  ('cmsgcmxm4000jmv7u4gzow9xu', 'cmsgcmx9h000imv7ukokuwmmi', 0, 'conceito', 'Quem responde por quê', '{"corpo":"Cada parte do sistema financeiro tem um órgão que registra e fiscaliza quem pode operar. Banco Central: bancos, cooperativas e instituições de pagamento. CVM: fundos, corretoras e quem oferece investimento. Susep: seguros e capitalização. Previc: fundos de pensão fechados. Antes de acreditar em qualquer promessa, dá para procurar o nome da empresa no site do órgão certo e ver se ela existe ali.","headline":"Registro no regulador não garante ganho. Garante que existe a quem reclamar."}'::jsonb, NULL),
  ('cmsgcmxm4000kmv7u6jr5film', 'cmsgcmx9h000imv7ukokuwmmi', 1, 'cenario', 'Três fontes, três versões', '{"linhas":[{"tipo":"saldo","label":"Vídeo com 800 mil visualizações","valor":0,"valorTexto":"alcance, não apuração"},{"tipo":"saldo","label":"Matéria de jornal com o nome do CEO","valor":0,"valorTexto":"fonte secundária"},{"tipo":"saldo","label":"Consulta no Banco Central","valor":0,"valorTexto":"empresa não aparece"},{"tipo":"saldo","label":"Promessa anunciada","valor":0,"valorTexto":"4% ao mês"}],"rodape":"Nayara tem 17 anos e precisa escrever um texto de opinião sobre uma empresa que promete render 4% ao mês. Ela acha três fontes: um vídeo com 800 mil visualizações, uma matéria de jornal com o nome do CEO e uma consulta no site do Banco Central, onde a empresa não aparece em nenhuma lista de instituições autorizadas. As três dizem coisas diferentes sobre a mesma empresa.","headline":"Qual dessas fontes ela deve colocar no centro do texto dela?","personagem":"Nayara"}'::jsonb, NULL),
  ('cmsgcmxm4000lmv7usmeqwl50', 'cmsgcmx9h000imv7ukokuwmmi', 2, 'quiz', 'Cada um no seu órgão', '{"opcoes":[{"letra":"A","texto":"Banco Central para os dois, porque ele regula todo o sistema financeiro.","correta":false,"feedback":"O Banco Central cuida de bancos, cooperativas e meios de pagamento. Seguro e fundo têm reguladores próprios."},{"letra":"B","texto":"Susep para o seguro e CVM para o fundo de investimento.","correta":true,"feedback":"Cada um no seu órgão: a Susep supervisiona seguros e capitalização, e a CVM supervisiona fundos e quem os distribui."},{"letra":"C","texto":"Procon para os dois, já que envolvem contratos com consumidores.","correta":false,"feedback":"O Procon atua no conflito de consumo, mas não autoriza nem registra essas empresas. A autorização vem do regulador do setor."}],"headline":"Nayara vai investigar também um seguro de celular e um fundo de investimento. Onde ela confere cada um?"}'::jsonb, NULL),
  ('cmsgcmxm4000mmv7u6dqcm4zv', 'cmsgcmx9h000imv7ukokuwmmi', 3, 'input', 'Sua primeira frase', '{"campos":[{"id":"valor","tipo":"texto","emoji":"✍️","label":"Sua frase de abertura","placeholder":"Vi um anúncio que promete dobrar o dinheiro em 60 dias."}],"headline":"Escreva a frase de abertura de um texto seu sobre uma promessa financeira que você já viu.","subtitulo":"Uma frase basta; é rascunho, não precisa estar pronta para publicar."}'::jsonb, NULL),
  ('cmsgcmxm4000nmv7ur5bpn011', 'cmsgcmx9h000imv7ukokuwmmi', 4, 'resultado', 'Do palpite ao argumento', '{"formula":"valor_direto","headline":"Uma frase vira texto quando dá para conferir","insightDinamico":"Sua abertura: {valorCru}. Um texto de opinião sustenta uma tese com evidência verificável. A estrutura mínima é: o que foi prometido, quem é a empresa, o que o regulador do setor mostra sobre ela e o que você conclui a partir disso. Sem a terceira parte, o texto vira palpite; com ela, vira argumento que outra pessoa consegue conferir.\n\nPróximo passo: Procure o nome de uma empresa financeira no site do Banco Central hoje."}'::jsonb, NULL),
  ('cmsgcmyjx000pmv7upumkezek', 'cmsgcmydd000omv7uxwaygaa4', 0, 'conceito', 'O preço do que você não escolhe', '{"corpo":"Toda escolha financeira tem um preço escondido: o que você deixa de fazer com o mesmo dinheiro. Isso é custo de oportunidade. Ele aparece no tempo — gastar hoje ou daqui a seis meses muda o que aquele valor compra — e no calendário: material escolar em janeiro, passagem em julho. Quem enxerga o que abre mão escolhe com mais informação.","headline":"Não existe escolha grátis: sempre há uma segunda opção que fica para trás."}'::jsonb, NULL),
  ('cmsgcmyjx000qmv7u9asa4pie', 'cmsgcmydd000omv7uxwaygaa4', 1, 'cenario', 'Notebook agora ou em março', '{"linhas":[{"tipo":"entrada","label":"Juntado em freelas","valor":900},{"tipo":"saida","label":"Notebook agora, em dezembro","valor":900},{"tipo":"saida","label":"Mesmo modelo em março","valor":750},{"tipo":"saida","label":"Trabalhos recusados até lá","valor":400}],"rodape":"Rafaela, 19 anos, juntou R$ 900 fazendo freelas de edição de vídeo. Ela quer um notebook usado por R$ 900 agora, em dezembro, quando o preço sobe com a demanda de fim de ano. Em março, o mesmo modelo costuma sair por R$ 750. Só que sem o notebook ela recusa dois trabalhos de R$ 200 cada até lá. Esperar economiza R$ 150 e custa R$ 400 de renda.","headline":"O desconto de março compensa a renda que ela deixa de ganhar até lá?","personagem":"Rafaela"}'::jsonb, NULL),
  ('cmsgcmyjx000rmv7uthcryo2z', 'cmsgcmydd000omv7uxwaygaa4', 2, 'quiz', 'Quem sente mais a inflação', '{"opcoes":[{"letra":"A","texto":"A que gasta quase toda a renda com comida e ônibus","correta":true,"feedback":"Quando quase toda a renda vai para itens que subiram, não há de onde cortar. A mesma inflação pesa mais em quem gasta tudo com o essencial."},{"letra":"B","texto":"A de renda mais alta, porque paga mais imposto","correta":false,"feedback":"Imposto não é o ponto aqui. Renda mais alta tem folga para trocar marcas, adiar compras ou usar reservas, e a alta de preços morde menos."},{"letra":"C","texto":"Todas igualmente, porque o índice é o mesmo para o país","correta":false,"feedback":"O índice é uma média. A cesta de cada família é diferente, e quem consome mais do que subiu perde mais poder de compra."}],"headline":"A inflação de um ano ficou em 5%, puxada por alimentos e transporte. Qual família sente mais o aperto?"}'::jsonb, NULL),
  ('cmsgcmyjx000smv7u2ymz3guz', 'cmsgcmydd000omv7uxwaygaa4', 3, 'input', 'A compra que dá para adiar', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"⏳","label":"Compra que dá para adiar","placeholder":"R$ 320"}],"headline":"Pense em uma compra que você faria neste mês e que dá para adiar. Quanto ela custa?","subtitulo":"Uma estimativa de cabeça basta; não precisa conferir o preço exato."}'::jsonb, NULL),
  ('cmsgcmyjx000tmv7u8rjhf41c', 'cmsgcmydd000omv7uxwaygaa4', 4, 'resultado', 'O que ficou de fora', '{"faixas":[{"cor":"green","condicao":"valor < 100","mensagem":"Valor pequeno, decisão rápida. Ainda assim, vale a pergunta: em três meses, esse dinheiro faria mais por você em outro lugar?"},{"cor":"yellow","condicao":"valor <= 500","mensagem":"Nessa faixa o calendário conta. Muitos itens caem de preço fora da alta temporada, e a espera costuma valer mais que o desconto de hoje."},{"cor":"yellow","condicao":"resto","mensagem":"Acima disso o custo de oportunidade fica visível: esse valor é reserva para imprevisto, um curso ou várias contas do mês. Escreva as duas alternativas antes de decidir."}],"formula":"valor_direto","headline":"Adiar <strong>R$ {valor}</strong> tem um preço e um ganho","insightDinamico":"Adiar essa compra de {valor} não é só guardar dinheiro. É comparar duas coisas: o que ela resolve hoje e o que o mesmo valor resolve daqui a alguns meses, já contando que preços mudam. A sazonalidade ajuda quem consegue esperar, e a inflação cobra de quem não consegue. A decisão muda conforme a folga que você tem.\n\nPróximo passo: Anote o preço dessa compra hoje e confira o mesmo item daqui a 30 dias."}'::jsonb, NULL),
  ('cmsgcmz3p000vmv7uqclrwufw', 'cmsgcmyx1000umv7uob8kdik1', 0, 'conceito', 'As três colunas do mês', '{"corpo":"Orçamento é uma folha com três colunas: o que entra, o que sai sempre e o que sai às vezes. Gastos fixos repetem — aluguel, transporte, assinatura. Variáveis oscilam — comida fora, presentes, farmácia. E existem os imprevistos, que ninguém agenda mas todo mês aparecem. Orçamento não é previsão perfeita: é ter o número na frente antes de decidir.","headline":"Quem não escreve o orçamento acredita que sobra mais do que sobra."}'::jsonb, NULL),
  ('cmsgcmz3p000wmv7ufgrt3l8j', 'cmsgcmyx1000umv7uob8kdik1', 1, 'cenario', 'A sobra que sumia', '{"linhas":[{"tipo":"entrada","label":"Entra por mês","valor":3200},{"tipo":"saida","label":"Fixos","valor":1840},{"tipo":"saida","label":"Variáveis, na média","valor":950},{"tipo":"saldo","label":"Sobra no papel","valor":410},{"tipo":"saldo","label":"Imprevisto, em 4 dos últimos 6 meses","valor":0,"valorTexto":"de R$ 200 a R$ 500"}],"rodape":"Everton, 34 anos, recebe R$ 3.200 por mês e mora com a filha. Fixos: aluguel R$ 1.100, transporte R$ 280, internet e celular R$ 160, escola R$ 300. Variáveis, na média: mercado R$ 700, farmácia e lazer R$ 250. No papel sobram R$ 410. Só que em quatro dos últimos seis meses apareceu algo fora da conta — dentista, pneu, uniforme — entre R$ 200 e R$ 500.","headline":"Se o imprevisto acontece quase todo mês, ele ainda pode ficar fora do orçamento?","personagem":"Everton"}'::jsonb, NULL),
  ('cmsgcmz3p000xmv7uml0eayd0', 'cmsgcmyx1000umv7uob8kdik1', 2, 'quiz', 'Onde está o furo', '{"opcoes":[{"letra":"A","texto":"Cortar o lazer de R$ 250 até zerar esse gasto","correta":false,"feedback":"Corte total costuma durar poucas semanas e não cobre o imprevisto do mês seguinte. O problema não é o lazer, é a linha que falta no orçamento."},{"letra":"B","texto":"Criar uma linha mensal de imprevistos, separada da sobra","correta":true,"feedback":"Se o inesperado aparece em quatro de cada seis meses, ele é previsível o bastante para virar linha do orçamento. Aí a sobra vira sobra de verdade."},{"letra":"C","texto":"Esperar o mês fechar e usar o cartão quando faltar","correta":false,"feedback":"Isso empurra o problema para frente com juros junto. O gasto não some, só chega maior no mês seguinte."}],"headline":"Everton quer que a sobra pare de sumir. Qual mudança resolve melhor o problema dele?"}'::jsonb, NULL),
  ('cmsgcmz3p000ymv7ujvqkl5li', 'cmsgcmyx1000umv7uob8kdik1', 3, 'input', 'Monte a sua conta', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"🧮","label":"Quanto sobra no seu mês","placeholder":"R$ 240"}],"headline":"Monte a conta: tudo que entra no mês, menos os gastos fixos e a média dos variáveis. Quanto sobra?","subtitulo":"Estimativa serve: use números redondos e a média dos últimos meses."}'::jsonb, NULL),
  ('cmsgcmz3p000zmv7ulhg6y8nh', 'cmsgcmyx1000umv7uob8kdik1', 4, 'resultado', 'Sua sobra real', '{"faixas":[{"cor":"red","condicao":"valor < 0","mensagem":"O mês fecha no vermelho antes de qualquer imprevisto. A saída passa por cortar ou renegociar um gasto fixo, não por apertar os variáveis por algumas semanas."},{"cor":"yellow","condicao":"valor <= 300","mensagem":"A sobra existe, mas um imprevisto médio consome ela inteira. Separar uma parte fixa por mês para o inesperado evita que a sobra vire dívida."},{"cor":"green","condicao":"resto","mensagem":"Com essa folga dá para dividir a sobra em destinos: imprevisto, objetivo de curto prazo e uso livre. Sobra sem destino tende a sumir."}],"formula":"valor_direto","headline":"Sua sobra real: <strong>R$ {valor}</strong>","insightDinamico":"Sua sobra estimada é {valor}. Esse número é o orçamento funcionando: ele mostra quanto do mês já está comprometido antes de qualquer decisão. A sobra só é real quando os imprevistos têm linha própria e as despesas variáveis são a média dos últimos meses, não o melhor mês. Refaça a conta quando a renda ou um gasto fixo mudar.\n\nPróximo passo: Escreva num papel só as três linhas: entra, fixo e variável médio."}'::jsonb, NULL),
  ('cmsgcmznk0011mv7u7pv4xxgs', 'cmsgcmzgw0010mv7u03vntkgt', 0, 'conceito', 'Preço não é só a etiqueta', '{"corpo":"Preço justo não é o menor número da tela. É o menor custo total para o que você precisa, no prazo que você precisa. Some frete, taxa de entrega, juros do parcelamento, garantia e o custo de esperar quinze dias. Pesquisar é comparar três ofertas na mesma base. Negociar é pedir — desconto à vista, frete grátis, prazo menor — sabendo o que você aceita.","headline":"Compare custo total e prazo, não a etiqueta."}'::jsonb, NULL),
  ('cmsgcmznk0012mv7uk6vt18pi', 'cmsgcmzgw0010mv7u03vntkgt', 1, 'cenario', 'Três ofertas, uma decisão', '{"linhas":[{"tipo":"saida","label":"Loja A — à vista, hoje","valor":1400},{"tipo":"saida","label":"Loja B — com frete, 20 dias","valor":1380},{"tipo":"saida","label":"Site C — à vista, 12 dias","valor":1180},{"tipo":"saida","label":"O que ela gasta hoje em transporte","valor":180}],"rodape":"Iasmin, 22 anos, precisa de uma bicicleta para ir ao trabalho e parar de gastar R$ 180 por mês em transporte. Loja A: R$ 1.400 à vista, retirada hoje. Loja B: R$ 1.290, frete R$ 90, entrega em 20 dias. Site C: R$ 1.180 à vista ou 10x de R$ 138, entrega em 12 dias, sem loja física para garantia. Ela tem R$ 1.500 guardados.","headline":"Qual oferta custa menos de verdade, considerando frete, juros e dias de espera?","personagem":"Iasmin"}'::jsonb, NULL),
  ('cmsgcmznk0013mv7u8veb53tq', 'cmsgcmzgw0010mv7u03vntkgt', 2, 'quiz', 'Como se pede desconto', '{"opcoes":[{"letra":"A","texto":"Dizer que só compra se derem 40% de desconto","correta":false,"feedback":"Pedido sem base e fora da margem da loja costuma encerrar a conversa. Negociação precisa de um número que o outro lado consiga aceitar."},{"letra":"B","texto":"Mostrar o preço da concorrente e pedir R$ 1.290 à vista, levando hoje","correta":true,"feedback":"Negociação funciona com informação e contrapartida: você traz um preço real de mercado e oferece pagamento imediato, que reduz custo e risco para a loja."},{"letra":"C","texto":"Aceitar o preço da etiqueta, porque desconto só existe em data promocional","correta":false,"feedback":"Em compras de valor maior, à vista ou em lojas com margem, pedir é comum. Não perguntar é abrir mão de um desconto que já existia."}],"headline":"Iasmin liga para a loja A e quer negociar. Qual pedido tem mais chance de funcionar?"}'::jsonb, NULL),
  ('cmsgcmznk0014mv7ud8x72vja', 'cmsgcmzgw0010mv7u03vntkgt', 3, 'input', 'Sua última pesquisa', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"🔍","label":"Lugares comparados","placeholder":"3"}],"headline":"Na sua última compra acima de R$ 200, em quantos lugares diferentes você comparou o preço?","subtitulo":"Vale o número aproximado; precisão não é exigida aqui."}'::jsonb, NULL),
  ('cmsgcmznk0015mv7uxen4u54h', 'cmsgcmzgw0010mv7u03vntkgt', 4, 'resultado', 'O que a pesquisa te dá', '{"faixas":[{"cor":"yellow","condicao":"valor <= 1","mensagem":"Sem comparação, o preço pago foi o primeiro que apareceu. Abrir mais duas abas é o passo com maior retorno por minuto gasto."},{"cor":"yellow","condicao":"valor == 2","mensagem":"Duas ofertas mostram uma diferença, mas não mostram a faixa de preço do item. A terceira é que revela se a barata é barata mesmo."},{"cor":"green","condicao":"resto","mensagem":"Boa base de comparação. O próximo ganho vem de padronizar a conta: preço mais frete, mais juros do parcelamento, mais custo do prazo de entrega."}],"formula":"valor_direto","headline":"Você comparou <strong>{valorCru}</strong> lugar(es)","insightDinamico":"Você comparou preços em {valorCru} lugares. Três é um bom piso: com menos, não dá para saber se o preço é bom ou só familiar. Comparar custa alguns minutos e costuma valer entre 5% e 20% do valor da compra. E o resultado da pesquisa é a sua carta na hora de negociar: sem ele você pede desconto, com ele você propõe um preço.\n\nPróximo passo: Antes da próxima compra, abra três ofertas e some frete, juros e prazo."}'::jsonb, NULL),
  ('cmsgcn0ka0017mv7uuao1m7xe', 'cmsgcn0680016mv7uqiwp8bsw', 0, 'conceito', 'De quem veio essa vontade', '{"corpo":"Nem toda compra começa numa necessidade. Começa num story, num amigo com o modelo novo, numa data que a publicidade inventou. Esses empurrões não são errados — são invisíveis, e é isso que os torna caros. Ao lado deles existe outra conta: quem produziu, em que condições, quanto o produto dura e o que acontece com ele quando você enjoar.","headline":"A pergunta não é \"eu quero?\", é \"de quem veio essa vontade?\"."}'::jsonb, NULL),
  ('cmsgcn0ka0018mv7uvt3ae8xx', 'cmsgcn0680016mv7uqiwp8bsw', 1, 'cenario', 'Tênis, grupo e curso', '{"linhas":[{"tipo":"entrada","label":"Juntado para o curso de inglês","valor":700},{"tipo":"saida","label":"Tênis que o grupo comprou","valor":650},{"tipo":"saldo","label":"Duração média do tênis","valor":0,"valorTexto":"um ano"},{"tipo":"saldo","label":"Vezes que o curso já foi adiado","valor":0,"valorTexto":"duas"}],"rodape":"Caio, 17 anos, juntou R$ 700 de trabalho no fim de semana para um curso de inglês. Aí três amigos compraram o mesmo tênis de R$ 650, lançamento com campanha grande, e o grupo não fala de outra coisa. Ele leu que a marca responde a processos por condições de trabalho na fábrica. O tênis dura, em média, um ano. O curso, ele já adiou duas vezes.","headline":"O que decide aqui: o plano dele, o grupo ou a campanha?","personagem":"Caio"}'::jsonb, NULL),
  ('cmsgcn0ka0019mv7u0cjh8x62', 'cmsgcn0680016mv7uqiwp8bsw', 2, 'quiz', 'Prós e contras de verdade', '{"opcoes":[{"letra":"A","texto":"Listar preço e condição de pagamento, porque o resto é opinião","correta":false,"feedback":"Preço e prazo são metade da conta. Ficam de fora o uso real, a durabilidade, o impacto social e ambiental e o plano que a compra atrasa."},{"letra":"B","texto":"Perguntar aos amigos se o tênis vale a pena","correta":false,"feedback":"O grupo é justamente uma das forças que criou a vontade. Consultá-lo tende a confirmar a decisão em vez de testá-la."},{"letra":"C","texto":"Esperar 72 horas e reler o objetivo daquele dinheiro antes de decidir","correta":true,"feedback":"O intervalo separa desejo de impulso, e o objetivo escrito devolve a comparação: curso ou tênis. A conta passa a incluir o que o dinheiro já tinha para fazer."}],"headline":"Caio quer decidir sem se enganar. Qual método pesa melhor os prós e contras dessa compra?"}'::jsonb, NULL),
  ('cmsgcn0ka001amv7ul56e6ab7', 'cmsgcn0680016mv7uqiwp8bsw', 3, 'input', 'Compras fora do plano', '{"campos":[{"id":"valor","tipo":"faixa","emoji":"🛒","label":"Gasto fora do plano, 30 dias","opcoes":[{"label":"Nada","valor":"0"},{"label":"Até R$ 50","valor":"25"},{"label":"R$ 50 a R$ 200","valor":"125"},{"label":"R$ 200 a R$ 500","valor":"350"},{"label":"Mais de R$ 500","valor":"600"}]}],"headline":"Nos últimos 30 dias, quanto você gastou em compras que não estavam no seu plano?","subtitulo":"Escolha a faixa mais próxima; estimativa serve, não precisa somar recibo por recibo."}'::jsonb, NULL),
  ('cmsgcn0ka001bmv7u4zo7fwwu', 'cmsgcn0680016mv7uqiwp8bsw', 4, 'resultado', 'O custo de não perceber', '{"faixas":[{"cor":"green","condicao":"valor == 0","mensagem":"Mês sem desvio costuma significar plano claro ou pouca exposição a gatilho. Vale conferir se foi controle ou só um mês sem lançamento e promoção."},{"cor":"yellow","condicao":"valor <= 200","mensagem":"Faixa comum e administrável. O risco não é o valor do mês, é ele se repetir doze vezes sem nunca entrar na conta."},{"cor":"yellow","condicao":"resto","mensagem":"Nessa faixa, o gasto fora do plano já concorre com um objetivo inteiro. Vale mapear onde a compra começou: anúncio, grupo, aplicativo ou data comercial."}],"formula":"valor_direto","headline":"O gasto fora do plano cabe no mês. E no ano?","insightDinamico":"{valorCru} em compras fora do plano é o preço de um mês de influência: grupo, campanha, data comercial. Não é sobre culpa, é sobre saber quanto custa não perceber. A cada compra, três perguntas dão conta do recado: de onde veio a vontade, quem paga o custo social e ambiental disso, e o que esse dinheiro deixaria de fazer.\n\nPróximo passo: Escolha uma compra pendente e espere 72 horas antes de decidir."}'::jsonb, NULL),
  ('cmsgcn1hu001dmv7ui1zhv62e', 'cmsgcn19b001cmv7u4bw641aj', 0, 'conceito', 'Poupar não é sobrar', '{"corpo":"Poupar sem destino vira dinheiro parado que some no primeiro imprevisto. Quem poupa com objetivo define três coisas antes de escolher onde guardar: para quê, quanto e até quando. Um curso no fim do ano é curto prazo. Trocar de moradia em três anos é médio. Parar de depender de renda um dia é longo. O prazo é o que muda a escolha, não o contrário.","headline":"Sem prazo definido, qualquer aplicação parece boa e nenhuma serve."}'::jsonb, NULL),
  ('cmsgcn1hu001emv7u0amx5bxt', 'cmsgcn19b001cmv7u4bw641aj', 1, 'cenario', 'Duas metas e um atalho', '{"linhas":[{"tipo":"entrada","label":"Guardado hoje","valor":3200},{"tipo":"saida","label":"Notebook, daqui a 6 meses","valor":4000},{"tipo":"saldo","label":"Viagem","valor":0,"valorTexto":"daqui a 3 anos"},{"tipo":"saldo","label":"Proposta do conhecido","valor":0,"valorTexto":"dobrar num fim de semana"}],"rodape":"Renata tem 24 anos e faz freelas de edição de vídeo. Guardou R$ 3.200 e tem dois planos: um notebook novo daqui a seis meses, por volta de R$ 4.000, e uma viagem em três anos. Um conhecido diz que ela dobra esse valor num fim de semana apostando em jogos online. Ele mostra um print de ganho. Não mostra as outras dez apostas da semana.","headline":"O dinheiro dos dois planos deve ficar no mesmo lugar? E a proposta do conhecido?","personagem":"Renata"}'::jsonb, NULL),
  ('cmsgcn1hu001fmv7ukazvoxbk', 'cmsgcn19b001cmv7u4bw641aj', 2, 'quiz', 'Investir ou apostar', '{"opcoes":[{"letra":"A","texto":"O valor envolvido: aposta é com pouco dinheiro, investimento é com muito.","correta":false,"feedback":"O valor não muda a natureza da operação. Dá para apostar alto e investir pouco no mesmo dia."},{"letra":"B","texto":"A origem do retorno: investimento remunera capital emprestado ou produtivo; aposta paga com a perda de outro apostador.","correta":true,"feedback":"Investir compra um direito sobre juros, lucros ou aluguéis. Na aposta, o ganho de um só existe porque outros perderam."},{"letra":"C","texto":"O tempo: aposta é rápida, investimento é lento.","correta":false,"feedback":"Existe aplicação com resgate no mesmo dia e aposta que leva meses para ser liquidada. Prazo não define a diferença."}],"headline":"Qual critério separa investir de apostar, independentemente de quanto cada um pode render?"}'::jsonb, NULL),
  ('cmsgcn1hv001gmv7uuiu8dwkr', 'cmsgcn19b001cmv7u4bw641aj', 3, 'input', 'Sua meta mais próxima', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"📅","label":"Meses até o objetivo","placeholder":"18"}],"headline":"Em quantos meses você quer ter o dinheiro do seu objetivo mais próximo na mão?","subtitulo":"Uma estimativa basta; o número aproximado já muda a escolha."}'::jsonb, NULL),
  ('cmsgcn1hv001hmv7uay8g2r23', 'cmsgcn19b001cmv7u4bw641aj', 4, 'resultado', 'O prazo escolhe por você', '{"faixas":[{"cor":"green","condicao":"valor <= 12","mensagem":"Curto prazo: o critério principal é poder sacar sem perder valor. Rendimento alto com resgate incerto não serve aqui."},{"cor":"green","condicao":"valor <= 60","mensagem":"Médio prazo: dá para aceitar alguma oscilação, desde que a data-alvo tenha folga de alguns meses."},{"cor":"green","condicao":"resto","mensagem":"Longo prazo: aqui o inimigo é a inflação, não a oscilação de um mês. Reveja a meta uma vez por ano."}],"formula":"valor_direto","headline":"<strong>{valorCru}</strong> meses: é o prazo que escolhe onde o dinheiro fica","insightDinamico":"Você marcou {valorCru} meses. Esse número é o primeiro filtro: ele elimina metade das opções antes de você olhar qualquer rendimento. Quanto mais perto o objetivo, menos você pode aceitar oscilação; quanto mais longe, mais o tempo trabalha a seu favor. E nada disso vale se o dinheiro estiver numa aposta, onde não existe prazo, só sorte.\n\nPróximo passo: Escreva no celular o objetivo, o valor e a data. Sem os três, não é meta."}'::jsonb, NULL),
  ('cmsgcn21k001jmv7udva1a1gh', 'cmsgcn1uv001imv7u1ze11q53', 0, 'conceito', 'O triângulo da escolha', '{"corpo":"Toda aplicação responde a três perguntas. Risco: qual a chance de eu receber menos do que esperava? Retorno: quanto ela promete render? Liquidez: em quanto tempo eu transformo isso em dinheiro na conta sem perder valor? As três se puxam. Retorno alto costuma vir com risco alto ou com liquidez baixa. Quem oferece as três no máximo está escondendo alguma coisa.","headline":"Risco, retorno e liquidez: você escolhe duas e negocia a terceira."}'::jsonb, NULL),
  ('cmsgcn21k001kmv7uk0m7ilo6', 'cmsgcn1uv001imv7u1ze11q53', 1, 'cenario', 'Tudo no mesmo lugar', '{"linhas":[{"tipo":"saida","label":"Aplicado num ativo só","valor":12000},{"tipo":"saldo","label":"Prazo de resgate","valor":0,"valorTexto":"dois anos"},{"tipo":"saida","label":"Precisou no terceiro mês","valor":2000},{"tipo":"saldo","label":"Conseguiu tirar","valor":0,"valorTexto":"nada"}],"rodape":"Cauã tem 31 anos e trabalha como técnico de refrigeração. Juntou R$ 12.000 e colocou tudo em um único ativo indicado num grupo de mensagens, com resgate só depois de dois anos. No terceiro mês, a geladeira de casa queimou e o aluguel subiu. Ele precisava de R$ 2.000 e não conseguiu tirar. No papel, o rendimento era ótimo. O dinheiro existia, mas não estava disponível.","headline":"O problema foi o rendimento, o prazo de resgate ou ter tudo num lugar só?","personagem":"Cauã"}'::jsonb, NULL),
  ('cmsgcn21k001lmv7u9utdogd2', 'cmsgcn1uv001imv7u1ze11q53', 2, 'quiz', 'Diversificar por quê', '{"opcoes":[{"letra":"A","texto":"Garantir que nenhuma parte do dinheiro perca valor.","correta":false,"feedback":"Nenhuma estratégia elimina perdas. Diversificar reduz o impacto de uma perda, não a possibilidade dela."},{"letra":"B","texto":"Multiplicar o retorno, já que mais aplicações rendem mais.","correta":false,"feedback":"Aplicações não somam rendimento por serem várias. Parte do dinheiro em opções mais conservadoras tende a render menos, e essa é a troca aceita."},{"letra":"C","texto":"Fazer com que um resultado ruim em uma parte não derrube o conjunto.","correta":true,"feedback":"Riscos diferentes raramente acontecem ao mesmo tempo. É isso que estabiliza o resultado total e permite manter o plano de pé."}],"headline":"Diversificar é dividir o dinheiro entre aplicações diferentes. Qual é o objetivo principal dessa estratégia?"}'::jsonb, NULL),
  ('cmsgcn21k001mmv7ublz4adb4', 'cmsgcn1uv001imv7u1ze11q53', 3, 'input', 'Sua régua de liquidez', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"🚪","label":"Precisa sacar em até 30 dias","placeholder":"40"}],"headline":"Que percentual do seu dinheiro guardado você precisa poder sacar em até 30 dias?","subtitulo":"Chute pelo seu histórico de imprevistos; precisão não é exigida."}'::jsonb, NULL),
  ('cmsgcn21k001nmv7u45mkd26g', 'cmsgcn1uv001imv7u1ze11q53', 4, 'resultado', 'Onde cada parte fica', '{"faixas":[{"cor":"yellow","condicao":"valor < 20","mensagem":"Liquidez baixa demais para a maioria das rotinas. Um imprevisto médio te obriga a resgatar no pior momento."},{"cor":"green","condicao":"valor <= 60","mensagem":"Faixa comum. Vale checar se essa parte acessível cobre pelo menos um mês de despesas fixas."},{"cor":"yellow","condicao":"resto","mensagem":"Quase tudo à mão. Seguro no curto prazo, mas com esse desenho a inflação corrói o que você guarda para depois."}],"formula":"valor_direto","headline":"<strong>{valorCru}%</strong> à mão em 30 dias","insightDinamico":"Você estimou {valorCru}%. Essa fatia não é a parte que rende mais: é a parte que precisa estar acessível quando algo quebra. O resto pode aceitar prazo maior e oscilação, porque não será chamado de uma hora para outra. Dividir por essa régua, e não por palpite de conhecido, é o que sustenta o plano quando um pedaço vai mal.\n\nPróximo passo: Liste onde está seu dinheiro hoje e o prazo de resgate de cada parte."}'::jsonb, NULL),
  ('cmsgcn2la001pmv7uy8fr7sdi', 'cmsgcn2eo001omv7utfn2xjrw', 0, 'conceito', 'Bruto, líquido e real', '{"corpo":"Um rendimento anunciado é sempre bruto. Dele saem taxas de administração ou custódia e, na maioria das aplicações de renda fixa, imposto de renda que cai conforme o prazo aumenta. O que sobra é o retorno líquido. Depois ainda vem a inflação: se os preços subiram mais que o seu líquido, você tem mais reais e compra menos. Esse resto é o retorno real.","headline":"Se o preço subiu mais que o seu rendimento, você perdeu ganhando."}'::jsonb, NULL),
  ('cmsgcn2la001qmv7uboeabc3p', 'cmsgcn2eo001omv7utfn2xjrw', 1, 'cenario', 'A conta de um ano', '{"linhas":[{"tipo":"entrada","label":"Aplicado por um ano","valor":8000},{"tipo":"saldo","label":"Rendimento anunciado","valor":0,"valorTexto":"11% ao ano"},{"tipo":"saldo","label":"Imposto de renda","valor":0,"valorTexto":"sobre o ganho, no resgate"},{"tipo":"saldo","label":"Inflação do período","valor":0,"valorTexto":"5%"}],"rodape":"Iolanda tem 47 anos e vende marmitas. Guardou R$ 8.000 de um pedido grande e aplicou por um ano, com rendimento anunciado de 11% ao ano. No resgate, veio o imposto de renda sobre o ganho. No mesmo período, os preços que ela paga subiram 5%. Ela anotou os três números numa planilha simples e marcou uma revisão a cada seis meses.","headline":"Dos 11% anunciados, quanto de fato aumentou o poder de compra dela?","personagem":"Iolanda"}'::jsonb, NULL),
  ('cmsgcn2la001rmv7ucorqtut7', 'cmsgcn2eo001omv7utfn2xjrw', 2, 'quiz', 'Faça a conta', '{"opcoes":[{"letra":"A","texto":"12%, ou R$ 1.200","correta":false,"feedback":"Esse é o bruto, antes do imposto e antes da alta de preços. É o número do anúncio, não o do bolso."},{"letra":"B","texto":"9,6%, ou R$ 960","correta":false,"feedback":"Esse é o líquido depois do imposto: R$ 1.200 de ganho menos R$ 240 de imposto. Ainda falta descontar os 6% de inflação."},{"letra":"C","texto":"Cerca de 3,4%, pouco mais de R$ 340","correta":true,"feedback":"R$ 1.200 menos R$ 240 de imposto dão R$ 960, ou 9,6% líquidos. Descontando 6% de inflação, sobram cerca de 3,4% de ganho real."}],"headline":"R$ 10.000 aplicados por um ano renderam 12% brutos. O imposto sobre o ganho foi de 20% e a inflação, 6%. Qual o ganho real aproximado?"}'::jsonb, NULL),
  ('cmsgcn2la001smv7ur4cpilf3', 'cmsgcn2eo001omv7utfn2xjrw', 3, 'input', 'Seu aporte mensal', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"📥","label":"Aporte mensal possível","placeholder":"R$ 250"}],"headline":"Quanto você consegue separar por mês para o seu plano, sem contar com sorte nem com renda extra?","subtitulo":"Uma estimativa média dos últimos três meses já serve."}'::jsonb, NULL),
  ('cmsgcn2la001tmv7ucwqaylcz', 'cmsgcn2eo001omv7utfn2xjrw', 4, 'resultado', 'Do plano ao papel', '{"faixas":[{"cor":"green","condicao":"valor < 100","mensagem":"Valor pequeno, mas no primeiro ano a data fixa e o hábito pesam mais que o tamanho do aporte."},{"cor":"green","condicao":"valor < 500","mensagem":"Nessa faixa a diferença entre bruto e líquido já aparece em reais. Vale comparar tributação e taxas antes de decidir."},{"cor":"yellow","condicao":"resto","mensagem":"Com esse aporte, taxa de administração e imposto pesam de verdade. Um ponto percentual a menos de custo muda o resultado do ano."}],"formula":"valor_direto","headline":"<strong>R$ {valor}</strong> por mês, e o que sobra depois de tudo","insightDinamico":"Com {valor} por mês, o plano só fica de pé se você acompanhar três números: quanto entrou, quanto rendeu líquido e quanto os preços subiram no período. Renda fixa e renda variável entram nesse plano em proporções que você decide pelo prazo de cada meta, não pelo rendimento anunciado. Marque uma revisão a cada seis meses e ajuste o aporte.\n\nPróximo passo: Abra uma planilha com três colunas: aporte, rendimento líquido e inflação do mês."}'::jsonb, NULL),
  ('cmsgcn3ij001vmv7ule2hgvmh', 'cmsgcn33s001umv7uy3f327sb', 0, 'conceito', 'Quem começa antes', '{"corpo":"Aposentadoria não é assunto de quem tem 50 anos. É um problema de tempo: cada ano guardado cedo rende sobre o próprio rendimento, e esse efeito não se recupera depois. Quem começa aos 20 precisa separar uma fatia bem menor da renda do que quem começa aos 40 para chegar ao mesmo lugar. O que falta não é dinheiro, é calendário.","headline":"Começar dez anos antes vale mais que dobrar o valor guardado depois."}'::jsonb, NULL),
  ('cmsgcn3ij001wmv7uzvfnkrij', 'cmsgcn33s001umv7uy3f327sb', 1, 'cenario', 'Teto, tempo e conta', '{"linhas":[{"tipo":"saldo","label":"Vínculo","valor":0,"valorTexto":"sem carteira, dirige por aplicativo"},{"tipo":"saldo","label":"INSS","valor":0,"valorTexto":"ele mesmo recolhe, todo mês"},{"tipo":"saldo","label":"Benefício público","valor":0,"valorTexto":"tem teto, menor que a renda dele"},{"tipo":"saldo","label":"Quem chega aos 65 no Brasil","valor":0,"valorTexto":"tende a viver mais de 20 anos"}],"rodape":"Wesley tem 38 anos e dirige por aplicativo. Como não tem carteira assinada, ele mesmo recolhe a contribuição ao INSS todo mês. Descobriu que o benefício público tem teto e que a renda dele hoje é maior que esse teto. Também leu que quem chega aos 65 no Brasil tende a viver mais de vinte anos depois disso. A conta dele precisa cobrir esse intervalo inteiro, não só a data de parar.","headline":"Se o benefício público tem teto, o que preenche a diferença até o padrão de vida dele?","personagem":"Wesley"}'::jsonb, NULL),
  ('cmsgcn3ij001xmv7uo3brzppd', 'cmsgcn33s001umv7uy3f327sb', 2, 'quiz', 'Público e privado', '{"opcoes":[{"letra":"A","texto":"A previdência privada substitui a pública, então quem tem uma não precisa da outra.","correta":false,"feedback":"São camadas diferentes. O regime público garante um piso vitalício e coberturas como incapacidade e pensão, que um plano privado não replica automaticamente."},{"letra":"B","texto":"A pública paga enquanto a pessoa viver e tem teto; a privada complementa e depende do que foi acumulado e das taxas cobradas.","correta":true,"feedback":"É a divisão de funções: piso vitalício de um lado, complemento acumulado do outro. Por isso prazo e taxas pesam tanto na parte privada."},{"letra":"C","texto":"Contribuir para o INSS só faz sentido para quem tem carteira assinada.","correta":false,"feedback":"Autônomos e informais podem contribuir por conta própria e manter direito a aposentadoria, auxílio por incapacidade e pensão."}],"headline":"Qual comparação entre a previdência pública e os planos privados se sustenta?"}'::jsonb, NULL),
  ('cmsgcn3ij001ymv7udnuneh3g', 'cmsgcn33s001umv7uy3f327sb', 3, 'input', 'Anos até reduzir o ritmo', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"🕰️","label":"Idade para reduzir o ritmo","placeholder":"62"}],"headline":"Com quantos anos você imagina reduzir o ritmo de trabalho e depender do que juntou?","subtitulo":"Uma idade aproximada basta; a ideia é enxergar o tamanho do intervalo."}'::jsonb, NULL),
  ('cmsgcn3ij001zmv7uhzizysf0', 'cmsgcn33s001umv7uy3f327sb', 4, 'resultado', 'O intervalo a bancar', '{"faixas":[{"cor":"yellow","condicao":"valor < 55","mensagem":"Parar cedo alonga o período a bancar: pode passar de trinta anos de despesas sem renda do trabalho."},{"cor":"yellow","condicao":"valor <= 64","mensagem":"Idade comum de saída, mas provavelmente antes do benefício público integral. O intervalo entre parar e receber precisa estar coberto."},{"cor":"green","condicao":"resto","mensagem":"Mais tempo contribuindo e menos tempo sacando alivia a conta. Ainda assim, planeje para viver bem além dessa idade."}],"formula":"valor_direto","headline":"Reduzir aos <strong>{valorCru}</strong>: o intervalo a bancar começa aí","insightDinamico":"Você marcou {valorCru} anos. A pergunta não é só quando parar, e sim por quanto tempo o dinheiro precisa durar depois disso. Como a expectativa de vida segue subindo, planejar por vinte ou trinta anos de despesas é mais realista que planejar por dez. Começar agora, mesmo com pouco, encurta o esforço mensal que você vai precisar fazer lá na frente.\n\nPróximo passo: Confira no Meu INSS quantas contribuições você já tem registradas."}'::jsonb, NULL),
  ('cmsgcn4qj0021mv7u002fqpjh', 'cmsgcn4am0020mv7uywkhbljh', 0, 'conceito', 'As três letras', '{"corpo":"ESG resume três critérios usados para avaliar uma empresa além do resultado financeiro. Ambiental: o que ela emite, consome e descarta. Social: como trata trabalhadores, clientes e a comunidade ao redor. Governança: quem decide, com qual transparência e qual controle sobre conflitos de interesse. Esses critérios não valem só para investir: aparecem também em qual banco você usa e no que você compra.","headline":"Governança fraca costuma aparecer no balanço antes de aparecer na notícia."}'::jsonb, NULL),
  ('cmsgcn4qj0022mv7ueytm94xs', 'cmsgcn4am0020mv7uywkhbljh', 1, 'cenario', 'Crédito, madeira e conduta', '{"linhas":[{"tipo":"entrada","label":"Empréstimo para a máquina","valor":15000},{"tipo":"saldo","label":"Instituição A","valor":0,"valorTexto":"0,4 ponto mais barata, cobrança abusiva"},{"tipo":"saldo","label":"Instituição B","valor":0,"valorTexto":"mais cara, contrato claro e ouvidoria"},{"tipo":"saldo","label":"Fornecedor da madeira","valor":0,"valorTexto":"só um comprova origem legal"}],"rodape":"Bianca tem 29 anos e toca uma marcenaria pequena. Precisa de R$ 15.000 emprestados para comprar uma máquina. Duas instituições oferecem crédito: uma com taxa 0,4 ponto menor e histórico de cobrança abusiva contra clientes; outra um pouco mais cara, com contrato claro e ouvidoria que responde. Na mesma semana, ela escolhe o fornecedor da madeira e vê que só um deles comprova origem legal.","headline":"O que a taxa menor não mostra sobre quem vai ficar com o seu contrato por três anos?","personagem":"Bianca"}'::jsonb, NULL),
  ('cmsgcn4qj0023mv7u1a7has9b', 'cmsgcn4am0020mv7uywkhbljh', 2, 'quiz', 'Critério ou marketing', '{"opcoes":[{"letra":"A","texto":"Uma campanha com embalagem verde e um selo criado pela própria empresa.","correta":false,"feedback":"Selo próprio e identidade visual não são verificáveis por ninguém de fora. Isso é comunicação, não critério."},{"letra":"B","texto":"Relatórios anuais com metas medidas e auditadas por terceiros, além do histórico de multas e processos acessível.","correta":true,"feedback":"Dado auditado é o que separa critério de propaganda. O histórico de sanções mostra o que a empresa faz quando ninguém está olhando."},{"letra":"C","texto":"O fato de o setor dela ser considerado limpo, como tecnologia ou serviços.","correta":false,"feedback":"Setor não define conduta. Empresas do mesmo ramo variam muito em consumo de energia, condições de trabalho e transparência."}],"headline":"Uma empresa se anuncia como sustentável. Qual evidência sustenta melhor essa afirmação?"}'::jsonb, NULL),
  ('cmsgcn4qj0024mv7u6m30lhmp', 'cmsgcn4am0020mv7uywkhbljh', 3, 'input', 'Sua prioridade', '{"campos":[{"id":"valor","tipo":"faixa","emoji":"🌱","label":"Critério que pesaria mais","opcoes":[{"label":"Ambiental: clima, água e resíduos","valor":"1"},{"label":"Social: trabalho e comunidade","valor":"2"},{"label":"Governança: transparência e contratos","valor":"3"}]}],"headline":"Entre os três critérios, qual pesaria mais na sua próxima decisão de compra, crédito ou aplicação?","subtitulo":"Não existe resposta certa; escolher é o que torna o critério utilizável."}'::jsonb, NULL),
  ('cmsgcn4qk0025mv7ucc1mnyr0', 'cmsgcn4am0020mv7uywkhbljh', 4, 'resultado', 'Do valor ao critério', '{"faixas":[{"cor":"green","condicao":"valor == 1","mensagem":"Peça o número: emissões, consumo de água, destino dos resíduos. Promessa sem dado medido não dá para acompanhar."},{"cor":"green","condicao":"valor == 2","mensagem":"Procure autuações trabalhistas, reclamações de clientes registradas e como a empresa fiscaliza os próprios fornecedores."},{"cor":"green","condicao":"resto","mensagem":"Veja quem responde pela empresa, se o contrato fica disponível antes da assinatura e se a ouvidoria dá resposta com prazo."}],"formula":"valor_direto","headline":"Critério só vale quando vira pergunta que dá para conferir","insightDinamico":"Você marcou {valorCru}. Critério só vale se for verificável: antes da próxima compra, do próximo crédito ou da próxima aplicação, procure um dado público que confirme ou desminta a promessa. Relatório auditado, decisão de órgão regulador, processo judicial, reclamação registrada. Quando o dado simplesmente não existe, isso também é informação sobre a empresa.\n\nPróximo passo: Escolha uma empresa que você já usa e procure o histórico dela em órgãos reguladores."}'::jsonb, NULL),
  ('cmsgcn61p0027mv7u3mpxrgeo', 'cmsgcn5lq0026mv7ubqvianr5', 0, 'conceito', 'Promessa alta, pressa maior', '{"corpo":"Retorno alto com garantia e prazo apertado é a combinação que aparece tanto em golpe quanto em produto de alto risco mal explicado. Golpe é crime: promete o que não existe. Risco alto é legítimo, mas pode desvalorizar muito, como acontece com alguns criptoativos. Nos dois casos, a pressa serve para você decidir sem verificar quem está do outro lado.","headline":"Quanto maior a promessa e menor o prazo para decidir, mais tempo você deveria tomar."}'::jsonb, NULL),
  ('cmsgcn61p0028mv7u65kuxdqv', 'cmsgcn5lq0026mv7ubqvianr5', 1, 'cenario', 'O grupo que pagou primeiro', '{"linhas":[{"tipo":"saida","label":"Primeiro Pix, para conta de pessoa física","valor":300},{"tipo":"entrada","label":"Devolvido na primeira semana","valor":24},{"tipo":"saida","label":"Oferta seguinte, só hoje","valor":3000},{"tipo":"saldo","label":"Promessa","valor":0,"valorTexto":"8% ao mês, sem CNPJ no site"}],"rodape":"Otávio, 24 anos, entrou num grupo que promete 8% ao mês em uma carteira automatizada. Ele fez um Pix de R$ 300 para uma conta de pessoa física e recebeu R$ 24 de volta na primeira semana, a prova de que funcionava. Aí veio a oferta: R$ 3.000 hoje, só hoje, com rendimento dobrado. O site não traz CNPJ e o suporte só responde por mensagem.","headline":"O primeiro pagamento provou alguma coisa, ou foi parte do golpe?","personagem":"Otávio"}'::jsonb, NULL),
  ('cmsgcn61p0029mv7ubc02m54s', 'cmsgcn5lq0026mv7ubqvianr5', 2, 'quiz', 'Antes de transferir', '{"opcoes":[{"letra":"A","texto":"Fazer um Pix menor primeiro, para testar se o dinheiro volta.","correta":false,"feedback":"Foi exatamente isso que já aconteceu: o retorno pequeno é a isca. Devolver R$ 24 é barato para quem quer R$ 3.000."},{"letra":"B","texto":"Conferir o CNPJ e a autorização da empresa nos sites do Banco Central e da CVM antes de qualquer transferência.","correta":true,"feedback":"A consulta ao regulador é gratuita e leva minutos. Quem capta dinheiro do público sem autorização está irregular, prometa o que prometer."},{"letra":"C","texto":"Pagar com cartão de crédito em vez de Pix, porque o cartão sempre estorna.","correta":false,"feedback":"Contestação de cartão existe, mas não é garantia e não cobre aporte em investimento. Trocar o meio de pagamento não torna a oferta legítima."}],"headline":"Otávio resolve checar antes de mandar os R$ 3.000. Qual medida realmente reduz o risco dessa transação?"}'::jsonb, NULL),
  ('cmsgcn61p002amv7uixjuungo', 'cmsgcn5lq0026mv7ubqvianr5', 3, 'input', 'Seu limiar de desconfiança', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"🚨","label":"Retorno que te faria desconfiar","placeholder":"3%"}],"headline":"Qual retorno mensal garantido alguém precisaria prometer para você desconfiar na hora?","subtitulo":"Uma estimativa basta: o número serve para você medir o próprio alarme, não para acertar na régua."}'::jsonb, NULL),
  ('cmsgcn61q002bmv7usx4eyj0k', 'cmsgcn5lq0026mv7ubqvianr5', 4, 'resultado', 'Onde seu alarme toca', '{"faixas":[{"cor":"green","condicao":"valor <= 1","mensagem":"Seu limiar está bem calibrado. Acima disso, com promessa de garantia, já cabe checar CNPJ e registro no regulador antes de qualquer transferência."},{"cor":"yellow","condicao":"valor <= 5","mensagem":"Faixa razoável, mas lembre que 3% ao mês garantidos viram mais de 40% ao ano. Pergunte de onde sairia esse dinheiro e quem responde por ele."},{"cor":"red","condicao":"resto","mensagem":"Seu alarme toca tarde: 5% ao mês compõem cerca de 80% ao ano. Promessa desse tamanho, com garantia, não existe no mercado regulado."}],"formula":"valor_direto","headline":"Seu alarme toca em <strong>{valorCru}%</strong> ao mês","insightDinamico":"Você disse que desconfiaria a partir de {valorCru} ao mês. Guarde esse número: aplicações conservadoras no Brasil rendem perto de 1% ao mês, e ninguém pode garantir retorno muito acima disso. O mesmo critério vale para compra online, senha de internet banking e Pix para desconhecido: quando pedem pressa, é aí que você para.\n\nPróximo passo: Procure o CNPJ de quem te ofereceu investimento nos sites do Banco Central e da CVM."}'::jsonb, NULL),
  ('cmsgcn7qa002dmv7u45oes4fi', 'cmsgcn75i002cmv7uo12f082k', 0, 'conceito', 'Colchão e contrato', '{"corpo":"São duas proteções diferentes. A reserva de emergência é dinheiro seu, guardado onde dá para sacar rápido, para o imprevisto que você consegue pagar. O seguro é um contrato: você paga um valor por período, o prêmio, e a seguradora assume uma perda grande demais para o seu bolso. As regras do que está coberto ficam escritas na apólice.","headline":"Reserva cobre o susto pequeno. Seguro cobre o estrago que quebraria você."}'::jsonb, NULL),
  ('cmsgcn7qa002emv7uj80d8g9t', 'cmsgcn75i002cmv7uo12f082k', 1, 'cenario', 'A queda de Neide', '{"linhas":[{"tipo":"saida","label":"Prêmio do seguro, no ano","valor":1380},{"tipo":"saida","label":"Conserto depois da queda","valor":5200},{"tipo":"saida","label":"Franquia — fica com ela","valor":2000},{"tipo":"entrada","label":"Indenização — a seguradora paga","valor":3200}],"rodape":"Neide, 38 anos, usa a moto para entregas. Paga R$ 1.380 por ano de prêmio no seguro. Numa queda em dia de chuva, o sinistro, que é o evento previsto na apólice, o conserto saiu R$ 5.200. A franquia da apólice é de R$ 2.000: essa parte fica com ela. A seguradora pagou os R$ 3.200 restantes, a indenização. Sem reserva, Neide não teria os R$ 2.000.","headline":"O seguro resolveu tudo, ou sobrou uma parte para a reserva cobrir?","personagem":"Neide"}'::jsonb, NULL),
  ('cmsgcn7qa002fmv7u2fvzsien', 'cmsgcn75i002cmv7uo12f082k', 2, 'quiz', 'Quem paga o quê', '{"opcoes":[{"letra":"A","texto":"A seguradora paga os R$ 1.500, já que o sinistro está coberto.","correta":false,"feedback":"Prejuízo abaixo da franquia fica com o segurado. A cobertura vale para o que passa desse valor, não para qualquer conserto."},{"letra":"B","texto":"Neide paga os R$ 1.500 do próprio bolso: abaixo da franquia não há indenização.","correta":true,"feedback":"A franquia é a parte do prejuízo que fica com você em cada sinistro. É justamente aí que a reserva de emergência entra."},{"letra":"C","texto":"Neide pode omitir que usa a moto para trabalhar e assim receber mais.","correta":false,"feedback":"Informar dado falso descumpre um dever do segurado e pode anular a cobertura. Avisar o sinistro no prazo e dizer a verdade são obrigações do contrato."}],"headline":"Um mês depois, Neide sofre outra queda e o conserto sai R$ 1.500. Com franquia de R$ 2.000, o que a apólice determina?"}'::jsonb, NULL),
  ('cmsgcn7qa002gmv7u81xalcsv', 'cmsgcn75i002cmv7uo12f082k', 3, 'input', 'Seu mês essencial', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"🛟","label":"Seu mês essencial","placeholder":"R$ 1.800"}],"headline":"Quanto você gasta por mês com o essencial: moradia, comida, transporte e contas básicas?","subtitulo":"Uma estimativa aproximada resolve; não precisa abrir extrato para responder."}'::jsonb, NULL),
  ('cmsgcn7qa002hmv7uwdqsjqnr', 'cmsgcn75i002cmv7uo12f082k', 4, 'resultado', 'O tamanho do colchão', '{"faixas":[{"cor":"green","condicao":"valor < 1000","mensagem":"Sua meta fica abaixo de R$ 3.000, alcançável guardando um pouco por mês. Comece pelo valor da franquia dos seguros que você tem ou pretende ter."},{"cor":"yellow","condicao":"valor <= 3000","mensagem":"A meta fica entre R$ 3.000 e R$ 9.000. Divida por doze e trate a parcela como uma conta fixa até fechar o valor."},{"cor":"yellow","condicao":"resto","mensagem":"A meta passa de R$ 9.000 e leva tempo para juntar. Enquanto isso, o seguro é o que protege o que seria impossível repor do próprio bolso."}],"formula":"valor_direto","headline":"Um mês essencial: <strong>R$ {valor}</strong>","insightDinamico":"Com {valor} por mês de gasto essencial, uma reserva de três meses fica em torno do triplo desse valor. É ela que cobre franquia, conta inesperada e mês sem renda. O seguro entra depois, para o estrago que a reserva não aguentaria. Guardar em algo de resgate rápido importa mais aqui do que buscar rendimento.\n\nPróximo passo: Some seus gastos essenciais de um mês e veja quanto falta para o primeiro mês de reserva."}'::jsonb, NULL),
  ('cmsgcn8yc002jmv7u6r5vr0od', 'cmsgcn8d0002imv7u2kbycs58', 0, 'conceito', 'Taxa não é o preço final', '{"corpo":"A taxa que aparece no anúncio é só uma parte do que você paga. O Custo Efetivo Total, o CET, junta tudo: juros, tarifa de cadastro, seguro embutido, impostos e o prazo. Por lei, a instituição precisa informar o CET antes de você assinar. Duas ofertas com a mesma taxa mensal podem ter CET bem diferente. Comparar pela taxa anunciada é comparar pela metade.","headline":"A taxa é a manchete. O CET é a conta."}'::jsonb, NULL),
  ('cmsgcn8yc002kmv7uobwafapk', 'cmsgcn8d0002imv7u2kbycs58', 1, 'cenario', 'Duas ofertas, mesma taxa', '{"linhas":[{"tipo":"entrada","label":"Precisa emprestado","valor":4000},{"tipo":"saida","label":"Oferta A — parcela (CET 2,9% a.m.)","valor":385},{"tipo":"saida","label":"Oferta B — parcela (CET 4,4% a.m.)","valor":427},{"tipo":"saldo","label":"Mesma taxa anunciada nas duas","valor":0,"valorTexto":"2,3% ao mês"},{"tipo":"saldo","label":"Diferença no total pago","valor":501}],"rodape":"Adriano, 29 anos, precisa de R$ 4.000 para trocar o notebook que usa no freela. Duas instituições oferecem 12 parcelas à mesma taxa nominal: 2,3% ao mês. Na oferta A, o CET é 2,9% ao mês e a parcela sai R$ 385. Na oferta B, o CET é 4,4% ao mês, porque entram tarifa de cadastro de R$ 250 e seguro de R$ 180 na conta; a parcela vira R$ 427. No fim, R$ 4.623 contra R$ 5.124.","headline":"Duas ofertas com a mesma taxa: o que está fazendo R$ 501 de diferença?","personagem":"Adriano"}'::jsonb, NULL),
  ('cmsgcn8yc002lmv7uayb3dh8h', 'cmsgcn8d0002imv7u2kbycs58', 2, 'quiz', 'O que o histórico muda', '{"opcoes":[{"letra":"A","texto":"Garante a aprovação de qualquer empréstimo que você pedir","correta":false,"feedback":"Nenhum histórico garante aprovação. A instituição continua avaliando renda, prazo e quanto você já deve."},{"letra":"B","texto":"Melhora sua avaliação de risco e pode reduzir a taxa oferecida a você","correta":true,"feedback":"É o efeito prático: pagamentos em dia registrados baixam o risco percebido, e risco menor costuma virar taxa e CET menores."},{"letra":"C","texto":"Apaga do seu nome as dívidas antigas já vencidas","correta":false,"feedback":"O cadastro positivo mostra o que foi pago, não elimina dívida. A negativação só sai quando a dívida é quitada ou renegociada."}],"headline":"O cadastro positivo registra seu histórico de contas e parcelas pagas em dia. O que ele tende a mudar na hora de contratar crédito?"}'::jsonb, NULL),
  ('cmsgcn8yc002mmv7u5ecg444x', 'cmsgcn8d0002imv7u2kbycs58', 3, 'input', 'O que cabe no seu mês', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"📆","label":"Parcela que cabe no seu mês","placeholder":"R$ 300"}],"headline":"Qual é o maior valor de parcela que caberia no seu mês sem cortar o essencial?","subtitulo":"Uma estimativa basta; não é preciso abrir extrato nem acertar no centavo."}'::jsonb, NULL),
  ('cmsgcn8yc002nmv7uo08tfer9', 'cmsgcn8d0002imv7u2kbycs58', 4, 'resultado', 'Sua faixa de decisão', '{"faixas":[{"cor":"yellow","condicao":"valor < 385","mensagem":"Nenhuma das duas ofertas do exemplo caberia no seu mês. Adiar a compra ou pedir menos custa bem menos do que atrasar parcela."},{"cor":"yellow","condicao":"valor < 427","mensagem":"Só a oferta de CET menor caberia. A diferença entre as duas não estava na taxa anunciada, estava nas tarifas e no seguro."},{"cor":"green","condicao":"resto","mensagem":"As duas caberiam, e é aí que o CET decide: a mais cara levaria R$ 501 a mais pelo mesmo dinheiro emprestado."}],"formula":"valor_direto","headline":"Cabe até <strong>R$ {valor}</strong> por mês","insightDinamico":"Você disse que cabe até R$ {valor} de parcela por mês. É esse número, e não o entusiasmo com a compra, que define quais ofertas entram na sua lista. Com ele na mão, peça o CET por escrito das duas propostas e compare o total pago, não a parcela isolada. Prazo maior quase sempre significa parcela menor e total maior.\n\nPróximo passo: Consulte seu cadastro positivo e peça o CET por escrito antes de assinar qualquer proposta."}'::jsonb, NULL),
  ('cmsgcn9vo002pmv7u0zd8unxz', 'cmsgcn9kp002omv7uqmk70p8b', 0, 'conceito', 'Como a dívida cresce', '{"corpo":"Dívida atrasada cresce em camadas: multa, que incide uma vez, juros de mora por mês de atraso e, no crédito rotativo, juros que incidem sobre o saldo já acrescido de juros. É por isso que o valor acelera. Endividamento excessivo raramente tem causa única: desemprego, doença, renda que varia de mês para mês e emergência sem reserva aparecem mais do que descontrole.","headline":"Juros compostos não perguntam por que você atrasou."}'::jsonb, NULL),
  ('cmsgcn9vo002qmv7ujtnyb0o8', 'cmsgcn9kp002omv7uqmk70p8b', 1, 'cenario', 'Quatro meses no rotativo', '{"linhas":[{"tipo":"saida","label":"Sobrou da fatura, no rotativo","valor":1200},{"tipo":"saldo","label":"Taxa","valor":0,"valorTexto":"14% ao mês, juros sobre juros"},{"tipo":"saldo","label":"Quatro meses depois","valor":2027},{"tipo":"entrada","label":"Entrada proposta no acordo","valor":300}],"rodape":"Marlene, 41 anos, ficou quatro meses sem trabalho depois que a empresa fechou. Pagou o mínimo da fatura e o resto foi para o rotativo do cartão, a 14% ao mês. Os R$ 1.200 que sobraram viraram cerca de R$ 2.027 em quatro meses, porque os juros passaram a incidir sobre juros. Ela voltou a trabalhar e propôs um acordo: R$ 300 de entrada e 10 parcelas, com taxa negociada para baixo.","headline":"A dívida quase dobrou em quatro meses. O que fez o valor crescer assim?","personagem":"Marlene"}'::jsonb, NULL),
  ('cmsgcn9vo002rmv7u3gt7hl25', 'cmsgcn9kp002omv7uqmk70p8b', 2, 'quiz', 'Multa mais mora', '{"opcoes":[{"letra":"A","texto":"R$ 816","correta":false,"feedback":"Isso é só a multa de 2%, ou seja, R$ 16. Faltam os juros de mora dos três meses de atraso."},{"letra":"B","texto":"R$ 824","correta":false,"feedback":"Aqui entrou a multa e apenas um mês de mora. O atraso é de três meses, então a mora é R$ 8 três vezes."},{"letra":"C","texto":"R$ 840","correta":true,"feedback":"R$ 800 mais R$ 16 de multa mais R$ 8 de mora por mês, em três meses, dá R$ 840. Multa incide uma vez; mora, a cada mês."}],"headline":"Uma conta de R$ 800 venceu há 3 meses. O contrato prevê multa de 2% e juros de mora de 1% ao mês. Quanto virou a dívida?"}'::jsonb, NULL),
  ('cmsgcn9vo002smv7u44max06d', 'cmsgcn9kp002omv7uqmk70p8b', 3, 'input', 'Quanto já está comprometido', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"⛓️","label":"Da renda já comprometida","placeholder":"25"}],"headline":"Quanto do que entra por mês já está comprometido com parcelas, faturas e dívidas?","subtitulo":"Estimativa serve; não é preciso somar tudo no centavo para ter a leitura."}'::jsonb, NULL),
  ('cmsgcn9vo002tmv7ut8eq3xbp', 'cmsgcn9kp002omv7uqmk70p8b', 4, 'resultado', 'Onde você está', '{"faixas":[{"cor":"green","condicao":"valor < 30","mensagem":"Abaixo de 30% ainda há folga para absorver um imprevisto. É o momento de montar reserva, não de assumir mais uma parcela."},{"cor":"yellow","condicao":"valor <= 50","mensagem":"Nessa faixa, qualquer queda de renda vira atraso. Vale procurar o credor antes do primeiro vencimento perdido, quando ainda não há multa."},{"cor":"red","condicao":"resto","mensagem":"Mais da metade da renda comprometida é endividamento excessivo, seja qual for a causa. Ataque primeiro a dívida de juros mais altos e proponha acordo."}],"formula":"valor_direto","headline":"<strong>{valorCru}%</strong> da sua renda já tem dono","insightDinamico":"Você estimou que {valorCru}% do que entra por mês já está comprometido com dívidas. Esse percentual é o que decide se sobra espaço para um imprevisto ou se o próximo mês termina no rotativo. Renegociar não é favor nem confissão de erro: credor costuma preferir receber menos e certo a não receber.\n\nPróximo passo: Liste suas dívidas por taxa de juros e ligue hoje para o credor da mais cara."}'::jsonb, NULL),
  ('cmsgcnalm002vmv7upo79s0je', 'cmsgcnaf1002umv7u8tqfm9ex', 0, 'conceito', 'Entrar e permanecer', '{"corpo":"Entrar e permanecer são duas contas diferentes. Enem e Sisu, Prouni, Fies, cotas e bolsas da própria instituição mudam quanto você paga de mensalidade, e o Fies vira parcela depois de formado. Nenhum deles cobre sozinho o custo de permanência: transporte, material, moradia, alimentação e as horas que você deixa de trabalhar. Muitas instituições têm auxílio de permanência, mas é preciso procurar.","headline":"A vaga é o começo da conta, não o fim dela."}'::jsonb, NULL),
  ('cmsgcnalm002wmv7uvxm732lc', 'cmsgcnaf1002umv7u8tqfm9ex', 1, 'cenario', 'Duas aprovações', '{"linhas":[{"tipo":"saldo","label":"Vaga pública, outra cidade","valor":0,"valorTexto":"mensalidade zero"},{"tipo":"saida","label":"…mas moradia, transporte e material","valor":1200},{"tipo":"saida","label":"Bolsa de 50%, na própria cidade","valor":700},{"tipo":"saida","label":"…mais transporte, morando em casa","valor":160}],"rodape":"Kauã, 17 anos, fez o Enem e tem nota para duas coisas: uma vaga pública pelo Sisu em outra cidade e uma bolsa de 50% pelo Prouni numa faculdade da sua cidade. Na primeira, a mensalidade é zero, mas moradia, transporte e material somam R$ 1.200 por mês. Na segunda, a mensalidade com bolsa fica em R$ 700 e o transporte, R$ 160, porque ele continua morando em casa.","headline":"A vaga sem mensalidade é mesmo a opção mais barata para ele?","personagem":"Kauã"}'::jsonb, NULL),
  ('cmsgcnalm002xmv7u4d0uyakr', 'cmsgcnaf1002umv7u8tqfm9ex', 2, 'quiz', 'Quatro anos de conta', '{"opcoes":[{"letra":"A","texto":"A vaga pública, porque a mensalidade é zero","correta":false,"feedback":"Mensalidade zero não zera moradia nem transporte. Em 48 meses, esse caminho soma R$ 57.600 de custo de permanência."},{"letra":"B","texto":"A opção com bolsa de 50%, por cerca de R$ 16 mil a menos","correta":true,"feedback":"São R$ 41.280 contra R$ 57.600 em 48 meses, uma diferença de R$ 16.320. O gasto de permanência decidiu, não a mensalidade."},{"letra":"C","texto":"As duas custam o mesmo; muda só quem paga a conta","correta":false,"feedback":"As duas contas são diferentes: R$ 340 por mês de diferença viram mais de R$ 16 mil ao longo do curso."}],"headline":"Manter-se na vaga pública em outra cidade custa R$ 1.200 por mês; com bolsa de 50% na própria cidade, R$ 860. Em 4 anos, o que pesa menos?"}'::jsonb, NULL),
  ('cmsgcnalm002ymv7upu1i9q3h', 'cmsgcnaf1002umv7u8tqfm9ex', 3, 'input', 'Seu custo de permanência', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"🎓","label":"Custo mensal de permanência","placeholder":"R$ 600"}],"headline":"Quanto você gastaria por mês para se manter estudando: transporte, material, alimentação e moradia?","subtitulo":"Uma estimativa aproximada já serve para comparar caminhos; precisão não é exigida aqui."}'::jsonb, NULL),
  ('cmsgcnalm002zmv7udbkmyi8n', 'cmsgcnaf1002umv7u8tqfm9ex', 4, 'resultado', 'A conta até a formatura', '{"faixas":[{"cor":"green","condicao":"valor < 400","mensagem":"Menos de R$ 400 por mês costuma pressupor morar em casa e trajeto curto. Confirme material e alimentação antes de fechar essa conta."},{"cor":"yellow","condicao":"valor <= 1000","mensagem":"Nessa faixa, passe estudantil e auxílio de permanência da instituição mudam bastante o resultado. Vale perguntar antes de escolher a vaga."},{"cor":"yellow","condicao":"resto","mensagem":"Acima de R$ 1.000 por mês, mudar de cidade pesa mais que qualquer mensalidade. Compare com os caminhos disponíveis onde você já mora."}],"formula":"valor_direto","headline":"Manter-se estudando: <strong>R$ {valor}</strong> por mês","insightDinamico":"R$ {valor} por mês é o seu custo de permanência estimado. Multiplicado pelos cerca de 48 meses de uma graduação, é ele que diz se um caminho se sustenta, não o valor da mensalidade. Compare Sisu, Prouni, Fies, cotas e bolsas da instituição por esse total, e pergunte a cada uma quais auxílios de moradia, transporte e alimentação existem.\n\nPróximo passo: Some o custo mensal de permanência de dois caminhos que te interessam e compare os totais."}'::jsonb, NULL),
  ('cmsgcnb5f0031mv7uqzzw5euh', 'cmsgcnayt0030mv7uud1tmv00', 0, 'conceito', 'As quatro forças da sua renda', '{"corpo":"Sua renda não é só resultado de esforço. Quatro forças a determinam ao mesmo tempo. As estruturais mudam devagar: escolaridade, região onde você mora, cor, gênero, a rede de contatos que herdou. As conjunturais são o momento: inflação, desemprego, o setor aquecido ou parado. As pessoais são suas escolhas e sua formação. E as do trabalho são o vínculo: carteira assinada, contrato, informalidade, quantas horas você entrega.","headline":"Esforço explica parte da renda. Estrutura, conjuntura e vínculo explicam o resto."}'::jsonb, NULL),
  ('cmsgcnb5f0032mv7u8g7wt7yf', 'cmsgcnayt0030mv7uud1tmv00', 1, 'cenario', 'Cleiton e a corrida que cai', '{"linhas":[{"tipo":"entrada","label":"Mês bom, 200 horas rodadas","valor":2800},{"tipo":"saida","label":"INSS, que ele mesmo recolhe","valor":200},{"tipo":"saldo","label":"Férias, 13º, afastamento","valor":0,"valorTexto":"nenhum"},{"tipo":"saldo","label":"Quando o combustível sobe","valor":0,"valorTexto":"o valor por corrida cai"}],"rodape":"Cleiton tem 29 anos e faz entregas por aplicativo em Belo Horizonte. Em um mês bom, roda 200 horas e leva R$ 2.800. Não tem férias, décimo terceiro nem afastamento se quebrar o braço. Guarda R$ 200 por mês para o INSS como contribuinte individual, porque ninguém recolhe por ele. Quando o combustível sobe e o número de entregadores na cidade cresce, o valor por corrida cai — e ele não tem com quem negociar.","headline":"O que na renda de Cleiton depende dele e o que depende do vínculo e do mercado?","personagem":"Cleiton"}'::jsonb, NULL),
  ('cmsgcnb5f0033mv7uss5bpohm', 'cmsgcnayt0030mv7uud1tmv00', 2, 'quiz', 'Direitos ou competitividade?', '{"opcoes":[{"letra":"A","texto":"Nada: direitos trabalhistas são custo e sempre travam a competitividade.","correta":false,"feedback":"Direitos como férias, FGTS e limite de jornada foram conquistados ao longo do século XX e sustentam saúde, previdência e poder de compra. Reduzi-los a custo apaga metade da conta."},{"letra":"B","texto":"Os dois lados: o custo do vínculo para a empresa e o que o trabalhador perde sem proteção.","correta":true,"feedback":"É o núcleo do debate. Encargos pesam no caixa de quem contrata, e a ausência deles transfere o risco de doença, acidente e velhice para o trabalhador e para o sistema público."},{"letra":"C","texto":"Só o lado da empresa: se ela quebrar, ninguém tem emprego.","correta":false,"feedback":"A sobrevivência da empresa importa, mas não encerra a discussão. Competir cortando proteção costuma empurrar o custo para a saúde pública e para a previdência, ou seja, para todo mundo."}],"headline":"Uma empresa diz que precisa reduzir encargos trabalhistas para competir com concorrentes que operam com equipes informais. O que esse debate exige avaliar?"}'::jsonb, NULL),
  ('cmsgcnb5f0034mv7urrmvcatk', 'cmsgcnayt0030mv7uud1tmv00', 3, 'input', 'Quanto da renda é informal', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"🧾","label":"Da renda da casa, sem carteira","placeholder":"40"}],"headline":"Da renda que entra na sua casa hoje, quanto vem de trabalho sem carteira, freela ou bico?","subtitulo":"Uma estimativa aproximada basta; o objetivo é enxergar a proporção, não acertar o número."}'::jsonb, NULL),
  ('cmsgcnb5f0035mv7uhz5pz9fu', 'cmsgcnayt0030mv7uud1tmv00', 4, 'resultado', 'O que está exposto', '{"faixas":[{"cor":"green","condicao":"valor == 0","mensagem":"Toda a renda da casa passa por vínculo formal. A proteção está dada, mas a dependência de um único contratante também é risco: vale saber quantos meses a casa aguenta sem esse salário."},{"cor":"yellow","condicao":"valor <= 40","mensagem":"Parte da renda oscila e não gera direito nenhum. Uma reserva de emergência e a contribuição própria ao INSS cobrem justamente essa fatia."},{"cor":"yellow","condicao":"resto","mensagem":"A maior parte da renda depende de trabalho sem proteção. Aqui, reserva e previdência não são luxo: substituem férias, licença e seguro-desemprego que ninguém vai pagar."}],"formula":"valor_direto","headline":"<strong>{valorCru}%</strong> da renda da casa vem sem proteção","insightDinamico":"Você estimou que {valorCru} da renda da sua casa vem de trabalho sem proteção formal. Esse número não mede o esforço de ninguém: mede exposição. Renda informal costuma variar mais de mês para mês, não gera FGTS nem seguro-desemprego e só conta para a aposentadoria se alguém recolher por conta própria. Saber a proporção é o primeiro passo para decidir o que dá para blindar.\n\nPróximo passo: Some quanto a sua renda variou nos últimos três meses e anote o pior mês."}'::jsonb, NULL),
  ('cmsgcnbpb0037mv7umhickl3q', 'cmsgcnbin0036mv7ur91o322s', 0, 'conceito', 'Empreender é comportamento', '{"corpo":"Empreender não começa com abrir empresa. Começa com um comportamento: notar um problema que incomoda outras pessoas, testar uma solução pequena antes de investir muito, aceitar risco calculado e recrutar quem faz melhor que você. Esse comportamento vale dentro de um emprego com carteira assinada, num projeto de bairro ou numa loja. Muda a escala, não a lógica.","headline":"Empreender é um jeito de agir, não um tipo de CNPJ."}'::jsonb, NULL),
  ('cmsgcnbpb0038mv7up3musl8d', 'cmsgcnbin0036mv7ur91o322s', 1, 'cenario', 'O teste de R$ 18', '{"linhas":[{"tipo":"saldo","label":"Ferramentas","valor":0,"valorTexto":"emprestadas de um vizinho"},{"tipo":"entrada","label":"Faturou no sábado","valor":100},{"tipo":"saida","label":"Gastou em peças","valor":18},{"tipo":"saldo","label":"Clientes atendidos","valor":0,"valorTexto":"quatro, a R$ 25 cada"}],"rodape":"Rejane tem 17 anos e percebeu que ninguém no bairro conserta bicicleta depois das 18h. Antes de comprar ferramentas caras, ela pegou emprestado o kit de um vizinho, avisou em dois grupos de mensagem e atendeu quatro pessoas num sábado, cobrando R$ 25 por reparo. Faturou R$ 100 e gastou R$ 18 em peças. O teste custou pouco e respondeu à pergunta que importava: existe gente disposta a pagar por isso?","headline":"O que o teste de R$ 18 comprou que uma planilha de projeções não compraria?","personagem":"Rejane"}'::jsonb, NULL),
  ('cmsgcnbpb0039mv7uda1lur52', 'cmsgcnbin0036mv7ur91o322s', 2, 'quiz', 'Cultural, social ou comercial', '{"opcoes":[{"letra":"A","texto":"Nada de relevante: todo negócio depende só de vender bem.","correta":false,"feedback":"Vender importa nos três, mas a origem do dinheiro é diferente. Um projeto social costuma combinar doação, edital e contrapartida, e isso muda quem ele precisa convencer."},{"letra":"B","texto":"De onde vem a receita e a quem cada um presta contas.","correta":true,"feedback":"É isso. O sarau depende de público e patrocínio, o projeto social de editais e doadores, a loja de margem e giro — e cada fonte cobra uma prestação de contas diferente."},{"letra":"C","texto":"O cultural e o social não precisam de controle financeiro, só o comercial.","correta":false,"feedback":"Os três precisam saber custo, receita e caixa. Projetos culturais e sociais costumam ter exigência de prestação de contas ainda mais rígida, porque usam recurso de terceiros."}],"headline":"Três pessoas querem tocar um negócio próprio: um sarau pago, um projeto de reforço escolar gratuito e uma loja de doces. O que muda entre eles?"}'::jsonb, NULL),
  ('cmsgcnbpb003amv7unodq27vu', 'cmsgcnbin0036mv7ur91o322s', 3, 'input', 'Sua próxima ideia', '{"campos":[{"id":"valor","tipo":"faixa","emoji":"🧪","label":"Natureza da sua próxima ideia","opcoes":[{"label":"Cultural: oficina, evento, produto artístico","valor":"1"},{"label":"Social: resolver um problema da comunidade","valor":"2"},{"label":"Comercial: vender produto ou serviço","valor":"3"},{"label":"Dentro de onde já estou","valor":"4"}]}],"headline":"Se você fosse testar uma ideia nos próximos 30 dias, de que natureza ela seria?","subtitulo":"Não precisa ser a ideia definitiva; vale a que você testaria com o que já tem hoje."}'::jsonb, NULL),
  ('cmsgcnbpb003bmv7utugr7n1f', 'cmsgcnbin0036mv7ur91o322s', 4, 'resultado', 'Do teste ao próximo passo', '{"faixas":[{"cor":"green","condicao":"valor == 3","mensagem":"Sua primeira pergunta é se alguém paga um preço que cobre o custo. Descubra isso com quatro clientes reais antes de investir em estoque."},{"cor":"green","condicao":"valor <= 2","mensagem":"Aqui a receita quase nunca vem só de quem usa. Mapeie desde já editais, parceiros e contrapartidas, porque cada fonte traz uma exigência de prestação de contas."},{"cor":"green","condicao":"resto","mensagem":"Empreender dentro de uma organização é o caminho de menor risco pessoal. Escolha um processo que trava toda semana e proponha a mudança com número antes e depois."}],"formula":"valor_direto","headline":"Teste pequeno responde o que projeção nenhuma responde","insightDinamico":"Você escolheu {valorCru}. Seja qual for a natureza, o próximo movimento é o mesmo: reduzir a ideia a um teste que caiba em uma semana e em pouco dinheiro. Quem empreende bem não aposta tudo de uma vez — troca dúvida por informação barata. O que muda entre as naturezas é de onde vem a receita e para quem você presta contas.\n\nPróximo passo: Descreva a ideia em uma frase e mostre para três pessoas que têm esse problema."}'::jsonb, NULL),
  ('cmsgcnc9a003dmv7uqgu5vmt1', 'cmsgcnc2g003cmv7ufhdnncg5', 0, 'conceito', 'Os quatro números do negócio', '{"corpo":"Todo negócio cabe em quatro números. Receita é o que entra. Custo variável cresce a cada venda: ingrediente, embalagem, taxa da maquininha. Custo fixo você paga mesmo vendendo zero: aluguel, luz, salários. A margem de contribuição é o que sobra de cada venda depois do custo variável — é ela que precisa pagar o custo fixo antes de virar lucro.","headline":"A margem paga o custo fixo. O que sobra depois disso é lucro."}'::jsonb, NULL),
  ('cmsgcnc9a003emv7ufohg5nvd', 'cmsgcnc2g003cmv7ufhdnncg5', 1, 'cenario', 'A marmitaria de Solange', '{"linhas":[{"tipo":"entrada","label":"Receita do mês — 600 marmitas a R$ 20","valor":12000},{"tipo":"saida","label":"Custo variável","valor":6600},{"tipo":"saida","label":"Custo fixo","valor":4200},{"tipo":"saldo","label":"Lucro — 10% da receita","valor":1200},{"tipo":"saldo","label":"Desperdício de legumes","valor":0,"valorTexto":"8% por compra mal dimensionada"}],"rodape":"Solange tem 41 anos e faz 600 marmitas por mês a R$ 20: R$ 12.000 de receita. Cada marmita custa R$ 11 em ingredientes e embalagem, o que dá R$ 6.600 de custo variável. Aluguel, gás, energia e a ajudante somam R$ 4.200 fixos. Sobram R$ 1.200 de lucro, 10% da receita. Ela joga fora cerca de 8% dos legumes por compra mal dimensionada e gasta R$ 380 por mês em embalagem descartável.","headline":"Onde mexer primeiro para o lucro subir sem empurrar o custo para o meio ambiente?","personagem":"Solange"}'::jsonb, NULL),
  ('cmsgcnc9a003fmv7ugrsvmc3t', 'cmsgcnc2g003cmv7ufhdnncg5', 2, 'quiz', 'Qual melhoria propor', '{"opcoes":[{"letra":"A","texto":"Demitir a ajudante e absorver o serviço sozinha.","correta":false,"feedback":"Corta custo fixo no papel, mas tira uma renda do bairro e joga a jornada inteira sobre ela. Se a produção cair junto, o lucro pode nem subir."},{"letra":"B","texto":"Reduzir os 8% de perda de legumes ajustando a compra semanal.","correta":true,"feedback":"Insumo que não vai para o lixo vira margem direta, sem aumentar preço nem cortar gente. E menos comida descartada reduz o custo ambiental da operação."},{"letra":"C","texto":"Subir o preço da marmita para R$ 24.","correta":false,"feedback":"Pode funcionar, mas é a saída que mais depende de o cliente aceitar: em marmita, quatro reais a mais costumam derrubar o volume. Mexer no que se controla vem antes."}],"headline":"Solange quer aumentar o lucro. Ela pode subir o preço, cortar o desperdício de insumo ou demitir a ajudante. Qual proposta ataca custo sem transferir prejuízo?"}'::jsonb, NULL),
  ('cmsgcnc9a003gmv7udehgcwa9', 'cmsgcnc2g003cmv7ufhdnncg5', 3, 'input', 'Quanto dá para cortar', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"♻️","label":"Corte proposto por mês","placeholder":"R$ 400"}],"headline":"Quanto por mês você propõe cortar em desperdício e embalagem descartável sem reduzir a produção?","subtitulo":"Uma estimativa serve: pense em quanto dos 8% de perda e dos R$ 380 de embalagem dá para reduzir."}'::jsonb, NULL),
  ('cmsgcnc9a003hmv7u5rd87t5m', 'cmsgcnc2g003cmv7ufhdnncg5', 4, 'resultado', 'O efeito no lucro', '{"faixas":[{"cor":"green","condicao":"valor < 200","mensagem":"Parece pouco, mas R$ 150 por mês são R$ 1.800 no ano, sem depender de o cliente aceitar preço maior. Meça a perda por uma semana antes de mudar a compra."},{"cor":"green","condicao":"valor <= 500","mensagem":"Uma economia nessa faixa aumenta o lucro entre 17% e 42% sem tocar no preço. Compare o custo por unidade da embalagem descartável com o de uma opção retornável ou compostável."},{"cor":"yellow","condicao":"resto","mensagem":"Acima de R$ 500 a estimativa fica otimista: a embalagem inteira custa R$ 380 por mês. Confirme com nota fiscal e com a pesagem do que vai para o lixo antes de contar com esse ganho."}],"formula":"valor_direto","headline":"<strong>R$ {valor}</strong> por mês saindo do desperdício","insightDinamico":"Com {valor} por mês a menos em desperdício e embalagem, esse valor cai direto no lucro de R$ 1.200 — sem vender uma marmita a mais e sem cortar a ajudante. É a melhoria mais barata do orçamento: mexe no custo variável, que Solange controla, e diminui o lixo. Preço e quadro de gente entram depois, se a conta ainda não fechar.\n\nPróximo passo: Pese por uma semana o que vai para o lixo e converta em reais."}'::jsonb, NULL),
  ('cmsgcnct0003jmv7ulcbkvr57', 'cmsgcncme003imv7ugx7tx3c3', 0, 'conceito', 'A engrenagem tem quatro peças', '{"corpo":"A economia é feita de gente decidindo. Produtores criam bens e serviços e contratam. Vendedores conectam quem produz a quem compra e definem preço. Compradores escolhem onde gastar e, com isso, dizem o que vale a pena existir. O governo arrecada, gasta, contrata e define regras. Cada decisão de um muda o campo de jogo dos outros — inclusive o seu.","headline":"Você é um agente econômico, não só um espectador do noticiário."}'::jsonb, NULL),
  ('cmsgcnct1003kmv7uopnb76ln', 'cmsgcncme003imv7ugx7tx3c3', 1, 'cenario', 'A padaria e o bairro', '{"linhas":[{"tipo":"saldo","label":"Fábrica da região","valor":0,"valorTexto":"demitiu 200 pessoas"},{"tipo":"saldo","label":"Faturamento da padaria","valor":0,"valorTexto":"caiu 18% em dois meses"},{"tipo":"saldo","label":"O que mudou na prateleira","valor":0,"valorTexto":"pão de queijo de R$ 6 → pão francês de R$ 1"},{"tipo":"saldo","label":"Clínica nova na mesma rua","valor":0,"valorTexto":"15 vagas de salário alto"}],"rodape":"Elaine, 41 anos, tem uma padaria num bairro de 3 mil moradores. Uma fábrica da região demitiu 200 pessoas e, em dois meses, o faturamento dela caiu 18%. Ninguém parou de comer: as pessoas trocaram o pão de queijo de R$ 6 pelo pão francês de R$ 1. Na mesma rua abriu uma clínica com 15 vagas de salário alto, e o café expresso passou a sair mais. A renda total do bairro quase não mudou. O que ela vende, sim.","headline":"Se a soma da renda é quase a mesma, por que o consumo do bairro mudou tanto?","personagem":"Elaine"}'::jsonb, NULL),
  ('cmsgcnct1003lmv7uhsjhkpxx', 'cmsgcncme003imv7ugx7tx3c3', 2, 'quiz', 'Mesmo bolo, fatias diferentes', '{"opcoes":[{"letra":"A","texto":"Nada relevante: o que importa é o total, não como ele se reparte.","correta":false,"feedback":"O total não determina o consumo. Renda espalhada entre muita gente sustenta padaria, farmácia e transporte; concentrada, esse gasto básico encolhe."},{"letra":"B","texto":"Na primeira, mais gente compra itens básicos; na segunda, o gasto se concentra em menos pessoas e em itens mais caros.","correta":true,"feedback":"É isso. A mesma renda total gera consumo, empregos e negócios diferentes conforme quem a recebe."},{"letra":"C","texto":"A segunda cidade terá mais comércio, porque dinheiro concentrado circula mais rápido.","correta":false,"feedback":"Não existe essa regra. Quem ganha muito tende a poupar ou investir uma fatia maior da renda, e parte desse dinheiro pode nem circular na cidade."}],"headline":"Duas cidades têm a mesma renda total. Na primeira, ela é bem distribuída; na segunda, concentrada em poucas famílias. O que tende a mudar?"}'::jsonb, NULL),
  ('cmsgcnct1003mmv7usedrbo9k', 'cmsgcncme003imv7ugx7tx3c3', 3, 'input', 'Onde seu dinheiro para', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"🏘️","label":"Gasto no comércio do bairro","placeholder":"R$ 350"}],"headline":"Pensando no último mês, quanto do seu dinheiro ficou em comércios do seu próprio bairro ou cidade?","subtitulo":"Uma estimativa de cabeça resolve; não é preciso somar recibos."}'::jsonb, NULL),
  ('cmsgcnct1003nmv7u7m8bnk67', 'cmsgcncme003imv7ugx7tx3c3', 4, 'resultado', 'Seu gasto é renda de alguém', '{"faixas":[{"cor":"yellow","condicao":"valor < 200","mensagem":"Boa parte do seu consumo sai do bairro: compras on-line e redes grandes levam esse dinheiro para outro lugar. Não é errado, mas muda quem recebe."},{"cor":"green","condicao":"valor <= 800","mensagem":"Seu gasto está dividido entre o comércio local e o de fora, que é o padrão da maioria das famílias urbanas."},{"cor":"green","condicao":"resto","mensagem":"Quase tudo que você gasta vira renda perto de onde você mora. Isso sustenta empregos vizinhos e costuma custar um pouco mais caro que comprar de grandes redes."}],"formula":"valor_direto","headline":"<strong>R$ {valor}</strong> viraram renda perto de você","insightDinamico":"Os {valor} que você estimou não sumiram: viraram renda de quem vendeu, salário de quem atendeu e tributo que financia serviço público. Multiplique isso por milhares de pessoas e você tem a economia local. Como distribuir melhor essa renda — via imposto, salário, crédito ou crescimento — é uma disputa política real, com bons argumentos de mais de um lado.\n\nPróximo passo: Escolha uma compra da semana e descubra quem produz, quem vende e quanto fica com cada um."}'::jsonb, NULL),
  ('cmsgcndcv003pmv7ubpy1sefo', 'cmsgcnd63003omv7uk6756ij0', 0, 'conceito', 'O que o preço já cobrou', '{"corpo":"Tributo é o que financia escola, SUS, estrada e polícia. Ele vem por dois caminhos. O direto incide sobre renda e patrimônio, como o Imposto de Renda e o IPTU: quem tem mais, paga mais. O indireto vem embutido no preço do que você compra e é igual para todo mundo, independentemente da renda — por isso pesa proporcionalmente mais em quem ganha menos.","headline":"Isso se chama regressividade: é fato medido. O que fazer a respeito é debate aberto."}'::jsonb, NULL),
  ('cmsgcndcw003qmv7ujo351gn9', 'cmsgcnd63003omv7uk6756ij0', 1, 'cenario', 'O fone e a nota fiscal', '{"linhas":[{"tipo":"entrada","label":"Freela de edição","valor":400},{"tipo":"saida","label":"Fone comprado","valor":250},{"tipo":"saida","label":"Tributo embutido no preço","valor":90},{"tipo":"saldo","label":"O mesmo tributo, para quem ganha R$ 22 mil","valor":0,"valorTexto":"0,4% da renda, contra 22%"}],"rodape":"Berenice, 17 anos, recebeu R$ 400 por um freela de edição de vídeo e comprou um fone de R$ 250. Na nota fiscal, a linha de tributos apontava cerca de R$ 90 embutidos no preço — valor de exemplo, que varia por produto e por estado. No mesmo dia, Regina, que ganha R$ 22.000 por mês, comprou o mesmo fone e pagou os mesmos R$ 90. Para Berenice, aquilo foi 22% da renda do freela. Para Regina, 0,4%.","headline":"O imposto pago foi idêntico. O peso foi o mesmo?","personagem":"Berenice"}'::jsonb, NULL),
  ('cmsgcndcw003rmv7u7ilf9qfc', 'cmsgcnd63003omv7uk6756ij0', 2, 'quiz', 'Venda sem nota', '{"opcoes":[{"letra":"A","texto":"Ninguém perde: o dinheiro fica com a loja e circula do mesmo jeito.","correta":false,"feedback":"Circula, mas fora do caixa público. Falta receita para o serviço que aquela arrecadação bancaria, e o buraco é coberto por quem não tem como deixar de pagar."},{"letra":"B","texto":"Falta receita para serviços públicos, e a conta tende a sobrar para quem não consegue sonegar.","correta":true,"feedback":"Sim: quem tem imposto descontado na fonte ou compra com nota sustenta a parte que faltou. É daí que nascem propostas opostas — uns querem fiscalizar e cobrar mais de quem tem renda alta, outros querem simplificar o sistema e reduzir a carga para que sonegar deixe de compensar."},{"letra":"C","texto":"O comprador economiza, porque o tributo some da conta dele.","correta":false,"feedback":"Em geral o preço não cai por isso: a diferença fica com o vendedor. E, sem nota, você perde a prova de compra para garantia e troca."}],"headline":"Uma loja vende sem emitir nota e não recolhe o tributo daquela venda. Qual é o efeito mais direto?"}'::jsonb, NULL),
  ('cmsgcndcw003smv7utx1un2l1', 'cmsgcnd63003omv7uk6756ij0', 3, 'input', 'Ferramentas de fiscalização', '{"campos":[{"id":"valor","tipo":"faixa","emoji":"🔎","label":"Ferramentas que você já usou","opcoes":[{"label":"Nenhum deles","valor":"0"},{"label":"Um deles","valor":"1"},{"label":"Dois deles","valor":"2"},{"label":"Os três","valor":"3"}]}],"headline":"Quais destes você já usou: portal da transparência, pedido pela Lei de Acesso à Informação, consulta pública do Banco Central?","subtitulo":"Vale a estimativa: se você já abriu um portal de gastos por curiosidade, conta."}'::jsonb, NULL),
  ('cmsgcndcw003tmv7uagc526ib', 'cmsgcnd63003omv7uk6756ij0', 4, 'resultado', 'Fiscalizar é parte do preço', '{"faixas":[{"cor":"yellow","condicao":"valor == 0","mensagem":"São três portas ainda fechadas. Uma consulta simples no portal do seu município costuma ser o caminho mais curto para abrir a primeira."},{"cor":"green","condicao":"valor <= 2","mensagem":"Você já sabe que os dados existem. O passo seguinte é comparar o que foi orçado, o que foi pago e o que ficou pronto — números que alimentam os dois lados do debate: quem considera a carga alta demais e quem considera a receita insuficiente para os serviços."},{"cor":"green","condicao":"resto","mensagem":"Você usa o instrumental completo. Divulgar o que encontrou costuma render mais efeito do que guardar o achado para si."}],"formula":"valor_direto","headline":"Fiscalizar é a parte do preço que quase ninguém cobra","insightDinamico":"Você marcou: {valorCru}. Os três canais são públicos e gratuitos: o portal da transparência mostra contratos e repasses, a Lei de Acesso à Informação obriga o órgão a responder em até 20 dias e o Banco Central abre consulta antes de mudar regras que afetam sua conta. Fiscalizar não resolve a discussão sobre quanto e de quem cobrar — mas dá base para participar dela.\n\nPróximo passo: Procure no portal da transparência do seu município quanto foi gasto na escola mais próxima."}'::jsonb, NULL),
  ('cmsgcne67003vmv7u5q9n26bn', 'cmsgcndpv003umv7ufeji4tc6', 0, 'conceito', 'Cinco números do noticiário', '{"corpo":"Cinco números resumem o noticiário. Inflação: seu dinheiro compra menos a cada mês. Selic: a taxa básica que encarece o crédito e melhora o rendimento da renda fixa. Desemprego alto: mais gente disputando a vaga ou o freela que você quer. PIB: o tamanho do que o país produz, e o que sobra para contratar. Dívida pública: juro do governo disputando espaço com escola e saúde no orçamento.","headline":"Nenhum deles é abstrato: cada um chega ao seu bolso por algum caminho."}'::jsonb, NULL),
  ('cmsgcne67003wmv7u10twrj8r', 'cmsgcndpv003umv7ufeji4tc6', 1, 'cenario', 'O dólar mexeu', '{"linhas":[{"tipo":"entrada","label":"US$ 600 quando o dólar valia R$ 5,20","valor":3120},{"tipo":"entrada","label":"Os mesmos US$ 600 com o dólar a R$ 5,90","valor":3540},{"tipo":"saida","label":"Notebook importado, antes","valor":6000},{"tipo":"saida","label":"…e depois","valor":6700}],"rodape":"Vinícius, 27 anos, edita vídeo para um cliente nos Estados Unidos e recebe US$ 600 por mês. Quando fechou o contrato, o dólar valia R$ 5,20 — R$ 3.120. Meses depois, com o dólar a R$ 5,90, os mesmos US$ 600 viraram R$ 3.540, sem ele cobrar um centavo a mais. No mesmo período, o notebook importado que ele queria subiu de R$ 6.000 para R$ 6.700. Valores de exemplo, não a cotação de hoje.","headline":"A alta do dólar foi boa ou ruim para Vinícius — e para quem não recebe em dólar?","personagem":"Vinícius"}'::jsonb, NULL),
  ('cmsgcne68003xmv7u9bs4epkr', 'cmsgcndpv003umv7ufeji4tc6', 2, 'quiz', 'Quando a moeda oscila', '{"opcoes":[{"letra":"A","texto":"Todo mundo perde poder de compra, sem exceção.","correta":false,"feedback":"Quem exporta ou recebe em moeda estrangeira passa a receber mais reais. O efeito depende de que lado da troca você está."},{"letra":"B","texto":"Importado e viagem ficam mais caros; quem exporta ou recebe em moeda estrangeira ganha mais reais.","correta":true,"feedback":"Isso. E o encarecimento de combustível e insumos importados costuma chegar aos preços internos algumas semanas depois."},{"letra":"C","texto":"Nada muda para quem só compra produto nacional.","correta":false,"feedback":"Muda: trigo, fertilizante, chip e combustível são cotados em dólar e entram no custo de coisas fabricadas aqui."}],"headline":"Uma crise geopolítica no exterior faz investidores correrem para o dólar, que sobe frente ao real. No Brasil, o efeito imediato é:"}'::jsonb, NULL),
  ('cmsgcne68003ymv7ux8f52a9s', 'cmsgcndpv003umv7ufeji4tc6', 3, 'input', 'Sua leitura da inflação', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"🌡️","label":"Sua leitura da inflação, 12 meses","placeholder":"6"}],"headline":"Na sua percepção, quanto os preços subiram no Brasil nos últimos 12 meses, em porcentagem?","subtitulo":"Chute pela sua experiência de compra; não precisa consultar índice nenhum."}'::jsonb, NULL),
  ('cmsgcne68003zmv7u5sr6ajh4', 'cmsgcndpv003umv7ufeji4tc6', 4, 'resultado', 'Seu número contra o mundo', '{"faixas":[{"cor":"green","condicao":"valor < 4","mensagem":"Sua percepção está na faixa de países de inflação baixa. Se a sua cesta subiu menos que a média, ela provavelmente é diferente da cesta média brasileira."},{"cor":"green","condicao":"valor <= 12","mensagem":"É a faixa em que o Brasil costuma se mover. Vale comparar outro dado: o juro do rotativo do cartão aqui está entre os mais altos do mundo, o que faz a dívida das famílias crescer rápido."},{"cor":"yellow","condicao":"resto","mensagem":"Você sentiu mais do que a média costuma registrar. Índice é média de muitos itens; aluguel, transporte e alimentação podem ter subido bem mais na sua conta."}],"formula":"valor_direto","headline":"Você sentiu <strong>{valorCru}%</strong> em 12 meses","insightDinamico":"Você estimou {valorCru}. Como referência histórica, países ricos costumam operar perto de 2% ao ano, o Brasil orbitou entre 4% e 10% nas últimas duas décadas, e casos como Argentina e Turquia passaram de 40%. Quanto maior a inflação, mais alta tende a ser a Selic para segurá-la — e crédito caro esfria o PIB e o emprego, e encarece a dívida pública que o país precisa rolar.\n\nPróximo passo: Compare o preço de três itens que você compra sempre com o que pagava há um ano."}'::jsonb, NULL)
