-- Dados de SISTEMA do Finlow — o conteúdo do produto, igual para todo mundo.
-- GERADO por scripts/exportar-banco.mts em 2026-08-10, direto do banco de produção.
--
-- Retrato desta exportação:
--   67 módulos (43 de público "adulto", 24 de público "em")
--   386 telas
--   33 indicadores
--
-- NENHUMA linha de usuário aqui: nem transação, nem conta, nem e-mail. O motivo
-- está no cabeçalho de scripts/exportar-banco.mts.
--
-- Para restaurar: rode 01, 02 e depois este. É idempotente (ON CONFLICT DO
-- UPDATE), então rodar de novo atualiza em vez de duplicar, e não apaga
-- progresso de ninguém.

BEGIN;

-- Modulo: 67 linha(s)
ON CONFLICT ("id") DO UPDATE SET "titulo" = EXCLUDED."titulo", "tipoPerfil" = EXCLUDED."tipoPerfil", "ordem" = EXCLUDED."ordem", "slug" = EXCLUDED."slug", "subtitulo" = EXCLUDED."subtitulo", "duracaoMin" = EXCLUDED."duracaoMin", "tags" = EXCLUDED."tags", "thumbnail" = EXCLUDED."thumbnail", "nivel" = EXCLUDED."nivel", "situacoes" = EXCLUDED."situacoes", "publico" = EXCLUDED."publico", "blocoId" = EXCLUDED."blocoId", "blocoRotulo" = EXCLUDED."blocoRotulo", "ehRevisao" = EXCLUDED."ehRevisao", "pontos" = EXCLUDED."pontos", "preRequisitoSlug" = EXCLUDED."preRequisitoSlug", "xp" = EXCLUDED."xp";

-- Tela: 386 linha(s)
ON CONFLICT ("id") DO UPDATE SET "moduloId" = EXCLUDED."moduloId", "ordem" = EXCLUDED."ordem", "tipo" = EXCLUDED."tipo", "label" = EXCLUDED."label", "conteudo" = EXCLUDED."conteudo", "mediacao" = EXCLUDED."mediacao";

-- Indicador: 33 linha(s)
ON CONFLICT ("chave") DO UPDATE SET "valor" = EXCLUDED."valor", "rotulo" = EXCLUDED."rotulo", "numero" = EXCLUDED."numero", "fonte" = EXCLUDED."fonte", "apuradoEm" = EXCLUDED."apuradoEm", "atualizadoEm" = EXCLUDED."atualizadoEm";

COMMIT;
